/* Shiv Luminoso - Bhaktamar Stotra. Generated content: do not retype or "improve" the religious text. */
window.LUZ_DATA = {"imgBase":"./","verses":[{"n":1,"sa":["भक्तामर-प्रणत-मौलि-मणि-प्रभाणा-","मुद्योतकं दलित-पाप-तमो-वितानम्।","सम्यक्प्रणम्य जिन-पाद-युगं युगादा-","वालम्बनं भव-जले पततां जनानाम् ।।१।।"],"pron":["bhaktāmara-praṇata-mauli-maṇi-prabhāṇā-","mudyotakaṃ dalita-pāpa-tamo-vitānam|","samyakpraṇamya jina-pāda-yugaṃ yugādā-","vālambanaṃ bhava-jale patatāṃ janānām ||1||"],"title":{"en":"A humble beginning","hi":"विनम्र आरंभ","es":"Un comienzo humilde","pt":"Um começo humilde","it":"Un umile inizio","gu":"નમ્ર શરૂઆત"},"meaning":{"en":"I bow at the feet of the Jina. His light clears away the darkness of wrongdoing and holds up every soul struggling in the ocean of worldly life.","hi":"मैं जिनेन्द्र के चरणों में प्रणाम करता हूँ। उनका प्रकाश पाप के अंधकार को मिटाता है और संसार-सागर में संघर्ष करती आत्माओं को सहारा देता है।","es":"Me inclino a los pies del Jina. Su luz disipa la oscuridad de las faltas y sostiene a todas las almas que luchan en el océano de la vida mundana.","pt":"Inclino-me aos pés do Jina. Sua luz dissipa a escuridão do mal e ampara toda alma que luta no oceano da vida mundana.","it":"Mi inchino ai piedi del Jina. La sua luce dissipa l’oscurità del male e sostiene ogni anima che lotta nell’oceano della vita mondana.","gu":"હું જિનના ચરણોમાં વંદન કરું છું. તેમનો પ્રકાશ પાપના અંધકારને દૂર કરે છે અને સંસારસાગરમાં સંઘર્ષ કરતા દરેક જીવને આધાર આપે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो अरिहंताणं णमो जिणाणं ह्रां ह्रीं ह्रूं ह्रौं ह्रः (असिआउसा) अप्रतिचक्रे फट् विचक्राय झ्रौं झ्रौं नमः स्वाहा।","iast":"Oṃ hrīṃ arhaṃ ṇamo arihaṃtāṇaṃ ṇamo jiṇāṇaṃ hrāṃ hrīṃ hrūṃ hrauṃ hraḥ (asiāusā) apraticakre phaṭ vicakrāya jhrauṃ jhrauṃ namaḥ svāhā"}],"mantra":[{"dev":"ॐ ह्रां ह्रीं ह्रूं श्रीं क्लीं ब्लूं क्रौं ॐ ह्रीं नमः स्वाहा।","iast":"Oṃ hrāṃ hrīṃ hrūṃ śrīṃ klīṃ blūṃ krauṃ oṃ hrīṃ namaḥ svāhā"}],"method":{"en":"Wearing white clothes, sit on a white seat facing east. With a pure heart, recite the first verse, the riddhi and the mantra 108 times every day, until one hundred thousand repetitions are complete.","es":"Vestido de blanco, siéntate en un asiento blanco mirando hacia el este. Con corazón puro, recita cada día 108 veces el primer verso, la riddhi y el mantra, hasta completar cien mil repeticiones.","hi":"श्वेत वस्त्र पहनकर सफेद आसन पर पूर्व दिशा की ओर मुख करके पवित्र भाव से प्रतिदिन एक सौ आठ बार प्रथम काव्य ऋद्धि तथा मंत्र का आराधन करते हुए एक लाख जप सम्पन्न करना चाहिए।","pt":"Vestindo roupas brancas, sente-se em um assento branco voltado para o leste. Com o coração puro, recite todos os dias o primeiro verso, o riddhi e o mantra 108 vezes, até completar cem mil repetições.","it":"Indossando abiti bianchi, siediti su un sedile bianco rivolto a est. Con il cuore puro, recita ogni giorno il primo verso, il riddhi e il mantra 108 volte, fino a completare centomila ripetizioni.","gu":"સફેદ વસ્ત્રો પહેરીને, પૂર્વ તરફ મુખ રાખી સફેદ આસન પર બેસો. શુદ્ધ હૃદયે દરરોજ પહેલો શ્લોક, ઋદ્ધિ અને મંત્ર 108 વાર બોલો, જ્યાં સુધી એક લાખ જાપ પૂરા ન થાય."},"benefit":{"en":"First: write the yantra with saffron on birch bark (bhojpatra), pass fragrant incense smoke over it and keep it with you. Troubles are destroyed, good fortune is gained and wealth (Lakshmi) comes. This mantra is greatly powerful.","es":"Primero: escribe el yantra con azafrán sobre corteza de abedul (bhojpatra), pasa sobre él el humo de incienso aromático y consérvalo contigo. Se destruyen las perturbaciones, se alcanza la buena fortuna y llega la prosperidad (Lakshmi). Este mantra es muy poderoso.","hi":"प्रथम, यंत्र को भोजपत्र पर केशर से लिखकर सुगन्धित धूप की धूनी देकर अपने पास रखने से उपद्रव नष्ट होते हैं, सौभाग्य की प्राप्ति होती है और लक्ष्मी का लाभ होता है। यह मंत्र महाप्रभावक है।","pt":"Primeiro: escreva o yantra com açafrão em casca de bétula (bhojpatra), passe sobre ele a fumaça de incenso perfumado e mantenha-o consigo. As aflições são destruídas, a boa fortuna é alcançada e a riqueza (Lakshmi) chega. Este mantra é imensamente poderoso.","it":"Per prima cosa: scrivi lo yantra con lo zafferano su corteccia di betulla (bhojpatra), fai passare sopra il fumo di incenso profumato e tienilo con te. Le difficoltà vengono distrutte, si ottiene buona sorte e arriva la ricchezza (Lakshmi). Questo mantra è di grandissima potenza.","gu":"પ્રથમ: ભોજપત્ર પર કેસરથી યંત્ર લખો, તેના પર સુગંધિત ધૂપનો ધુમાડો ફેરવો અને તેને પોતાની પાસે રાખો. વિપત્તિઓ નાશ પામે છે, સૌભાગ્ય પ્રાપ્ત થાય છે અને લક્ષ્મી (ધન) આવે છે. આ મંત્ર અત્યંત શક્તિશાળી છે."}},{"n":2,"sa":["यः संस्तुतः सकल-वाङ्मय-तत्त्वबोधा-","दुद्भूत-बुद्धि-पटुभिः सुरलोक-नाथैः।","स्तोत्रैर्जगत्त्रितय-चित्त-हरै-रुदारैः,","स्तोष्ये किलाहमपि तं प्रथमं जिनेन्द्रम् ।।२।।"],"pron":["yaḥ saṃstutaḥ sakala-vāṅmaya-tattvabodhā-","dudbhūta-buddhi-paṭubhiḥ suraloka-nāthaiḥ|","stotrairjagattritaya-citta-harai-rudāraiḥ,","stoṣye kilāhamapi taṃ prathamaṃ jinendram ||2||"],"title":{"en":"Joining the song","hi":"गीत में सम्मिलित होना","es":"Unirse al canto","pt":"Juntando-se ao canto","it":"Unirsi al canto","gu":"સ્તુતિમાં જોડાવું"},"meaning":{"en":"Gods and sages, wise beyond measure, have already praised the first Jina in grand hymns. I, too, will sing.","hi":"देवों और ऋषियों ने, अपनी अपार बुद्धि से, प्रथम जिनेन्द्र की महान स्तुतियाँ पहले ही गाई हैं। मैं भी गाऊँगा।","es":"Dioses y sabios, de sabiduría inmensa, ya han alabado al primer Jina con grandes himnos. Yo también cantaré.","pt":"Deuses e sábios, de sabedoria imensurável, já louvaram o primeiro Jina em grandes hinos. Eu também cantarei.","it":"Dèi e saggi, di sapienza immensa, hanno già lodato il primo Jina in grandi inni. Anch’io canterò.","gu":"અપાર જ્ઞાની દેવો અને ઋષિઓએ પ્રથમ જિનની સ્તુતિ મહાન સ્તોત્રોમાં કરી જ છે. હું પણ ગાઈશ."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो ओहि जिणाणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo ohi jiṇāṇaṃ"}],"mantra":[{"dev":"ॐ ह्रीं श्रीं क्लीं ब्लूं नमः।","iast":"Oṃ hrīṃ śrīṃ klīṃ blūṃ namaḥ"}],"method":{"en":"Wearing black clothes and holding a black rosary (mala), sit on a black seat facing east and fold your legs into the staff posture (dandasana). For twenty-one or thirty days recite the riddhi and the mantra 108 times each day, or for seven days recite them 1,000 times each day.","es":"Vestido de negro y con un rosario (mala) negro, siéntate en un asiento negro mirando hacia el este y pliega las piernas en la postura del bastón (dandasana). Durante veintiún o treinta días recita la riddhi y el mantra 108 veces al día, o durante siete días recítalos 1.000 veces al día.","hi":"काले वस्त्र पहनकर काली माला लेकर, काले आसन पर पूर्व दिशा की ओर मुख करके दंडासन माँडकर इक्कीस या तीस दिन तक प्रतिदिन एक सौ आठ बार अथवा सात दिन तक प्रतिदिन एक हजार बार ऋद्धि तथा मंत्र का स्मरण करें।","pt":"Vestindo roupas pretas e segurando um rosário (mala) preto, sente-se em um assento preto voltado para o leste, com as pernas dobradas na postura do bastão (dandasana). Durante vinte e um ou trinta dias, recite o riddhi e o mantra 108 vezes por dia, ou durante sete dias recite-os 1.000 vezes por dia.","it":"Indossando abiti neri e tenendo un rosario (mala) nero, siediti su un sedile nero rivolto a est, con le gambe piegate nella posizione del bastone (dandasana). Per ventuno o trenta giorni recita il riddhi e il mantra 108 volte al giorno, oppure per sette giorni recitali 1.000 volte al giorno.","gu":"કાળાં વસ્ત્રો પહેરી, કાળી માળા હાથમાં લઈ, પૂર્વ તરફ મુખ રાખી કાળા આસન પર બેસો અને પગને દંડાસનની મુદ્રામાં વાળો. એકવીસ અથવા ત્રીસ દિવસ સુધી રોજ ઋદ્ધિ અને મંત્ર 108 વાર બોલો, અથવા સાત દિવસ સુધી રોજ 1,000 વાર બોલો."},"benefit":{"en":"Keeping the yantra with you and recalling the second verse together with the riddhi and mantra destroys enemies and headaches, and removes the effect of drishtibandh, that is, the practice that clouds the sight of those who look. The devotee should eat only one meal a day until the mantra practice is complete.","es":"Tener el yantra contigo y recordar el segundo verso junto con la riddhi y el mantra destruye a los enemigos y los dolores de cabeza, y disipa el efecto del drishtibandh, es decir, la práctica que nubla la vista de quienes miran. El devoto debe comer una sola vez al día hasta completar la práctica del mantra.","hi":"यंत्र को पास में रखने और द्वितीय काव्य एवं ऋद्धि मंत्र के स्मरण करने से शत्रु तथा सिर की पीड़ा नाश होती है, दृष्टिबन्ध अर्थात् वह क्रिया, जिससे देखने वालों की दृष्टि में भ्रम हो जाये, दूर होता है। आराधक को मंत्र साधन तक एकाशन करना चाहिए।","pt":"Mantendo o yantra consigo e recordando o segundo verso junto com o riddhi e o mantra, destroem-se os inimigos e as dores de cabeça, e remove-se o efeito do drishtibandh, isto é, a prática que obscurece a visão de quem olha. O devoto deve fazer apenas uma refeição por dia até concluir a prática do mantra.","it":"Tenendo con te lo yantra e ricordando il secondo verso insieme al riddhi e al mantra, si distruggono i nemici e il mal di testa, e si rimuove l’effetto del drishtibandh, cioè la pratica che offusca la vista di chi guarda. Il devoto deve fare un solo pasto al giorno finché la pratica del mantra non è completata.","gu":"યંત્ર પોતાની પાસે રાખી, ઋદ્ધિ અને મંત્ર સાથે બીજા શ્લોકનું સ્મરણ કરવાથી શત્રુઓ અને માથાનો દુખાવો નાશ પામે છે, તથા દૃષ્ટિબંધનો પ્રભાવ, એટલે કે જોનારની નજરને ઝાંખી કરી દેનાર પ્રયોગનો, દૂર થાય છે. મંત્રસાધના પૂરી ન થાય ત્યાં સુધી સાધકે દિવસમાં એક જ વાર ભોજન કરવું."}},{"n":3,"sa":["बुद्ध्या विनापि विबुधार्चित-पाद-पीठ,","स्तोतुं समुद्यत-मतिर्विगत-त्रपोऽहम्।","बालं विहाय जल-संस्थित-मिन्दु-बिम्ब-","मन्यः क इच्छति जनः सहसा ग्रहीतुम्।।३।।"],"pron":["buddhyā vināpi vibudhārcita-pāda-pīṭha,","stotuṃ samudyata-matirvigata-trapo’ham|","bālaṃ vihāya jala-saṃsthita-mindu-bimba-","manyaḥ ka icchati janaḥ sahasā grahītum||3||"],"title":{"en":"The child and the moon","hi":"बालक और चंद्रमा","es":"El niño y la luna","pt":"A criança e a lua","it":"Il bambino e la luna","gu":"બાળક અને ચંદ્ર"},"meaning":{"en":"I have little wisdom, and still I dare to praise you, like a child stretching out a hand for the moon’s reflection in the water.","hi":"मेरे पास ज्ञान कम है, फिर भी मैं आपकी स्तुति का साहस करता हूँ, जैसे कोई बालक जल में दिखते चंद्रमा के प्रतिबिंब को छूने हाथ बढ़ाता है।","es":"Tengo poca sabiduría y aun así me atrevo a alabarte, como un niño que extiende la mano hacia el reflejo de la luna en el agua.","pt":"Tenho pouca sabedoria e, ainda assim, ouso louvar-te, como uma criança que estende a mão para o reflexo da lua na água.","it":"Ho poca saggezza, eppure oso lodarti, come un bambino che tende la mano verso il riflesso della luna nell’acqua.","gu":"મારી પાસે બહુ ઓછી બુદ્ધિ છે, છતાં હું તમારી સ્તુતિ કરવાની હિંમત કરું છું, જેમ બાળક પાણીમાં ચંદ્રના પ્રતિબિંબ તરફ હાથ લંબાવે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो परमोहि जिणाणं झ्रौं झ्रौं नमः स्वाहा।","iast":"Oṃ hrīṃ arhaṃ ṇamo paramohi jiṇāṇaṃ jhrauṃ jhrauṃ namaḥ svāhā"}],"mantra":[{"dev":"ॐ ह्रीं श्रीं क्लीं सिद्धेभ्यः बुद्धेभ्यः सर्वसिद्धिदायकेभ्यः नमः स्वाहा।","iast":"Oṃ hrīṃ śrīṃ klīṃ siddhebhyaḥ buddhebhyaḥ sarvasiddhidāyakebhyaḥ namaḥ svāhā"}],"method":{"en":"Recall the riddhi and the mantra seven days in a row, 108 times each day, with a rosary of lotus seeds. For worship of the yantra take fully opened rose flowers, and fragrant incense for the fire offering (homa).","es":"Recuerda la riddhi y el mantra durante siete días seguidos, 108 veces al día, con un rosario de semillas de loto. Para la adoración del yantra toma rosas completamente abiertas, y para el homa (ofrenda al fuego) incienso aromático.","hi":"कमल गट्टे की माला से ऋद्धि और मंत्र का सात दिन तक प्रतिदिन १०८ बार स्मरण करना चाहिए। यंत्र आराधन के लिये खिले हुये गुलाब के फूल एवं होम के लिये सुगन्धित धूप लें।","pt":"Recorde o riddhi e o mantra durante sete dias seguidos, 108 vezes por dia, com um rosário de sementes de lótus. Para a adoração do yantra, tome rosas totalmente abertas e incenso perfumado para a oferenda ao fogo (homa).","it":"Ricorda il riddhi e il mantra per sette giorni consecutivi, 108 volte al giorno, con un rosario di semi di loto. Per il culto dello yantra prendi rose completamente sbocciate e incenso profumato per l’offerta al fuoco (homa).","gu":"કમળગટ્ટાની માળા વડે સાત દિવસ સુધી સતત, રોજ 108 વાર, ઋદ્ધિ અને મંત્રનું સ્મરણ કરો. યંત્રની પૂજા માટે પૂરેપૂરાં ખીલેલાં ગુલાબનાં ફૂલ અને હોમ (અગ્નિમાં આહુતિ) માટે સુગંધિત ધૂપ લો."},"benefit":{"en":"Charge water with the mantra and sprinkle it on the face for 21 days: everyone becomes pleased. Keeping the yantra with you and recalling the third verse with its riddhi and mantra closes the eyes of the enemy (their gaze is bound). Ill effects of the evil eye also go away.","es":"Carga agua con el mantra y rocíala sobre el rostro durante 21 días: todos se muestran complacidos. Tener el yantra contigo y recordar el tercer verso con su riddhi y su mantra ata la mirada del enemigo. También se disipan los efectos del mal de ojo.","hi":"जल को मंत्रित कर २१ दिन तक जल के छींटे मुख पर देने से सब लोग प्रसन्न होते हैं। यंत्र को पास में रखने तथा तीसरा काव्य ऋद्धि मंत्र सहित स्मरण करने से शत्रु की नजर बन्द हो जाती है। दृष्टि दोष भी दूर होता है।","pt":"Carregue água com o mantra e borrife-a no rosto por 21 dias: todos ficam satisfeitos. Mantendo o yantra consigo e recordando o terceiro verso com seu riddhi e mantra, fecham-se os olhos do inimigo (seu olhar fica preso). Os maus efeitos do mau-olhado também desaparecem.","it":"Carica l’acqua con il mantra e spruzzala sul viso per 21 giorni: tutti ne sono compiaciuti. Tenendo con te lo yantra e ricordando il terzo verso con il suo riddhi e mantra, si chiudono gli occhi del nemico (il suo sguardo resta legato). Anche gli effetti nocivi del malocchio svaniscono.","gu":"મંત્રથી પાણીને અભિમંત્રિત કરી 21 દિવસ સુધી ચહેરા પર છાંટો: બધા પ્રસન્ન થાય છે. યંત્ર પોતાની પાસે રાખી, ઋદ્ધિ અને મંત્ર સાથે ત્રીજા શ્લોકનું સ્મરણ કરવાથી શત્રુની આંખો બંધ થઈ જાય છે (તેની નજર બંધાઈ જાય છે). નજરનો ખરાબ પ્રભાવ પણ દૂર થાય છે."}},{"n":4,"sa":["वक्तुं गुणान् गुण-समुद्र शशांक-कान्तान्,","कस्ते क्षमः सुर-गुरु-प्रतिमोऽपि बुद्ध्या।","कल्पान्त-काल-पवनोद्धत-नक्र-चक्रं,","को वा तर्तुमल-मम्बुनिधिं भुजाभ्याम्।।४।।"],"pron":["vaktuṃ guṇān guṇa-samudra śaśāṃka-kāntān,","kaste kṣamaḥ sura-guru-pratimo’pi buddhyā|","kalpānta-kāla-pavanoddhata-nakra-cakraṃ,","ko vā tartumala-mambunidhiṃ bhujābhyām||4||"],"title":{"en":"An ocean of virtues","hi":"गुणों का सागर","es":"Un océano de virtudes","pt":"Um oceano de virtudes","it":"Un oceano di virtù","gu":"ગુણોનો સાગર"},"meaning":{"en":"Your virtues are an ocean. Even a teacher as wise as Brihaspati cannot describe them, any more than anyone can swim a stormy, crocodile-filled sea with bare arms.","hi":"आपके गुण एक सागर हैं। बृहस्पति जैसे ज्ञानी गुरु भी उनका वर्णन नहीं कर सकते, जैसे कोई खाली भुजाओं से मगरमच्छों भरा तूफ़ानी समुद्र पार नहीं कर सकता।","es":"Tus virtudes son un océano. Ni un maestro tan sabio como Brihaspati puede describirlas, como nadie puede cruzar a nado un mar tormentoso lleno de cocodrilos con los brazos desnudos.","pt":"Tuas virtudes são um oceano. Nem mesmo um mestre tão sábio quanto Brihaspati consegue descrevê-las, assim como ninguém atravessa a nado, de braços nus, um mar tempestuoso cheio de crocodilos.","it":"Le tue virtù sono un oceano. Nemmeno un maestro saggio come Brihaspati può descriverle, così come nessuno può attraversare a nuoto, a braccia nude, un mare in tempesta pieno di coccodrilli.","gu":"તમારા ગુણો સાગર સમાન છે. બૃહસ્પતિ જેવા જ્ઞાની ગુરુ પણ તેનું વર્ણન કરી શકતા નથી, જેમ મગરોથી ભરેલા તોફાની સમુદ્રને કોઈ ખુલ્લા હાથે તરીને પાર કરી શકતું નથી."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो सव्वोसहि जिणाणं झ्रौं झ्रौं नमः स्वाहा।","iast":"Oṃ hrīṃ arhaṃ ṇamo savvosahi jiṇāṇaṃ jhrauṃ jhrauṃ namaḥ svāhā"}],"mantra":[{"dev":"ॐ ह्रीं श्रीं क्लीं सागरसिद्धदेवताभ्यो नमः स्वाहा।","iast":"Oṃ hrīṃ śrīṃ klīṃ sāgarasiddhadevatābhyo namaḥ svāhā"}],"method":{"en":"Wearing pure white clothes, set up the yantra and worship it. Then, with a crystal rosary, chant the riddhi and the mantra 1,000 times a day for seven days, offering 108 white flowers each day. Eat one meal a day and sleep on the floor at night.","es":"Vestido con ropa blanca y pura, coloca el yantra y adóralo. Luego, con un rosario de cristal, canta la riddhi y el mantra 1.000 veces al día durante siete días, ofreciendo cada día 108 flores blancas. Come una vez al día y duerme en el suelo por la noche.","hi":"शुद्ध श्वेत वस्त्र पहनकर यंत्र स्थापित करें तथा यंत्र की पूजा करें। तत्पश्चात् स्फटिक मणि की माला से सात दिन तक प्रतिदिन १००० बार ऋद्धि तथा मंत्र का जाप जपते हुए रोज १०८ सफेद फूल चढ़ाना चाहिए, दिन में एक बार भोजन और रात्रि में भूमि पर शयन करना चाहिए।","pt":"Vestindo roupas brancas e puras, coloque o yantra e adore-o. Depois, com um rosário de cristal, entoe o riddhi e o mantra 1.000 vezes por dia durante sete dias, oferecendo 108 flores brancas a cada dia. Faça uma refeição por dia e durma no chão à noite.","it":"Indossando abiti di un bianco puro, disponi lo yantra e adoralo. Poi, con un rosario di cristallo, intona il riddhi e il mantra 1.000 volte al giorno per sette giorni, offrendo ogni giorno 108 fiori bianchi. Fai un solo pasto al giorno e dormi per terra di notte.","gu":"શુદ્ધ સફેદ વસ્ત્રો પહેરી યંત્રની સ્થાપના કરી તેની પૂજા કરો. પછી સ્ફટિકની માળા વડે સાત દિવસ સુધી રોજ 1,000 વાર ઋદ્ધિ અને મંત્રનો જાપ કરો, અને દરરોજ 108 સફેદ ફૂલ અર્પણ કરો. દિવસમાં એક વાર ભોજન કરો અને રાત્રે જમીન પર સૂઓ."},"benefit":{"en":"Keeping the yantra with you, take 21 pebbles and charge each one seven times with the fourth verse, the riddhi and the mantra, then drop them into the water: fish and water creatures are not caught in the net. The devotee of the mantra does not drown and escapes from fast-flowing water.","es":"Con el yantra a tu lado, toma 21 guijarros y carga cada uno siete veces con el cuarto verso, la riddhi y el mantra; luego échalos al agua: los peces y los animales acuáticos no quedan atrapados en la red. El devoto del mantra no se ahoga y se libra de las aguas de corriente fuerte.","hi":"यंत्र को पास में रखकर चौथा काव्य ऋद्धि तथा मंत्र द्वारा २१ कंकरियों को लेकर प्रत्येक कंकड़ी सात बार मंत्रित कर जल में डालने से मछलियाँ तथा जलजन्तु जाल में नहीं फँसते। मंत्र आराधक जल में नहीं डूबता और तेज बहाव वाले पानी से बच निकलता है।","pt":"Mantendo o yantra consigo, tome 21 seixos e carregue cada um sete vezes com o quarto verso, o riddhi e o mantra; depois jogue-os na água: peixes e criaturas aquáticas não são presos na rede. O devoto do mantra não se afoga e escapa de águas de correnteza forte.","it":"Tenendo con te lo yantra, prendi 21 sassolini e carica ciascuno sette volte con il quarto verso, il riddhi e il mantra, poi gettali nell’acqua: i pesci e le creature acquatiche non restano presi nella rete. Il devoto del mantra non annega e si salva dalle acque impetuose.","gu":"યંત્ર પોતાની પાસે રાખી, 21 કાંકરા લો અને દરેકને ચોથા શ્લોક, ઋદ્ધિ અને મંત્ર વડે સાત વાર અભિમંત્રિત કરો, પછી તેમને પાણીમાં નાખો: માછલીઓ અને જળચર જીવો જાળમાં ફસાતાં નથી. મંત્રનો સાધક ડૂબતો નથી અને વહેતા પ્રવાહમાંથી બચી જાય છે."}},{"n":5,"sa":["सोऽहं तथापि तव भक्ति-वशान्मुनीश,","कर्तुं स्तवं विगत-शक्ति-रपि प्रवृत्तः।","प्रीत्यात्म-वीर्य-मविचार्य्य मृगी मृगेन्द्रं,","नाऽभ्येति किं निज-शिशोः परि-पालनार्थम्।।५।।"],"pron":["so’haṃ tathāpi tava bhakti-vaśānmunīśa,","kartuṃ stavaṃ vigata-śakti-rapi pravṛttaḥ|","prītyātma-vīrya-mavicāryya mṛgī mṛgendraṃ,","nā’bhyeti kiṃ nija-śiśoḥ pari-pālanārtham||5||"],"title":{"en":"Courage born of love","hi":"प्रेम से उपजा साहस","es":"Valor nacido del amor","pt":"Coragem nascida do amor","it":"Coraggio nato dall’amore","gu":"પ્રેમથી જન્મેલી હિંમત"},"meaning":{"en":"My strength is small, yet devotion moves me to speak, as love makes even the gentle doe stand up for her fawn.","hi":"मेरी शक्ति थोड़ी है, फिर भी भक्ति मुझे बोलने को प्रेरित करती है, जैसे प्रेम कोमल हिरनी को भी अपने शावक के लिए खड़ा कर देता है।","es":"Mi fuerza es pequeña, y aun así la devoción me impulsa a hablar, como el amor hace que la tierna cierva se enfrente por su cría.","pt":"Minha força é pequena, mas a devoção me move a falar, como o amor faz até a gentil corça se levantar em defesa de seu filhote.","it":"La mia forza è poca, eppure la devozione mi spinge a parlare, come l’amore fa sì che perfino la dolce cerva si levi in difesa del suo cerbiatto.","gu":"મારી શક્તિ થોડી છે, છતાં ભક્તિ મને બોલવા પ્રેરે છે, જેમ પ્રેમ સૌમ્ય હરણીને પણ પોતાના બચ્ચા માટે ઊભી થવા પ્રેરે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो अणंतोहि जिणाणं झ्रौं झ्रौं नमः स्वाहा।","iast":"Oṃ hrīṃ arhaṃ ṇamo aṇaṃtohi jiṇāṇaṃ jhrauṃ jhrauṃ namaḥ svāhā"}],"mantra":[{"dev":"ॐ ह्रीं श्रीं क्लीं क्रौं सर्व संकट निवारणेभ्यः सुपार्श्व यक्षेभ्यो नमो नमः स्वाहा।","iast":"Oṃ hrīṃ śrīṃ klīṃ krauṃ sarva saṃkaṭa nivāraṇebhyaḥ supārśva yakṣebhyo namo namaḥ svāhā"}],"method":{"en":"Wearing yellow clothes, set up the yantra and sit on a yellow seat. Worship the yantra with yellow flowers. For seven days in a row chant the riddhi and the mantra 1,000 times each day with a pure heart, and each time offer kundru (frankincense) incense.","es":"Vestido de amarillo, coloca el yantra y siéntate en un asiento amarillo. Adora el yantra con flores amarillas. Durante siete días seguidos canta la riddhi y el mantra 1.000 veces al día con corazón puro, y cada vez ofrece incienso de kundru (incienso de olíbano).","hi":"पीले वस्त्र पहनकर यंत्र स्थापित कर, पीले आसन पर बैठकर पीले रंग के फूलों द्वारा यंत्र की पूजा कर सात दिन तक लगातार १००० बार ऋद्धि तथा मंत्र का शुद्ध भाव से जाप जपें और हर बार कुन्दरु की धूप खेवें।","pt":"Vestindo roupas amarelas, coloque o yantra e sente-se em um assento amarelo. Adore o yantra com flores amarelas. Durante sete dias seguidos, entoe o riddhi e o mantra 1.000 vezes por dia com o coração puro e, a cada vez, ofereça incenso de kundru (olíbano).","it":"Indossando abiti gialli, disponi lo yantra e siediti su un sedile giallo. Adora lo yantra con fiori gialli. Per sette giorni consecutivi intona il riddhi e il mantra 1.000 volte al giorno con cuore puro e ogni volta offri incenso di kundru (olibano).","gu":"પીળાં વસ્ત્રો પહેરી યંત્રની સ્થાપના કરો અને પીળા આસન પર બેસો. પીળાં ફૂલોથી યંત્રની પૂજા કરો. સાત દિવસ સુધી સતત શુદ્ધ હૃદયે રોજ 1,000 વાર ઋદ્ધિ અને મંત્રનો જાપ કરો અને દરેક વખતે કુંદરુનો ધૂપ અર્પણ કરો."},"benefit":{"en":"Keeping the yantra with you, and dropping into a well water charged with the verse, riddhi and mantra, stops worms from breeding. For someone with eye pain or a severe affliction: keep them without food all day, and in the evening charge water 21 times with the mantra, dissolve sugar drops (batashe) in it, and have them drink it and sprinkle it on the eyes. The pain and suffering go away.","es":"Tener el yantra contigo y echar a un pozo agua cargada con el verso, la riddhi y el mantra impide que se críen gusanos. A quien tenga dolor de ojos o una dolencia grave: déjalo sin comer todo el día y, por la tarde, carga agua 21 veces con el mantra, disuelve en ella batashas (dulces de azúcar), hazlo beber y rocíale los ojos. El dolor y el sufrimiento desaparecen.","hi":"यंत्र पास में रखने और काव्य ऋद्धि मंत्र द्वारा मंत्रित जल को कुएँ में डालने से कीड़े पैदा नहीं होते। जिसकी आँखों में दर्द हो, भयानक पीड़ा हो उसे सारे दिन भूखा रखकर साँयकाल मंत्र द्वारा २१ बार मंत्रित कर बताशों को जल में घोलकर पिलाने और आँखों पर छीटें मारने से दुःख दर्द दूर होता है।","pt":"Mantendo o yantra consigo e lançando em um poço água carregada com o verso, o riddhi e o mantra, impede-se que os vermes se reproduzam. Para quem sofre de dor nos olhos ou de uma aflição grave: deixe a pessoa sem comer durante o dia todo e, à noite, carregue água 21 vezes com o mantra, dissolva nela gotas de açúcar (batashe), e faça-a beber e borrifá-la nos olhos. A dor e o sofrimento desaparecem.","it":"Tenendo con te lo yantra e gettando in un pozzo acqua caricata con il verso, il riddhi e il mantra, si impedisce ai vermi di proliferare. Per chi soffre di dolore agli occhi o di un grave tormento: tienilo senza cibo per tutto il giorno e la sera carica l’acqua 21 volte con il mantra, scioglici dentro delle gocce di zucchero (batashe), e fagliela bere e spruzzare sugli occhi. Il dolore e la sofferenza svaniscono.","gu":"યંત્ર પોતાની પાસે રાખી, શ્લોક, ઋદ્ધિ અને મંત્રથી અભિમંત્રિત કરેલું પાણી કૂવામાં નાખવાથી કીડા થતા અટકે છે. આંખના દુખાવાવાળા કે ભારે પીડાવાળા માટે: તેને આખો દિવસ ભોજન વગર રાખો, અને સાંજે મંત્ર વડે 21 વાર પાણી અભિમંત્રિત કરો, તેમાં બતાશાં ઓગાળો, અને તે તેને પીવડાવો તથા આંખો પર છાંટો. દુખાવો અને પીડા દૂર થાય છે."}},{"n":6,"sa":["अल्पश्रुतं श्रुतवतां परिहास-धाम,","त्वद्भक्ति-रेव-मुखरी-कुरुते बलान्माम्।","यत्कोकिलः किल मधौ मधुरं विरौति,","तच्चारुचूतकलिकानिकरैकहेतुः ।।६।।"],"pron":["alpaśrutaṃ śrutavatāṃ parihāsa-dhāma,","tvadbhakti-reva-mukharī-kurute balānmām|","yatkokilaḥ kila madhau madhuraṃ virauti,","taccārucūtakalikānikaraikahetuḥ ||6||"],"title":{"en":"The cuckoo’s song","hi":"कोयल का गीत","es":"El canto del cuco","pt":"O canto do cuco","it":"Il canto del cuculo","gu":"કોયલનું ગીત"},"meaning":{"en":"I know little, and scholars may smile. It is your devotion that makes me sing, as spring’s mango blossoms make the cuckoo call.","hi":"मैं कम जानता हूँ और विद्वान मुस्कुरा सकते हैं। आपकी भक्ति ही मुझसे गवाती है, जैसे वसंत में आम की मंजरी कोयल को गाने के लिए जगा देती है।","es":"Sé poco y los eruditos pueden sonreír. Es tu devoción la que me hace cantar, como las flores de mango de la primavera despiertan el canto del cuco.","pt":"Sei pouco, e os eruditos podem sorrir. É a tua devoção que me faz cantar, como as flores de mangueira da primavera fazem o cuco chamar.","it":"So poco, e gli eruditi possono sorridere. È la tua devozione a farmi cantare, come i fiori di mango della primavera fanno chiamare il cuculo.","gu":"હું થોડું જાણું છું, અને વિદ્વાનો હસી પણ શકે. તમારી ભક્તિ જ મને ગવડાવે છે, જેમ વસંતની આંબાની મંજરી કોયલને ટહુકવા પ્રેરે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो कुट्ठबुद्धीणं झ्रौं झ्रौं नमः स्वाहा।","iast":"Oṃ hrīṃ arhaṃ ṇamo kuṭṭhabuddhīṇaṃ jhrauṃ jhrauṃ namaḥ svāhā"}],"mantra":[{"dev":"ॐ ह्रीं श्रां श्रीं श्रूं श्रः हं सं थ थ थः ठः ठः सरस्वती भगवती विद्या प्रसादं कुरु कुरु नमः स्वाहा।","iast":"Oṃ hrīṃ śrāṃ śrīṃ śrūṃ śraḥ haṃ saṃ tha tha thaḥ ṭhaḥ ṭhaḥ sarasvatī bhagavatī vidyā prasādaṃ kuru kuru namaḥ svāhā"}],"method":{"en":"After bathing, wear clean clothes, set up the yantra and worship it. Then sit on a red seat and for 21 days chant the riddhi and the mantra 1,000 times each day. Each time offer kundru (frankincense) incense. Eat one meal a day and sleep on the earth at night.","es":"Después de bañarte, ponte ropa limpia, coloca el yantra y adóralo. Luego siéntate en un asiento rojo y durante 21 días canta la riddhi y el mantra 1.000 veces al día. Cada vez ofrece incienso de kundru (incienso de olíbano). Come una vez al día y duerme sobre la tierra por la noche.","hi":"स्नान करके पवित्र वस्त्र पहनकर यंत्र स्थापित कर पूजा करें, पश्चात् लाल आसन पर बैठकर २१ दिन तक प्रतिदिन ऋद्धि तथा मंत्र का १००० वार जाप करें। हर वार कुंदरू की धूप क्षेपण करें, दिन में एक वार भोजन और रात में पृथ्वी पर शयन करना चाहिये।","pt":"Depois do banho, vista roupas limpas, coloque o yantra e adore-o. Depois sente-se em um assento vermelho e, por 21 dias, entoe o riddhi e o mantra 1.000 vezes por dia. A cada vez, ofereça incenso de kundru (olíbano). Faça uma refeição por dia e durma na terra à noite.","it":"Dopo il bagno, indossa abiti puliti, disponi lo yantra e adoralo. Poi siediti su un sedile rosso e per 21 giorni intona il riddhi e il mantra 1.000 volte al giorno. Ogni volta offri incenso di kundru (olibano). Fai un solo pasto al giorno e dormi sulla terra di notte.","gu":"સ્નાન કરીને સ્વચ્છ વસ્ત્રો પહેરો, યંત્રની સ્થાપના કરી તેની પૂજા કરો. પછી લાલ આસન પર બેસી 21 દિવસ સુધી રોજ 1,000 વાર ઋદ્ધિ અને મંત્રનો જાપ કરો. દરેક વખતે કુંદરુનો ધૂપ અર્પણ કરો. દિવસમાં એક વાર ભોજન કરો અને રાત્રે જમીન પર સૂઓ."},"benefit":{"en":"By chanting this mantra together with its riddhi, a person of dull mind becomes wise.","es":"Quien canta este mantra junto con su riddhi, siendo de mente torpe, se vuelve sabio.","hi":"इस मंत्र का ऋद्धि सहित जाप्य करने से मन्द बुद्धि वाला बुद्धिमान हो जाता है।","pt":"Ao entoar este mantra junto com seu riddhi, uma pessoa de mente lenta torna-se sábia.","it":"Intonando questo mantra insieme al suo riddhi, una persona dalla mente ottusa diventa saggia.","gu":"આ મંત્ર ઋદ્ધિ સાથે જપવાથી મંદબુદ્ધિ વ્યક્તિ બુદ્ધિમાન બને છે."}},{"n":7,"sa":["त्वत्संस्तवेन भव-सन्तति-सन्निबद्धं,","पापं क्षणात्क्षय-मुपैति शरीर-भाजाम्।","आक्रान्त-लोक-मलिनील-मशेष-माशु,","सूर्यांशु-भिन्न-मिव शार्वर-मन्धकारम् ।।७।।"],"pron":["tvatsaṃstavena bhava-santati-sannibaddhaṃ,","pāpaṃ kṣaṇātkṣaya-mupaiti śarīra-bhājām|","ākrānta-loka-malinīla-maśeṣa-māśu,","sūryāṃśu-bhinna-miva śārvara-mandhakāram ||7||"],"title":{"en":"Light after darkness","hi":"अंधकार के बाद प्रकाश","es":"Luz tras la oscuridad","pt":"Luz depois da escuridão","it":"Luce dopo l’oscurità","gu":"અંધકાર પછીનો પ્રકાશ"},"meaning":{"en":"Praise of you, offered with devotion, destroys the karma gathered over countless lives, as the piercing rays of the sun scatter the night.","hi":"भक्ति से की गई आपकी स्तुति अनेक जन्मों में संचित कर्मों को नष्ट कर देती है, जैसे सूर्य की भेदक किरणें रात्रि के अंधकार को मिटा देती हैं।","es":"La alabanza a ti, ofrecida con devoción, destruye el karma acumulado durante incontables vidas, como los rayos penetrantes del sol dispersan la noche.","pt":"O louvor a ti, oferecido com devoção, destrói o karma acumulado ao longo de incontáveis vidas, como os raios penetrantes do sol dissipam a noite.","it":"La lode a te, offerta con devozione, distrugge il karma accumulato in innumerevoli vite, come i raggi penetranti del sole disperdono la notte.","gu":"ભક્તિપૂર્વક કરેલી તમારી સ્તુતિ અનેક જન્મોમાં એકઠાં થયેલાં કર્મોનો નાશ કરે છે, જેમ સૂર્યનાં તીક્ષ્ણ કિરણો રાત્રિને વિખેરી નાખે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो बीज बुद्धीणं (झ्रौं झ्रौं) नमः स्वाहा।","iast":"Oṃ hrīṃ arhaṃ ṇamo bīja buddhīṇaṃ (jhrauṃ jhrauṃ) namaḥ svāhā"}],"mantra":[{"dev":"ॐ ह्रीं हं सं श्रां श्रीं क्रौं क्लीं सर्व दुरित संकट क्षुद्रोपद्रव कष्ट निवारणं कुरु कुरु नमः स्वाहा।","iast":"Oṃ hrīṃ haṃ saṃ śrāṃ śrīṃ krauṃ klīṃ sarva durita saṃkaṭa kṣudropadrava kaṣṭa nivāraṇaṃ kuru kuru namaḥ svāhā"}],"method":{"en":"Become pure, wear green clothes and sit on a green seat. With a green rosary, for 21 days recite the seventh verse, the riddhi and the mantra 108 times each day, offering loban (benzoin) incense.","es":"Purifícate, vístete de verde y siéntate en un asiento verde. Con un rosario verde, durante 21 días recita 108 veces al día el séptimo verso, la riddhi y el mantra, ofreciendo incienso de loban (benjuí).","hi":"पवित्र होकर हरे रंग के वस्त्र धारण कर हरे रंग के आसन पर बैठकर हरी माला से २१ दिन तक प्रतिदिन १०८ बार सातवाँ काव्य ऋद्धि तथा मंत्र की जाप जपते हुए लोभान की धूप क्षेपण करना चाहिए।","pt":"Purifique-se, vista roupas verdes e sente-se em um assento verde. Com um rosário verde, durante 21 dias recite o sétimo verso, o riddhi e o mantra 108 vezes por dia, oferecendo incenso de loban (benjoim).","it":"Purificati, indossa abiti verdi e siediti su un sedile verde. Con un rosario verde, per 21 giorni recita il settimo verso, il riddhi e il mantra 108 volte al giorno, offrendo incenso di loban (benzoino).","gu":"શુદ્ધ થઈને લીલાં વસ્ત્રો પહેરો અને લીલા આસન પર બેસો. લીલી માળા વડે 21 દિવસ સુધી રોજ સાતમો શ્લોક, ઋદ્ધિ અને મંત્ર 108 વાર બોલો અને લોબાનનો ધૂપ અર્પણ કરો."},"benefit":{"en":"Keeping a yantra written in green on birch bark with you removes snake venom, and other poisons also have no effect. Charge a pebble 108 times with the riddhi and mantra and strike the snake's head with it: the snake is held spellbound.","es":"Tener contigo un yantra escrito en verde sobre corteza de abedul elimina el veneno de serpiente, y otros venenos tampoco surten efecto. Carga un guijarro 108 veces con la riddhi y el mantra y golpea con él la cabeza de la serpiente: la serpiente queda paralizada.","hi":"भोज पत्र पर हरे रंग से लिखा यंत्र पास में रखने से सर्प विष दूर होता है तथा अन्य विष भी प्रभावशील नहीं होते। ऋद्धि मंत्र द्वारा १०८ बार कंकरी मंत्रित कर सर्प के सिर पर मारने से नाग कीलित हो जाता है।","pt":"Manter consigo um yantra escrito em verde em casca de bétula remove o veneno de cobra, e outros venenos também não fazem efeito. Carregue um seixo 108 vezes com o riddhi e o mantra e golpeie com ele a cabeça da cobra: a cobra fica enfeitiçada.","it":"Tenere con sé uno yantra scritto in verde su corteccia di betulla elimina il veleno dei serpenti, e anche altri veleni non hanno effetto. Carica un sassolino 108 volte con il riddhi e il mantra e colpisci con esso la testa del serpente: il serpente resta incantato.","gu":"ભોજપત્ર પર લીલા રંગે લખેલું યંત્ર પોતાની પાસે રાખવાથી સાપનું ઝેર ઊતરે છે, અને બીજાં ઝેર પણ અસર કરતાં નથી. એક કાંકરાને ઋદ્ધિ અને મંત્ર વડે 108 વાર અભિમંત્રિત કરી સાપના માથા પર મારો: સાપ મંત્રમુગ્ધ થઈ જાય છે."}},{"n":8,"sa":["मत्वेति नाथ! तव संस्तवनं मयेद-","मारभ्यते तनुधियाऽपि तव प्रभावात् ।","चेतो हरिष्यति सतां नलिनी-दलेषु,","मुक्ताफल-द्युति-मुपैति ननूद-बिंदुः।।८।।"],"pron":["matveti nātha! tava saṃstavanaṃ mayeda-","mārabhyate tanudhiyā’pi tava prabhāvāt |","ceto hariṣyati satāṃ nalinī-daleṣu,","muktāphala-dyuti-mupaiti nanūda-biṃduḥ||8||"],"title":{"en":"A drop becomes a pearl","hi":"बूँद बनी मोती","es":"Una gota se vuelve perla","pt":"Uma gota que vira pérola","it":"Una goccia diventa perla","gu":"ટીપું બને મોતી"},"meaning":{"en":"Trusting in your greatness, I begin this humble hymn. A drop of water resting on a lotus leaf can shine like a pearl.","hi":"आपकी महिमा पर भरोसा करके मैं यह विनम्र स्तोत्र आरंभ करता हूँ। कमल के पत्ते पर ठहरी जल की बूँद भी मोती-सी चमक सकती है।","es":"Confiando en tu grandeza, comienzo este humilde himno. Una gota de agua sobre una hoja de loto puede brillar como una perla.","pt":"Confiando em tua grandeza, começo este humilde hino. Uma gota de água sobre uma folha de lótus pode brilhar como uma pérola.","it":"Confidando nella tua grandezza, comincio questo umile inno. Una goccia d’acqua posata su una foglia di loto può brillare come una perla.","gu":"તમારી મહાનતા પર વિશ્વાસ રાખીને હું આ નમ્ર સ્તોત્ર શરૂ કરું છું. કમળના પાન પર રહેલું પાણીનું ટીપું મોતીની જેમ ચમકી શકે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो अरिहंताणं णमो पादानुसारीणं नमः स्वाहा।","iast":"Oṃ hrīṃ arhaṃ ṇamo arihaṃtāṇaṃ ṇamo pādānusārīṇaṃ namaḥ svāhā"}],"mantra":[{"dev":"ॐ ह्रां ह्रीं ह्रूं ह्रः असिआउसा अप्रतिचक्रे फट् विचक्राय झ्रौं झ्रौं नमः स्वाहा।","iast":"Oṃ hrāṃ hrīṃ hrūṃ hraḥ asiāusā apraticakre phaṭ vicakrāya jhrauṃ jhrauṃ namaḥ svāhā"}],"method":{"en":"With a rosary of soapnut (arittha/ritha) seeds, for 21 days chant the riddhi and the mantra 1,000 times each day, offering guggul incense mixed with ghee.","es":"Con un rosario de semillas de aritha (nuez de jabón), durante 21 días canta la riddhi y el mantra 1.000 veces al día, ofreciendo incienso de guggul mezclado con ghee.","hi":"अरीठा (रीठा) के बीज की माला से २१ दिन तक प्रतिदिन १००० बार ऋद्धि तथा मंत्र का जाप जपते हुए घृत मिश्रित गूगल की धूप का क्षेपण करें।","pt":"Com um rosário de sementes de sabão (arittha/ritha), durante 21 dias entoe o riddhi e o mantra 1.000 vezes por dia, oferecendo incenso de guggul misturado com ghee.","it":"Con un rosario di semi di noce del sapone (arittha/ritha), per 21 giorni intona il riddhi e il mantra 1.000 volte al giorno, offrendo incenso di guggul mescolato a ghi.","gu":"અરીઠાના (arittha/ritha) બીજની માળા વડે 21 દિવસ સુધી રોજ 1,000 વાર ઋદ્ધિ અને મંત્રનો જાપ કરો, અને ઘી મિશ્રિત ગુગળનો ધૂપ અર્પણ કરો."},"benefit":{"en":"Keeping the yantra with you, and through worship of the verse, riddhi and mantra, all kinds of misfortune (arishta) are removed.","es":"Tener el yantra contigo, y la adoración del verso, la riddhi y el mantra, alejan toda clase de desgracias (arishta).","hi":"यंत्र को पास में रखने से, काव्य, ऋद्धि-मंत्र के आराधन से सब प्रकार के अरिष्ट दूर होते हैं।","pt":"Mantendo o yantra consigo, e por meio da adoração do verso, do riddhi e do mantra, todo tipo de infortúnio (arishta) é afastado.","it":"Tenendo con te lo yantra, e attraverso l’adorazione del verso, del riddhi e del mantra, ogni sorta di sventura (arishta) viene allontanata.","gu":"યંત્ર પોતાની પાસે રાખી, શ્લોક, ઋદ્ધિ અને મંત્રની પૂજા વડે બધા પ્રકારનાં અરિષ્ટ (અમંગળ) દૂર થાય છે."}},{"n":9,"sa":["आस्तां तव स्तवन-मस्त-समस्त-दोषं,","त्वत्संकथापि जगतां दुरितानि हन्ति।","दूरे सहस्र-किरणः कुरुते प्रभैव,","पद्माकरेषु जलजानि विकासभाञ्जि।।९।।"],"pron":["āstāṃ tava stavana-masta-samasta-doṣaṃ,","tvatsaṃkathāpi jagatāṃ duritāni hanti|","dūre sahasra-kiraṇaḥ kurute prabhaiva,","padmākareṣu jalajāni vikāsabhāñji||9||"],"title":{"en":"The distant sun","hi":"दूर का सूर्य","es":"El sol lejano","pt":"O sol distante","it":"Il sole lontano","gu":"દૂરનો સૂર્ય"},"meaning":{"en":"Even speaking your name undoes our faults, as the far-off sun opens the lotus with its light.","hi":"आपका नाम-उच्चारण मात्र भी हमारे दोषों को मिटा देता है, जैसे दूर का सूर्य अपनी किरणों से कमल को खिला देता है।","es":"Aun pronunciar tu nombre disuelve nuestras faltas, como el sol lejano abre el loto con su luz.","pt":"Até pronunciar o teu nome desfaz as nossas faltas, assim como o sol distante abre o lótus com a sua luz.","it":"Anche solo pronunciare il tuo nome scioglie le nostre colpe, come il sole lontano fa schiudere il loto con la sua luce.","gu":"તમારું નામ બોલવા માત્રથી પણ આપણા દોષો દૂર થાય છે, જેમ દૂરનો સૂર્ય પોતાના પ્રકાશથી કમળને ખીલવે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो अरिहंताणं णमो संभिण्ण सोदराणं नमः स्वाहा।","iast":"Oṃ hrīṃ arhaṃ ṇamo arihaṃtāṇaṃ ṇamo saṃbhiṇṇa sodarāṇaṃ namaḥ svāhā"}],"mantra":[{"dev":"ॐ ह्रीं श्रीं क्रौं झ्वीं रः रः हं हः नमः स्वाहा।","iast":"Oṃ hrīṃ śrīṃ krauṃ jhvīṃ raḥ raḥ haṃ haḥ namaḥ svāhā"}],"method":{"en":"Recite the ninth verse, the riddhi and the mantra 108 times every day.","es":"Recita cada día 108 veces el noveno verso, la riddhi y el mantra.","hi":"नवम् काव्य ऋद्धि और मंत्र प्रतिदिन १०८ बार जपना चाहिए।","pt":"Recite o nono verso, o riddhi e o mantra 108 vezes todos os dias.","it":"Recita il nono verso, il riddhi e il mantra 108 volte ogni giorno.","gu":"નવમો શ્લોક, ઋદ્ધિ અને મંત્ર દરરોજ 108 વાર બોલો."},"benefit":{"en":"By repeatedly recalling this verse, riddhi and mantra, and keeping the yantra with you, there is no fear of thieves and robbers on the road; a thief cannot steal. Take 4 pebbles, charge each pebble 108 times with the mantra and throw them in the four directions: the road becomes sealed (protected).","es":"Al recordar una y otra vez este verso, la riddhi y el mantra, y tener el yantra contigo, no hay temor a ladrones ni salteadores en el camino; un ladrón no puede robar. Toma 4 guijarros, carga cada uno 108 veces con el mantra y lánzalos hacia las cuatro direcciones: el camino queda sellado (protegido).","hi":"इस काव्य ऋद्धि और मंत्र के बार बार स्मरण करने तथा यंत्र को पास में रखने से मार्ग में चोर डाकुओं का भय नहीं रहता। चोर, चोरी नहीं कर सकता। ४ कंकड़ियों को लेकर प्रत्येक कंकरी को १०८ बार मंत्र कर चारों दिशाओं में फेंकने से मार्ग कीलित हो जाता है।","pt":"Recordando repetidamente este verso, o riddhi e o mantra, e mantendo o yantra consigo, não há medo de ladrões e salteadores no caminho; o ladrão não consegue roubar. Pegue 4 seixos, carregue cada um 108 vezes com o mantra e jogue-os nas quatro direções: o caminho fica selado (protegido).","it":"Ricordando di continuo questo verso, il riddhi e il mantra, e tenendo con te lo yantra, non si ha timore di ladri e briganti lungo la strada; il ladro non riesce a rubare. Prendi 4 sassolini, carica ciascuno 108 volte con il mantra e gettali nelle quattro direzioni: la strada viene sigillata (protetta).","gu":"આ શ્લોક, ઋદ્ધિ અને મંત્રનું વારંવાર સ્મરણ કરવાથી અને યંત્ર પોતાની પાસે રાખવાથી માર્ગમાં ચોર-લૂંટારાનો ભય રહેતો નથી; ચોર ચોરી કરી શકતો નથી. 4 કાંકરા લો, દરેકને મંત્ર વડે 108 વાર અભિમંત્રિત કરો અને ચારે દિશાઓમાં ફેંકો: માર્ગ બંધાઈ જાય છે (સુરક્ષિત થાય છે)."}},{"n":10,"sa":["नात्यद्भुतं भुवन-भूषण-भूतनाथ,","भूतैर्गुणैर्भुवि भवन्त-मभिष्टु-वन्तः।","तुल्या भवन्ति भवतो ननु तेन किं वा,","भूत्याश्रितं य इह नात्मसमं करोति।।१०।।"],"pron":["nātyadbhutaṃ bhuvana-bhūṣaṇa-bhūtanātha,","bhūtairguṇairbhuvi bhavanta-mabhiṣṭu-vantaḥ|","tulyā bhavanti bhavato nanu tena kiṃ vā,","bhūtyāśritaṃ ya iha nātmasamaṃ karoti||10||"],"title":{"en":"Greatness that uplifts","hi":"ऐसी महानता जो ऊपर उठाए","es":"Una grandeza que eleva","pt":"Uma grandeza que eleva","it":"Una grandezza che solleva","gu":"ઊંચે ઉઠાવતી મહાનતા"},"meaning":{"en":"It is no wonder that those who praise your virtues become like you, as a generous master lifts those who serve him.","hi":"इसमें आश्चर्य नहीं कि आपके गुणों की स्तुति करने वाले आप जैसे बन जाते हैं, जैसे उदार स्वामी अपने सेवकों को ऊपर उठाता है।","es":"No es de extrañar que quienes alaban tus virtudes lleguen a ser como tú, como un amo generoso eleva a quienes le sirven.","pt":"Não é de admirar que quem louva as tuas virtudes se torne como tu, assim como um mestre generoso eleva aqueles que o servem.","it":"Non c’è da stupirsi che chi loda le tue virtù diventi come te, come un padrone generoso innalza chi lo serve.","gu":"જે તમારા ગુણોની સ્તુતિ કરે છે તે તમારા જેવો બની જાય છે, એમાં કોઈ આશ્ચર્ય નથી, જેમ ઉદાર સ્વામી પોતાની સેવા કરનારને ઊંચે ઉઠાવે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो सयं बुद्धीणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo sayaṃ buddhīṇaṃ"}],"mantra":[{"dev":"ॐ ह्रां ह्रीं ह्रौं ह्रः श्रां श्रीं श्रूं श्रः सिद्ध बुद्ध कृतार्थो भव भव वषट् संपूर्ण नमः स्वाहा।","iast":"Oṃ hrāṃ hrīṃ hrauṃ hraḥ śrāṃ śrīṃ śrūṃ śraḥ siddha buddha kṛtārtho bhava bhava vaṣaṭ saṃpūrṇa namaḥ svāhā"}],"method":{"en":"Wearing yellow clothes and with a yellow rosary, for 7 or 10 days recite the tenth verse, the riddhi and the mantra 108 times each day, offering kundru (frankincense) incense.","es":"Vestido de amarillo y con un rosario amarillo, durante 7 o 10 días recita 108 veces al día el décimo verso, la riddhi y el mantra, ofreciendo incienso de kundru (incienso de olíbano).","hi":"पीले रंग के वस्त्र पहनकर पीले रंग की माला से ७ या १० दिन तक प्रतिदिन १०८ बार दसवाँ काव्य, ऋद्धि तथा मंत्र का आराधन करते हुए कुंदरू की धूप क्षेपण करना चाहिए।","pt":"Vestindo roupas amarelas e com um rosário amarelo, durante 7 ou 10 dias recite o décimo verso, o riddhi e o mantra 108 vezes por dia, oferecendo incenso de kundru (olíbano).","it":"Indossando abiti gialli e con un rosario giallo, per 7 o 10 giorni recita il decimo verso, il riddhi e il mantra 108 volte al giorno, offrendo incenso di kundru (olibano).","gu":"પીળાં વસ્ત્રો પહેરી, પીળી માળા લઈ, 7 અથવા 10 દિવસ સુધી રોજ દસમો શ્લોક, ઋદ્ધિ અને મંત્ર 108 વાર બોલો અને કુંદરુનો ધૂપ અર્પણ કરો."},"benefit":{"en":"Keeping the yantra with you removes the poison of a dog bite. Take seven lumps of salt, charge each 108 times with the mantra and eat them: the dog's poison has no effect.","es":"Tener el yantra contigo elimina el veneno de la mordedura de un perro. Toma siete terrones de sal, carga cada uno 108 veces con el mantra y cómelos: el veneno del perro no hace efecto.","hi":"यंत्र को पास रखने से कुत्ते के काटने का विष उतर जाता है। नमक की सात डली लेकर प्रत्येक को १०८ बार मंत्रित कर खाने से कुत्ते का विष असर नहीं करता।","pt":"Mantendo o yantra consigo, remove-se o veneno da mordida de cachorro. Pegue sete pedaços de sal, carregue cada um 108 vezes com o mantra e coma-os: o veneno do cão não faz efeito.","it":"Tenendo con te lo yantra, si rimuove il veleno del morso di cane. Prendi sette pezzetti di sale, carica ciascuno 108 volte con il mantra e mangiali: il veleno del cane non ha effetto.","gu":"યંત્ર પોતાની પાસે રાખવાથી કૂતરાના કરડવાનું ઝેર ઊતરે છે. સાત મીઠાના ગાંગડા લો, દરેકને મંત્ર વડે 108 વાર અભિમંત્રિત કરીને ખાઓ: કૂતરાનું ઝેર અસર કરતું નથી."}},{"n":11,"sa":["दृष्ट्वा भवन्त-मनिमेष-विलोकनीयं,","नान्यत्र तोष-मुपयाति जनस्य चक्षुः।","पीत्वा पयः शशिकर-द्युति-दुग्ध-सिन्धौ,","क्षारं जलं जलनिधेरसितुं क इच्छेत्।।११।।"],"pron":["dṛṣṭvā bhavanta-manimeṣa-vilokanīyaṃ,","nānyatra toṣa-mupayāti janasya cakṣuḥ|","pītvā payaḥ śaśikara-dyuti-dugdha-sindhau,","kṣāraṃ jalaṃ jalanidherasituṃ ka icchet||11||"],"title":{"en":"A deeper contentment","hi":"गहरा संतोष","es":"Un contento más hondo","pt":"Um contentamento mais profundo","it":"Un appagamento più profondo","gu":"ઊંડો સંતોષ"},"meaning":{"en":"Once my eyes have seen your calm form, nothing less can please them. Who would drink salt water after drinking the moon-bright milk of the divine ocean?","hi":"आपका शांत स्वरूप देख लेने के बाद मेरी आँखों को कोई कम चीज़ नहीं भाती। चंद्र-सम उज्ज्वल क्षीर-सागर का दूध पी लेने के बाद खारा पानी कौन पीना चाहेगा?","es":"Una vez que mis ojos han visto tu forma serena, nada menor puede agradarles. ¿Quién querría agua salada tras beber la leche, clara como la luna, del océano divino?","pt":"Depois que meus olhos viram tua forma serena, nada menos os pode agradar. Quem beberia água salgada depois de beber o leite do oceano divino, claro como a lua?","it":"Dopo che i miei occhi hanno visto la tua forma serena, nulla di meno può appagarli. Chi berrebbe acqua salata dopo aver bevuto il latte dell’oceano divino, chiaro come la luna?","gu":"તમારું શાંત સ્વરૂપ મારી આંખોએ જોયા પછી, તેનાથી ઓછું કંઈ તેમને ગમતું નથી. ચંદ્ર જેવા ઉજ્જવળ દિવ્ય સાગરનું દૂધ પીધા પછી ખારું પાણી કોણ પીએ?"},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो पत्तेय बुद्धीणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo patteya buddhīṇaṃ"}],"mantra":[{"dev":"ॐ ह्रीं श्रीं क्लीं श्रां श्रीं कुमति निवारिण्यै महामायायै नमः स्वाहा।","iast":"Oṃ hrīṃ śrīṃ klīṃ śrāṃ śrīṃ kumati nivāriṇyai mahāmāyāyai namaḥ svāhā"}],"method":{"en":"Become pure, wear white clothes and worship with a pure heart in the temple. Then, in a quiet place right there, sit or stand with a glad mind and, with a white rosary or a red rosary, for 21 days recite the eleventh verse, the riddhi and the mantra 108 times each day, offering kundru (frankincense) incense.","es":"Purifícate, vístete de blanco y haz tu adoración con corazón puro en el templo. Luego, en un lugar apartado allí mismo, sentado o de pie y con ánimo sereno, con un rosario blanco o rojo, durante 21 días recita 108 veces al día el undécimo verso, la riddhi y el mantra, ofreciendo incienso de kundru (incienso de olíbano).","hi":"पवित्र होकर सफेद वस्त्र पहनकर मंदिर में शुद्ध भावों से पूजा करें पश्चात् वहीं एकान्त स्थान में बैठकर या खड़े होकर प्रसन्न चित्त से सफेद माला द्वारा या लाल रंग की माला से २१ दिन तक प्रतिदिन ग्यारहवाँ काव्य ऋद्धि तथा मंत्र का १०८ बार आराधन करते हुए कुंदरु की धूप क्षेपण करना चाहिए।","pt":"Purifique-se, vista roupas brancas e adore com o coração puro no templo. Depois, ali mesmo, em um lugar tranquilo, sentado ou em pé, com a mente alegre e com um rosário branco ou vermelho, durante 21 dias recite o décimo primeiro verso, o riddhi e o mantra 108 vezes por dia, oferecendo incenso de kundru (olíbano).","it":"Purificati, indossa abiti bianchi e adora con cuore puro nel tempio. Poi, lì stesso, in un luogo tranquillo, seduto o in piedi, con la mente lieta e con un rosario bianco o rosso, per 21 giorni recita l’undicesimo verso, il riddhi e il mantra 108 volte al giorno, offrendo incenso di kundru (olibano).","gu":"શુદ્ધ થઈ, સફેદ વસ્ત્રો પહેરી, મંદિરમાં શુદ્ધ હૃદયે પૂજા કરો. પછી ત્યાં જ શાંત સ્થાને, પ્રસન્ન મનથી બેસીને અથવા ઊભા રહીને, સફેદ કે લાલ માળા વડે 21 દિવસ સુધી રોજ અગિયારમો શ્લોક, ઋદ્ધિ અને મંત્ર 108 વાર બોલો અને કુંદરુનો ધૂપ અર્પણ કરો."},"benefit":{"en":"Keeping the yantra with you, take a fistful of white mustard seeds, charge them 12,000 times with the above mantra and fling them upward: rain is certain to fall, as you wish to call it.","es":"Con el yantra a tu lado, toma un puñado de semillas de mostaza blanca, cárgalas 12.000 veces con el mantra anterior y lánzalas hacia arriba: sin duda cae la lluvia, como deseas convocarla.","hi":"यंत्र को पास में रखने से जिसे आप बुलाना चाहते हैं मुट्ठी भर सफेद सरसों को उक्त मंत्र १२००० बार मंत्रित कर ऊपर उछालकर फेंकने से निश्चयपूर्वक जल वृष्टि होती है।","pt":"Mantendo o yantra consigo, pegue um punhado de sementes de mostarda branca, carregue-as 12.000 vezes com o mantra acima e lance-as para o alto: a chuva certamente cairá, como você desejar chamá-la.","it":"Tenendo con te lo yantra, prendi una manciata di semi di senape bianca, caricali 12.000 volte con il mantra sopra indicato e lanciali verso l’alto: la pioggia cadrà di certo, come desideri chiamarla.","gu":"યંત્ર પોતાની પાસે રાખી, મુઠ્ઠીભર સફેદ રાઈ લો, ઉપરોક્ત મંત્ર વડે તેને 12,000 વાર અભિમંત્રિત કરો અને ઉપર ઉછાળો: તમે જે રીતે વરસાદને બોલાવવા ઇચ્છો તે રીતે વરસાદ નિશ્ચિત પડે છે."}},{"n":12,"sa":["यैः शान्त-राग-रुचिभिः परमाणु-भिस्त्वं,","निर्मापितस्त्रि-भुवनैक-ललाम-भूत।","तावन्त एव खलु तेऽप्यणवः पृथिव्यां,","यत्ते समान-मपरं न हि रूपमस्ति।।१२।।"],"pron":["yaiḥ śānta-rāga-rucibhiḥ paramāṇu-bhistvaṃ,","nirmāpitastri-bhuvanaika-lalāma-bhūta|","tāvanta eva khalu te’pyaṇavaḥ pṛthivyāṃ,","yatte samāna-maparaṃ na hi rūpamasti||12||"],"title":{"en":"A form beyond comparison","hi":"अतुलनीय स्वरूप","es":"Una forma sin comparación","pt":"Uma forma sem comparação","it":"Una forma senza paragoni","gu":"અજોડ સ્વરૂપ"},"meaning":{"en":"The peaceful particles that made your form were so pure that nowhere in the world is there another like you.","hi":"आपके शरीर को रचने वाले शांत परमाणु इतने पवित्र थे कि संसार में आपके समान कोई दूसरा नहीं।","es":"Las partículas serenas que formaron tu cuerpo eran tan puras que en el mundo no hay otro como tú.","pt":"As partículas serenas que formaram o teu corpo eram tão puras que em lugar algum do mundo existe outro igual a ti.","it":"Le particelle serene che formarono il tuo corpo erano così pure che in nessun luogo del mondo esiste un altro come te.","gu":"તમારા દેહને રચનારા શાંત પરમાણુઓ એટલા શુદ્ધ હતા કે સંસારમાં ક્યાંય તમારા જેવું બીજું કોઈ નથી."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो बोहि बुद्धीणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo bohi buddhīṇaṃ"}],"mantra":[{"dev":"ॐ आं आं अं अः सर्वराजाप्रजामोहिनी सर्वजनवश्यं कुरु कुरु नमः स्वाहा।","iast":"Oṃ āṃ āṃ aṃ aḥ sarvarājāprajāmohinī sarvajanavaśyaṃ kuru kuru namaḥ svāhā"}],"method":{"en":"After bathing, wear red clothes and, with a red rosary, for 42 days chant the riddhi and the mantra 1,000 times each day, offering dashang incense (a blend of ten substances).","es":"Después de bañarte, vístete de rojo y, con un rosario rojo, durante 42 días canta la riddhi y el mantra 1.000 veces al día, ofreciendo incienso dashang (una mezcla de diez sustancias).","hi":"स्नान करके लाल रंग के वस्त्र पहनकर लाल रंग की माला द्वारा ४२ दिन तक प्रतिदिन १००० बार ऋद्धि तथा मंत्र का आराधन करते हुए दशांग धूप खेना चाहिए।","pt":"Depois do banho, vista roupas vermelhas e, com um rosário vermelho, durante 42 dias entoe o riddhi e o mantra 1.000 vezes por dia, oferecendo incenso dashang (uma mistura de dez substâncias).","it":"Dopo il bagno, indossa abiti rossi e, con un rosario rosso, per 42 giorni intona il riddhi e il mantra 1.000 volte al giorno, offrendo incenso dashang (una miscela di dieci sostanze).","gu":"સ્નાન કરી લાલ વસ્ત્રો પહેરો અને લાલ માળા વડે 42 દિવસ સુધી રોજ 1,000 વાર ઋદ્ધિ અને મંત્રનો જાપ કરો અને દશાંગ ધૂપ (દસ દ્રવ્યોનું મિશ્રણ) અર્પણ કરો."},"benefit":{"en":"Recalling the twelfth verse, the riddhi and the mantra, keeping the yantra with you, and giving an elephant oil charged 108 times with the mantra to drink: its frenzy (mada) goes away. By repeatedly recalling the mantra, a wife who has gone back to her parents' home in anger returns.","es":"Al recordar el duodécimo verso, la riddhi y el mantra, tener el yantra contigo y dar a beber a un elefante aceite cargado 108 veces con el mantra, se le pasa el furor (mada). Con el recuerdo repetido del mantra, la esposa que se ha ido enfadada a casa de sus padres regresa.","hi":"बारहवाँ काव्य ऋद्धि तथा मंत्र स्मरण करने तथा यंत्र को पास में रखने से और १०८ बार तेल को उक्त मंत्रित द्वारा मंत्र कर हाथी को पिलाने से उसका मद उतर जाता है। बार बार मंत्र स्मरण से रूठकर पीहर गई पत्नी वापिस लौट आती है।","pt":"Recordando o décimo segundo verso, o riddhi e o mantra, mantendo o yantra consigo e dando a um elefante óleo carregado 108 vezes com o mantra para beber, seu frenesi (mada) passa. Recordando repetidamente o mantra, uma esposa que, com raiva, voltou para a casa dos pais retorna.","it":"Ricordando il dodicesimo verso, il riddhi e il mantra, tenendo con te lo yantra e dando da bere a un elefante olio caricato 108 volte con il mantra, il suo furore (mada) svanisce. Ricordando di continuo il mantra, una moglie che per rabbia è tornata a casa dei genitori fa ritorno.","gu":"બારમા શ્લોક, ઋદ્ધિ અને મંત્રનું સ્મરણ કરવાથી, યંત્ર પોતાની પાસે રાખવાથી અને મંત્ર વડે 108 વાર અભિમંત્રિત કરેલું તેલ હાથીને પીવડાવવાથી તેનો મદ ઊતરી જાય છે. મંત્રનું વારંવાર સ્મરણ કરવાથી ગુસ્સે થઈને પિયર ગયેલી પત્ની પાછી આવે છે."}},{"n":13,"sa":["वक्त्रं क्व ते सुर-नरोरगनेत्र-हारि,","निःशेष-निर्जित-जगत्त्रित-योपमानम्।","बिम्बं कलंक-मलिनं क्व निशाकरस्य,","यद्वासरे भवति पाण्डु-पलाश-कल्पम् ।।१३।।"],"pron":["vaktraṃ kva te sura-naroraganetra-hāri,","niḥśeṣa-nirjita-jagattrita-yopamānam|","bimbaṃ kalaṃka-malinaṃ kva niśākarasya,","yadvāsare bhavati pāṇḍu-palāśa-kalpam ||13||"],"title":{"en":"Beyond the moon","hi":"चंद्रमा से भी परे","es":"Más allá de la luna","pt":"Além da lua","it":"Oltre la luna","gu":"ચંદ્રથી પણ પર"},"meaning":{"en":"Your face outshines every comparison. Beside it, the moon, pale by day and marked with a stain, looks like an autumn leaf.","hi":"आपका मुख हर उपमा से बढ़कर है। उसके सामने चंद्रमा, जो दिन में फीका और कलंकित है, शरद ऋतु के पीले पत्ते-सा लगता है।","es":"Tu rostro supera toda comparación. A su lado, la luna, pálida de día y manchada, parece una hoja de otoño.","pt":"Teu rosto ofusca toda comparação. Ao lado dele, a lua, pálida de dia e marcada por uma mancha, parece uma folha de outono.","it":"Il tuo volto supera ogni paragone. Accanto a esso la luna, pallida di giorno e segnata da una macchia, sembra una foglia d’autunno.","gu":"તમારું મુખ દરેક ઉપમાથી ચઢિયાતું છે. તેની પાસે દિવસે ફિક્કો અને કલંકવાળો ચંદ્ર પાનખરના પાન જેવો લાગે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो ऋजुमदीणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo ṛjumadīṇaṃ"}],"mantra":[{"dev":"ॐ ह्रीं श्रीं हं सः ह्रौं ह्रां ह्रीं द्रां द्रीं द्रौं द्रः द्रः मोहिनी सर्व जन वश्यं कुरु कुरु स्वाहा।","iast":"Oṃ hrīṃ śrīṃ haṃ saḥ hrauṃ hrāṃ hrīṃ drāṃ drīṃ drauṃ draḥ draḥ mohinī sarva jana vaśyaṃ kuru kuru svāhā"}],"method":{"en":"Become pure, wear yellow clothes and, with a yellow rosary, for seven days recall the riddhi and the mantra 1,000 times each day, offering kundru (frankincense) incense. Eat one meal a day and sleep on the earth at night.","es":"Purifícate, vístete de amarillo y, con un rosario amarillo, durante siete días recuerda la riddhi y el mantra 1.000 veces al día, ofreciendo incienso de kundru (incienso de olíbano). Come una vez al día y duerme sobre la tierra por la noche.","hi":"पवित्र होकर पीले वस्त्र पहनकर पीली माला द्वारा सात दिन तक प्रतिदिन १००० बार ऋद्धि तथा मंत्र का स्मरण करते हुए कुंदरु की धूप क्षेपण करें। दिन में एक बार भोजन व रात में पृथ्वी पर शयन करना चाहिए।","pt":"Purifique-se, vista roupas amarelas e, com um rosário amarelo, durante sete dias recorde o riddhi e o mantra 1.000 vezes por dia, oferecendo incenso de kundru (olíbano). Faça uma refeição por dia e durma no chão à noite.","it":"Purificati, indossa abiti gialli e, con un rosario giallo, per sette giorni ricorda il riddhi e il mantra 1.000 volte al giorno, offrendo incenso di kundru (olibano). Fai un solo pasto al giorno e dormi per terra di notte.","gu":"શુદ્ધ થઈ, પીળાં વસ્ત્રો પહેરી, પીળી માળા વડે સાત દિવસ સુધી રોજ 1,000 વાર ઋદ્ધિ અને મંત્રનું સ્મરણ કરો અને કુંદરુનો ધૂપ અર્પણ કરો. દિવસમાં એક વાર ભોજન કરો અને રાત્રે જમીન પર સૂઓ."},"benefit":{"en":"By recalling the 13th verse, riddhi and mantra, keeping the yantra with you, and taking 7 pebbles, charging each one 108 times and throwing them in the four directions, thieves cannot steal and there is no kind of fear on the road.","es":"Al recordar el 13.º verso, la riddhi y el mantra, tener el yantra contigo y tomar 7 guijarros, cargar cada uno 108 veces y lanzarlos hacia las cuatro direcciones, los ladrones no pueden robar y en el camino no hay ninguna clase de temor.","hi":"१३ वाँ काव्य, ऋद्धि तथा मंत्र के स्मरण से एवं यंत्र पास रखने से तथा ७ कंकरी लेकर हरेक को १०८ बार मंत्रित कर चारों दिशाओं में फेंकने से चोर चोरी नहीं कर पाते तथा मार्ग में किसी प्रकार का भय नहीं रहता।","pt":"Recordando o 13º verso, o riddhi e o mantra, mantendo o yantra consigo, e pegando 7 seixos, carregando cada um 108 vezes e jogando-os nas quatro direções, os ladrões não conseguem roubar e não há nenhum tipo de medo no caminho.","it":"Ricordando il 13º verso, il riddhi e il mantra, tenendo con te lo yantra, e prendendo 7 sassolini, caricando ciascuno 108 volte e gettandoli nelle quattro direzioni, i ladri non riescono a rubare e non c’è alcun genere di timore lungo la strada.","gu":"13મા શ્લોક, ઋદ્ધિ અને મંત્રનું સ્મરણ કરવાથી, યંત્ર પોતાની પાસે રાખવાથી અને 7 કાંકરા લઈ દરેકને 108 વાર અભિમંત્રિત કરી ચારે દિશાઓમાં ફેંકવાથી ચોર ચોરી કરી શકતા નથી અને માર્ગમાં કોઈ પ્રકારનો ભય રહેતો નથી."}},{"n":14,"sa":["सम्पूर्ण-मण्डल-शशांक-कला कलाप-","शुभ्रा गुणास्त्रिभुवनं तव लङ्घयन्ति।","ये संश्रितास्त्रिजगदीश्वर-नाथमेकं,","कस्तान्निवारयति संचरतो यथेष्टम् ।।१४।।"],"pron":["sampūrṇa-maṇḍala-śaśāṃka-kalā kalāpa-","śubhrā guṇāstribhuvanaṃ tava laṅghayanti|","ye saṃśritāstrijagadīśvara-nāthamekaṃ,","kastānnivārayati saṃcarato yatheṣṭam ||14||"],"title":{"en":"Virtue without boundaries","hi":"सीमाओं से परे गुण","es":"Una virtud sin fronteras","pt":"Virtude sem fronteiras","it":"Virtù senza confini","gu":"સીમા વગરનો ગુણ"},"meaning":{"en":"Your pure virtues, bright as the full moon, spread through all three worlds, and whoever takes shelter in the one Lord walks freely, without anyone to hold them back.","hi":"पूर्ण चंद्र-सी उज्ज्वल आपकी पवित्र गुण-राशि तीनों लोकों में फैली है, और जो एकमात्र प्रभु की शरण लेता है वह बिना किसी रुकावट स्वतंत्र विचरता है।","es":"Tus puras virtudes, brillantes como la luna llena, se extienden por los tres mundos, y quien se refugia en el único Señor camina libre, sin nadie que lo detenga.","pt":"Tuas virtudes puras, brilhantes como a lua cheia, espalham-se pelos três mundos, e quem se abriga no único Senhor caminha livre, sem ninguém que o detenha.","it":"Le tue virtù pure, luminose come la luna piena, si spandono nei tre mondi, e chi si rifugia nell’unico Signore cammina libero, senza nessuno che lo trattenga.","gu":"પૂર્ણિમાના ચંદ્ર જેવા ઉજ્જવળ તમારા શુદ્ધ ગુણો ત્રણે લોકમાં ફેલાયેલા છે, અને જે એક પ્રભુનું શરણ લે છે તે કોઈના અટકાવ્યા વિના મુક્તપણે વિચરે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो विउलमदीणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo viulamadīṇaṃ"}],"mantra":[{"dev":"ॐ नमो भगवती गुणवती महामानसी नमः स्वाहा।","iast":"Oṃ namo bhagavatī guṇavatī mahāmānasī namaḥ svāhā"}],"method":{"en":"Become pure, wear white clothes and, with a crystal rosary, recite the fourteenth verse, the riddhi and the mantra 108 times in each of the three daily periods. Light a lamp and offer incense. Perform the homa every day with guggul, musk, saffron, camphor, shilaras, ratnanjali, agar-tagar incense, ghee and so on.","es":"Purifícate, vístete de blanco y, con un rosario de cristal, recita 108 veces el decimocuarto verso, la riddhi y el mantra en cada uno de los tres momentos del día. Enciende una lámpara y ofrece incienso. Realiza cada día el homa con guggul, almizcle, azafrán, alcanfor, shilaras, ratnanjali, incienso de agar-tagar, ghee, etcétera.","hi":"पवित्र होकर सफेद वस्त्र धारण कर स्फटिक मणि की माला द्वारा प्रतिदिन तीनों काल १०८ बार चौदहवाँ काव्य, ऋद्धि तथा मंत्र का आराधन करें, दीपक जलावें, धूप प्रक्षेपण करें। गुग्गुल, कस्तूरी, केशर, कपूर, शिलारस, रत्नाञ्जलि, अगर-तगर, धूप घी आदि से प्रतिदिन होम करना चाहिए।","pt":"Purifique-se, vista roupas brancas e, com um rosário de cristal, recite o décimo quarto verso, o riddhi e o mantra 108 vezes em cada um dos três períodos do dia. Acenda uma lamparina e ofereça incenso. Realize o homa todos os dias com guggul, almíscar, açafrão, cânfora, shilaras, ratnanjali, incenso de agar-tagar, ghee e assim por diante.","it":"Purificati, indossa abiti bianchi e, con un rosario di cristallo, recita il quattordicesimo verso, il riddhi e il mantra 108 volte in ciascuno dei tre momenti del giorno. Accendi una lampada e offri incenso. Compi ogni giorno l’homa con guggul, muschio, zafferano, canfora, shilaras, ratnanjali, incenso di agar-tagar, ghi e così via.","gu":"શુદ્ધ થઈ, સફેદ વસ્ત્રો પહેરી, સ્ફટિકની માળા વડે ચૌદમો શ્લોક, ઋદ્ધિ અને મંત્ર દિવસના ત્રણે સમયે 108 વાર બોલો. દીપક પ્રગટાવો અને ધૂપ અર્પણ કરો. દરરોજ ગુગળ, કસ્તૂરી, કેસર, કપૂર, શિલારસ, રત્નાંજલિ, અગર-તગરનો ધૂપ, ઘી વગેરેથી હોમ કરો."},"benefit":{"en":"Keeping the yantra with you, and taking seven pebbles, charging each one 21 times with the mantra and throwing them around: mental and bodily affliction (adhi, vyadhi) and fear of enemies are destroyed. Wealth (Lakshmi) is gained and the intellect grows. Goddess Saraswati becomes pleased.","es":"Con el yantra a tu lado, y tomando siete guijarros, cargando cada uno 21 veces con el mantra y lanzándolos alrededor, se destruyen las aflicciones de la mente y del cuerpo (adhi, vyadhi) y el temor a los enemigos. Se alcanza la prosperidad (Lakshmi) y crece la inteligencia. La diosa Saraswati se complace.","hi":"यंत्र पास रखने से तथा सात कंकरी लेकर प्रत्येक को २१ बार मंत्रित कर चारों ओर फेंकने से आधि, व्याधि और शत्रु भय नाश होता है। लक्ष्मी की प्राप्ति होती है तथा बुद्धि का विकास होता है। सरस्वती देवी प्रसन्न होती है।","pt":"Mantendo o yantra consigo, e pegando sete seixos, carregando cada um 21 vezes com o mantra e lançando-os ao redor, destroem-se a aflição da mente e do corpo (adhi, vyadhi) e o medo dos inimigos. Alcança-se a riqueza (Lakshmi) e a inteligência cresce. A deusa Saraswati fica satisfeita.","it":"Tenendo con te lo yantra, e prendendo sette sassolini, caricando ciascuno 21 volte con il mantra e gettandoli intorno, si distruggono l’afflizione della mente e del corpo (adhi, vyadhi) e il timore dei nemici. Si ottiene ricchezza (Lakshmi) e l’intelletto cresce. La dea Saraswati ne è compiaciuta.","gu":"યંત્ર પોતાની પાસે રાખી, સાત કાંકરા લઈ દરેકને મંત્ર વડે 21 વાર અભિમંત્રિત કરી ચારે બાજુ ફેંકવાથી માનસિક અને શારીરિક પીડા (આધિ, વ્યાધિ) અને શત્રુઓનો ભય નાશ પામે છે. લક્ષ્મી (ધન) પ્રાપ્ત થાય છે અને બુદ્ધિ વધે છે. દેવી સરસ્વતી પ્રસન્ન થાય છે."}},{"n":15,"sa":["चित्रं किमत्र यदि ते त्रिदशांगनाभि-","र्नीतं मनागपि मनो न विकार-मार्गम्।","कल्पान्त-काल-मरुता चलिता-चलेन,","किं मन्दराद्रि-शिखरं चलितं कदाचित्।।१५।।"],"pron":["citraṃ kimatra yadi te tridaśāṃganābhi-","rnītaṃ manāgapi mano na vikāra-mārgam|","kalpānta-kāla-marutā calitā-calena,","kiṃ mandarādri-śikharaṃ calitaṃ kadācit||15||"],"title":{"en":"The unshaken mountain","hi":"अडिग पर्वत","es":"La montaña inquebrantable","pt":"A montanha inabalável","it":"La montagna incrollabile","gu":"અડગ પર્વત"},"meaning":{"en":"Heavenly nymphs, with every charm, could not stir your mind. The storm at the end of time shakes ordinary hills, but never great Mount Meru.","hi":"अप्सराएँ अपने हाव-भावों से भी आपके मन को विचलित न कर सकीं। प्रलय की आँधी साधारण पर्वतों को हिला देती है, पर महान सुमेरु को कभी नहीं।","es":"Las ninfas celestiales, con todos sus encantos, no pudieron agitar tu mente. La tormenta del fin de los tiempos sacude las colinas comunes, pero nunca al gran monte Meru.","pt":"Ninfas celestiais, com todos os seus encantos, não puderam abalar a tua mente. A tempestade do fim dos tempos sacode as colinas comuns, mas jamais o grande monte Meru.","it":"Le ninfe celesti, con ogni loro fascino, non poterono smuovere la tua mente. La tempesta della fine dei tempi scuote le colline comuni, ma mai il grande monte Meru.","gu":"સર્વ આકર્ષણોથી સજ્જ સ્વર્ગની અપ્સરાઓ પણ તમારા મનને ડગાવી શક્યાં નહીં. પ્રલયકાળનું તોફાન સામાન્ય ટેકરીઓને હલાવે છે, પરંતુ મહાન મેરુ પર્વતને ક્યારેય નહીં."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो दसपुव्वीणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo dasapuvvīṇaṃ"}],"mantra":[{"dev":"ॐ नमो अचिन्त्य बल पराक्रमाय सर्वार्थकाम रूपाय ह्रां ह्रीं क्रौं श्रीं नमः।","iast":"Oṃ namo acintya bala parākramāya sarvārthakāma rūpāya hrāṃ hrīṃ krauṃ śrīṃ namaḥ"}],"method":{"en":"After bathing, wear red clothes, sit on a red seat and, with a red coral rosary, for 14 days recall the 15th verse, the riddhi and the mantra every day, offering dashang incense. Also eat one meal a day, every day.","es":"Después de bañarte, vístete de rojo, siéntate en un asiento rojo y, con un rosario rojo de coral, durante 14 días recuerda cada día el verso 15, la riddhi y el mantra, ofreciendo incienso dashang. Además, come una sola vez al día, todos los días.","hi":"स्नान करके लाल रंग के वस्त्र धारण कर, लाल आसन पर बैठकर, मूँगा की लाल माला द्वारा १४ दिन तक प्रतिदिन १५वाँ काव्य, ऋद्धि तथा मंत्र का स्मरण करते हुए दशांग धूप का क्षेपण करना चाहिए तथा प्रतिदिन एकाशन करना चाहिए।","pt":"Depois do banho, vista roupas vermelhas, sente-se em um assento vermelho e, com um rosário de coral vermelho, durante 14 dias recorde o 15º verso, o riddhi e o mantra todos os dias, oferecendo incenso dashang. Faça também uma refeição por dia, todos os dias.","it":"Dopo il bagno, indossa abiti rossi, siediti su un sedile rosso e, con un rosario di corallo rosso, per 14 giorni ricorda ogni giorno il 15º verso, il riddhi e il mantra, offrendo incenso dashang. Fai inoltre un solo pasto al giorno, ogni giorno.","gu":"સ્નાન કરી લાલ વસ્ત્રો પહેરો, લાલ આસન પર બેસો અને લાલ પરવાળાની માળા વડે 14 દિવસ સુધી રોજ 15મો શ્લોક, ઋદ્ધિ અને મંત્ર યાદ કરો અને દશાંગ ધૂપ અર્પણ કરો. રોજ દિવસમાં એક જ વાર ભોજન પણ કરો."},"benefit":{"en":"Charge oil 21 times with the riddhi and mantra above and apply it to the face: influence in the royal court increases, honour is gained and wealth (Lakshmi) is received. By repeatedly recalling this riddhi and mantra, and by tying the yantra on the upper arm, vital strength is protected and nocturnal emissions never occur.","es":"Carga aceite 21 veces con la riddhi y el mantra anteriores y aplícalo en el rostro: aumenta la influencia en la corte real, se recibe honor y se alcanza la prosperidad (Lakshmi). Con el recuerdo repetido de esta riddhi y este mantra, y atando el yantra en el brazo, se protege la fuerza vital y nunca ocurren emisiones nocturnas.","hi":"उपरोक्त ऋद्धि मंत्र द्वारा २१ बार तेल मंत्रित कर मुख पर लगाने से राजदरबार में प्रभाव बढ़ता है, सम्मान प्राप्त होता है और लक्ष्मी की प्राप्ति होती है। इस ऋद्धि मंत्र के बारम्बार स्मरण से तथा भुजा पर यंत्र बाँधने से वीर्य की रक्षा होती है और स्वप्नदोष कभी नहीं होता।","pt":"Carregue óleo 21 vezes com o riddhi e o mantra acima e aplique-o no rosto: aumenta a influência na corte real, ganha-se honra e recebe-se riqueza (Lakshmi). Recordando repetidamente este riddhi e mantra, e amarrando o yantra no alto do braço, a força vital é protegida e nunca ocorrem emissões noturnas.","it":"Carica olio 21 volte con il riddhi e il mantra sopra indicati e applicalo sul viso: cresce l’influenza alla corte reale, si ottiene onore e si riceve ricchezza (Lakshmi). Ricordando di continuo questo riddhi e mantra, e legando lo yantra sulla parte alta del braccio, la forza vitale è protetta e non si verificano mai emissioni notturne.","gu":"ઉપરોક્ત ઋદ્ધિ અને મંત્ર વડે તેલને 21 વાર અભિમંત્રિત કરી ચહેરા પર લગાવો: રાજદરબારમાં પ્રભાવ વધે છે, માન મળે છે અને લક્ષ્મી (ધન) પ્રાપ્ત થાય છે. આ ઋદ્ધિ અને મંત્રનું વારંવાર સ્મરણ કરવાથી અને યંત્રને બાવડા પર બાંધવાથી જીવનશક્તિ સચવાય છે અને સ્વપ્નદોષ ક્યારેય થતો નથી."}},{"n":16,"sa":["निर्धूम-वर्त्ति-रपवर्जित-तैलपूरः,","कृत्स्नं जगत्त्रयमिदं प्रकटी-करोषि।","गम्यो न जातु मरुतां चलिता-चलानां,","दीपोऽपरस्त्वमसि नाथ जगत्प्रकाशः।।१६।।"],"pron":["nirdhūma-vartti-rapavarjita-tailapūraḥ,","kṛtsnaṃ jagattrayamidaṃ prakaṭī-karoṣi|","gamyo na jātu marutāṃ calitā-calānāṃ,","dīpo’parastvamasi nātha jagatprakāśaḥ||16||"],"title":{"en":"The unfailing lamp","hi":"कभी न बुझने वाला दीप","es":"La lámpara que no se apaga","pt":"A lamparina que nunca falha","it":"La lampada che non vacilla","gu":"કદી ન બુઝાતો દીવો"},"meaning":{"en":"You are a lamp unlike any other: no smoke, no wick, no oil, never put out by the winds that shake mountains, and lighting all three worlds.","hi":"आप एक अनोखे दीपक हैं: न धुआँ, न बाती, न तेल; पर्वतों को हिला देने वाली हवाएँ भी जिसे बुझा नहीं सकतीं, और जो तीनों लोकों को प्रकाशित करता है।","es":"Eres una lámpara sin igual: sin humo, sin mecha, sin aceite, que ni los vientos que sacuden las montañas pueden apagar, y que ilumina los tres mundos.","pt":"És uma lamparina diferente de todas: sem fumaça, sem pavio, sem óleo, jamais apagada pelos ventos que sacodem as montanhas, e iluminando os três mundos.","it":"Sei una lampada diversa da ogni altra: senza fumo, senza stoppino, senza olio, mai spenta dai venti che scuotono le montagne, e che illumina i tre mondi.","gu":"તમે એવો દીવો છો જેવો બીજો કોઈ નથી: ન ધુમાડો, ન વાટ, ન તેલ, પર્વતોને હલાવી દેનારા પવનોથી પણ ક્યારેય ન બુઝાતો, અને ત્રણે લોકને પ્રકાશિત કરતો."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो चउदसपुव्वीणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo caudasapuvvīṇaṃ"}],"mantra":[{"dev":"ॐ नमः सुमंगला सुसीमा नामदेवी सर्वसमीहितार्थं वज्रश्रृंखलां कुरु कुरु नमः स्वाहा।","iast":"Oṃ namaḥ sumaṃgalā susīmā nāmadevī sarvasamīhitārthaṃ vajraśrṛṃkhalāṃ kuru kuru namaḥ svāhā"}],"method":{"en":"After bathing, for 9 days recall the sixteenth verse, the riddhi and the mantra 1,000 times each day with a green rosary, offering kundru (frankincense) incense.","es":"Después de bañarte, durante 9 días recuerda cada día, con un rosario verde, el decimosexto verso, la riddhi y el mantra 1.000 veces, ofreciendo incienso de kundru (incienso de olíbano).","hi":"स्नान करके ९ दिन तक प्रतिदिन हरे रंग की माला से १००० बार सोलहवाँ काव्य ऋद्धि तथा मंत्र स्मरण करते हुए कुंदरु की धूप क्षेपण करना चाहिए।","pt":"Depois do banho, durante 9 dias recorde o décimo sexto verso, o riddhi e o mantra 1.000 vezes por dia com um rosário verde, oferecendo incenso de kundru (olíbano).","it":"Dopo il bagno, per 9 giorni ricorda il sedicesimo verso, il riddhi e il mantra 1.000 volte al giorno con un rosario verde, offrendo incenso di kundru (olibano).","gu":"સ્નાન કરીને, લીલી માળા વડે 9 દિવસ સુધી રોજ સોળમો શ્લોક, ઋદ્ધિ અને મંત્ર 1,000 વાર યાદ કરો અને કુંદરુનો ધૂપ અર્પણ કરો."},"benefit":{"en":"Keeping the yantra with you, and going to the royal court after recalling the riddhi and mantra 108 times with pure feeling, the opponent is defeated and there is no fear of enemies. Moreover, sprinkling water charged with this same riddhi and mantra calms every kind of fire.","es":"Con el yantra a tu lado, y acudiendo a la corte real tras recordar 108 veces la riddhi y el mantra con sentimiento puro, el oponente es derrotado y no hay temor a los enemigos. Además, rociar agua cargada con esta misma riddhi y este mantra calma toda clase de fuego.","hi":"यंत्र को पास में रखने से तथा १०८ बार शुद्ध भावों से ऋद्धि मंत्र का स्मरण कर राजदरबार में पहुँचने से प्रतिपक्षी पराजित होता है और शत्रु का भय नहीं रहता। पुनश्च इसी ऋद्धि मंत्र द्वारा जल मंत्रित कर छिड़कने से हर प्रकार की अग्नि शान्त हो जाती है।","pt":"Mantendo o yantra consigo, e indo à corte real depois de recordar o riddhi e o mantra 108 vezes com sentimento puro, o adversário é derrotado e não há medo de inimigos. Além disso, borrifar água carregada com este mesmo riddhi e mantra acalma todo tipo de fogo.","it":"Tenendo con te lo yantra, e recandoti alla corte reale dopo aver ricordato il riddhi e il mantra 108 volte con sentimento puro, l’avversario è sconfitto e non c’è timore dei nemici. Inoltre, spruzzare acqua caricata con questo stesso riddhi e mantra placa ogni tipo di fuoco.","gu":"યંત્ર પોતાની પાસે રાખી, શુદ્ધ ભાવથી ઋદ્ધિ અને મંત્ર 108 વાર યાદ કરીને રાજદરબારમાં જવાથી વિરોધી પરાજિત થાય છે અને શત્રુઓનો ભય રહેતો નથી. વળી, આ જ ઋદ્ધિ અને મંત્રથી અભિમંત્રિત કરેલું પાણી છાંટવાથી દરેક પ્રકારની આગ શાંત થાય છે."}},{"n":17,"sa":["नास्तं कदाचिदुपयासि न राहु-गम्यः,","स्पष्टी-करोषि सहसा युगपज्जगन्ति।","नाम्भोधरोदर-निरुद्ध-महा-प्रभावः,","सूर्यातिशायि-महिमासि मुनीन्द्र लोके।।१७।।"],"pron":["nāstaṃ kadācidupayāsi na rāhu-gamyaḥ,","spaṣṭī-karoṣi sahasā yugapajjaganti|","nāmbhodharodara-niruddha-mahā-prabhāvaḥ,","sūryātiśāyi-mahimāsi munīndra loke||17||"],"title":{"en":"A sun that never sets","hi":"सूर्य जो कभी अस्त नहीं होता","es":"Un sol que nunca se pone","pt":"Um sol que nunca se põe","it":"Un sole che non tramonta mai","gu":"કદી ન આથમતો સૂર્ય"},"meaning":{"en":"You are a sun beyond the sun: you never set, no eclipse swallows you, and no cloud can hide you.","hi":"आप सूर्य से भी बढ़कर सूर्य हैं: न आप अस्त होते हैं, न राहु आपको निगलता है, न बादल आपको ढक सकते हैं।","es":"Eres un sol más allá del sol: nunca te pones, ningún eclipse te devora y ninguna nube puede ocultarte.","pt":"És um sol acima do sol: nunca te pões, nenhum eclipse te engole e nenhuma nuvem te pode esconder.","it":"Sei un sole oltre il sole: non tramonti mai, nessuna eclissi ti inghiotte e nessuna nuvola può nasconderti.","gu":"તમે સૂર્યથી પણ પર સૂર્ય છો: કદી આથમતા નથી, કોઈ ગ્રહણ તમને ગળી શકતું નથી અને કોઈ વાદળ તમને ઢાંકી શકતું નથી."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो अष्टाङ्ग महानिमित्त कुसलाणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo aṣṭāṅga mahānimitta kusalāṇaṃ"}],"mantra":[{"dev":"ॐ णमो णमिऊण अट्टे मट्टे क्षुद्र विघट्टे क्षुद्रपीड़ा जठरपीड़ा भञ्जय भञ्जय सर्वपीड़ा सर्वरोग निवारणं कुरु कुरु नमः स्वाहा।","iast":"Oṃ ṇamo ṇamiūṇa aṭṭe maṭṭe kṣudra vighaṭṭe kṣudrapīr̤ā jaṭharapīr̤ā bhañjaya bhañjaya sarvapīr̤ā sarvaroga nivāraṇaṃ kuru kuru namaḥ svāhā"}],"method":{"en":"With pure feeling, for seven days in a row recall the 17th verse, the riddhi and the mantra 1,000 times each day with a white rosary, offering sandalwood incense.","es":"Con sentimiento puro, durante siete días seguidos recuerda cada día 1.000 veces el verso 17, la riddhi y el mantra con un rosario blanco, ofreciendo incienso de sándalo.","hi":"पवित्र भावों से सात दिन तक प्रतिदिन सफेद माला द्वारा १००० वार १७ वाँ काव्य, ऋद्धि तथा मंत्र स्मरण करते हुए चंदन की धूप क्षेपण करना चाहिए।","pt":"Com sentimento puro, durante sete dias seguidos recorde o 17º verso, o riddhi e o mantra 1.000 vezes por dia com um rosário branco, oferecendo incenso de sândalo.","it":"Con sentimento puro, per sette giorni consecutivi ricorda il 17º verso, il riddhi e il mantra 1.000 volte al giorno con un rosario bianco, offrendo incenso di sandalo.","gu":"શુદ્ધ ભાવથી સતત સાત દિવસ સુધી સફેદ માળા વડે રોજ 17મો શ્લોક, ઋદ્ધિ અને મંત્ર 1,000 વાર યાદ કરો અને ચંદનનો ધૂપ અર્પણ કરો."},"benefit":{"en":"By tying on the yantra, and by giving untouched pure water charged 21 times with the riddhi and mantra to drink, incurable abdominal pain, wind-balls (vayugola), wind-colic (vayushool) and similar illnesses go away.","es":"Atando el yantra y dando a beber agua pura, intacta, cargada 21 veces con la riddhi y el mantra, desaparecen el dolor abdominal incurable, las bolas de aire (vayugola), el cólico ventoso (vayushool) y otros males semejantes.","hi":"यंत्र को बाँधने से तथा अछूता शुद्ध जल ऋद्धि मंत्र द्वारा इक्कीस वार मंत्रित कर पिलाने से उदर की असाध्य पीड़ा, वायुगोला, वायुशूल आदिरोग दूर होते हैं।","pt":"Amarrando o yantra no corpo e dando para beber água pura, intocada, carregada 21 vezes com o riddhi e o mantra, desaparecem a dor abdominal incurável, as bolas de gases (vayugola), a cólica de gases (vayushool) e doenças semelhantes.","it":"Legando addosso lo yantra e dando da bere acqua pura, intatta, caricata 21 volte con il riddhi e il mantra, scompaiono il dolore addominale incurabile, le palle di gas (vayugola), la colica da gas (vayushool) e malattie simili.","gu":"યંત્ર બાંધવાથી અને ઋદ્ધિ તથા મંત્ર વડે 21 વાર અભિમંત્રિત કરેલું અણસ્પર્શ્યું શુદ્ધ પાણી પીવડાવવાથી અસાધ્ય પેટનો દુખાવો, વાયુગોળો, વાયુશૂળ અને તેવા રોગો દૂર થાય છે."}},{"n":18,"sa":["नित्योदयं दलित-मोह-महान्धकारं।","गम्यं न राहु-वदनस्य न वारिदानाम्।।","विभ्राजते तव मुखाब्ज-मनल्प-कान्ति,","विद्योतयज्जगदपूर्वशशाङ्कबिम्बम् ।।१८।।"],"pron":["nityodayaṃ dalita-moha-mahāndhakāraṃ|","gamyaṃ na rāhu-vadanasya na vāridānām||","vibhrājate tava mukhābja-manalpa-kānti,","vidyotayajjagadapūrvaśaśāṅkabimbam ||18||"],"title":{"en":"The moon of understanding","hi":"समझ का चंद्रमा","es":"La luna de la comprensión","pt":"A lua da compreensão","it":"La luna della comprensione","gu":"સમજણનો ચંદ્ર"},"meaning":{"en":"Your lotus face is a moon that is always rising. Rahu cannot reach it, clouds cannot cover it, and it scatters the heavy darkness of delusion.","hi":"आपका कमल-सा मुख सदा उदित रहने वाला चंद्रमा है। राहु उस तक नहीं पहुँचता, बादल उसे ढकते नहीं, और वह मोह के घने अंधकार को बिखेर देता है।","es":"Tu rostro de loto es una luna siempre naciente. Rahu no puede alcanzarla, las nubes no la cubren, y dispersa la densa oscuridad de la ilusión.","pt":"Teu rosto de lótus é uma lua que está sempre nascendo. Rahu não a alcança, as nuvens não a cobrem, e ela dispersa a densa escuridão da ilusão.","it":"Il tuo volto di loto è una luna che sorge sempre. Rahu non può raggiungerla, le nuvole non possono coprirla, ed essa disperde la fitta oscurità dell’illusione.","gu":"તમારું કમળ જેવું મુખ સદા ઊગતો ચંદ્ર છે. તેને રાહુ પહોંચી શકતો નથી, વાદળો ઢાંકી શકતાં નથી, અને તે મોહના ગાઢ અંધકારને વિખેરી નાખે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो विउयणयड्ढि पत्ताणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo viuyaṇayaḍḍhi pattāṇaṃ"}],"mantra":[{"dev":"ॐ नमो शास्त्र ज्ञानबोधनाय परमर्द्धि प्राप्ति जयंकराय ह्रां ह्रीं क्रौं श्रीं नमः।","iast":"Oṃ namo śāstra jñānabodhanāya paramarddhi prāpti jayaṃkarāya hrāṃ hrīṃ krauṃ śrīṃ namaḥ"}],"method":{"en":"Become pure and, with a red rosary, for seven days in a row recite the eighteenth verse, the riddhi and the mantra 1,000 times each day, offering dashang incense. Eat one pure meal a day.","es":"Purifícate y, con un rosario rojo, durante siete días seguidos recita 1.000 veces al día el decimoctavo verso, la riddhi y el mantra, ofreciendo incienso dashang. Come una sola comida pura al día.","hi":"पवित्र होकर लाल रंग की माला द्वारा सात दिन तक प्रतिदिन एक हजार बार अठारहवाँ काव्य, ऋद्धि तथा मंत्र स्मरण करते हुए दशांग धूप क्षेपण किया जाता है। दिन में एक बार शुद्ध भोजन करना चाहिए।","pt":"Purifique-se e, com um rosário vermelho, durante sete dias seguidos recite o décimo oitavo verso, o riddhi e o mantra 1.000 vezes por dia, oferecendo incenso dashang. Faça uma refeição pura por dia.","it":"Purificati e, con un rosario rosso, per sette giorni consecutivi recita il diciottesimo verso, il riddhi e il mantra 1.000 volte al giorno, offrendo incenso dashang. Fai un solo pasto puro al giorno.","gu":"શુદ્ધ થઈ, લાલ માળા વડે સતત સાત દિવસ સુધી રોજ અઢારમો શ્લોક, ઋદ્ધિ અને મંત્ર 1,000 વાર બોલો અને દશાંગ ધૂપ અર્પણ કરો. દિવસમાં એક વાર શુદ્ધ ભોજન કરો."},"benefit":{"en":"Keeping the yantra with you and recalling the riddhi and mantra 108 times halts the enemy's army. In the mind of the devotee who practises this mantra, useless thoughts and doubts do not arise. Worry, anger, harmful meditation, delusion and false belief are destroyed, and the mind stays steady in dharma meditation.","es":"Tener el yantra contigo y recordar 108 veces la riddhi y el mantra detiene al ejército enemigo. En la mente del devoto que practica este mantra no surgen pensamientos ni dudas inútiles. Se destruyen la preocupación, la ira, la meditación dañina, la confusión y la falsa creencia, y la mente permanece firme en la meditación del dharma.","hi":"यंत्र को पास रखने से तथा १०८ बार ऋद्धि मंत्र के स्मरण से शत्रु की सेना का स्तम्भन होता है। इस मंत्र का आराधन करने वाले आराधक के मन में व्यर्थ के संकल्प विकल्प पैदा नहीं होते। चिन्ता, कोप, दुर्ध्यान, मोह, मिथ्यात्व का नाश होता है तथा धर्म ध्यान में चित्त स्थिर रहता है।","pt":"Mantendo o yantra consigo e recordando o riddhi e o mantra 108 vezes, detém-se o exército do inimigo. Na mente do devoto que pratica este mantra não surgem pensamentos inúteis nem dúvidas. Preocupação, raiva, meditação nociva, ilusão e crença falsa são destruídas, e a mente permanece firme na meditação do dharma.","it":"Tenendo con te lo yantra e ricordando il riddhi e il mantra 108 volte, si ferma l’esercito del nemico. Nella mente del devoto che pratica questo mantra non sorgono pensieri inutili né dubbi. Preoccupazione, collera, meditazione dannosa, illusione e falsa credenza vengono distrutte, e la mente resta salda nella meditazione sul dharma.","gu":"યંત્ર પોતાની પાસે રાખી ઋદ્ધિ અને મંત્ર 108 વાર યાદ કરવાથી શત્રુનું સૈન્ય અટકી જાય છે. આ મંત્રની સાધના કરનાર ભક્તના મનમાં નકામા વિચારો અને શંકાઓ ઊઠતાં નથી. ચિંતા, ક્રોધ, અશુભ ધ્યાન, મોહ અને મિથ્યા માન્યતા નાશ પામે છે, અને મન ધર્મધ્યાનમાં સ્થિર રહે છે."}},{"n":19,"sa":["किं शर्वरीषु शशिनाऽह्नि विवस्वता वा,","युष्मन्मुखेन्दु-दलितेषु तमःसु नाथ।","निष्पन्न-शालि-वन-शालिनि जीव-लोके,","कार्यं कियज्-जलधरैर्जल-भारनम्रैः।।१९।।"],"pron":["kiṃ śarvarīṣu śaśinā’hni vivasvatā vā,","yuṣmanmukhendu-daliteṣu tamaḥsu nātha|","niṣpanna-śāli-vana-śālini jīva-loke,","kāryaṃ kiyaj-jaladharairjala-bhāranamraiḥ||19||"],"title":{"en":"The fulfilled field","hi":"भरा हुआ खेत","es":"El campo ya colmado","pt":"O campo realizado","it":"Il campo giunto a maturazione","gu":"પાકી ગયેલું ખેતર"},"meaning":{"en":"Your face sweeps away the darkness of ignorance. What need then of the sun by day or the moon by night? Once the crop is ripe, who needs rain clouds?","hi":"आपका मुख अज्ञान के अंधकार को हर लेता है। फिर दिन में सूर्य और रात में चंद्रमा की क्या आवश्यकता? जब फसल पक चुकी हो, तब जल बरसाने वाले मेघों का क्या काम?","es":"Tu rostro barre la oscuridad de la ignorancia. ¿Qué falta hacen el sol de día o la luna de noche? Cuando la cosecha ya está madura, ¿para qué las nubes de lluvia?","pt":"Teu rosto varre a escuridão da ignorância. Que necessidade há então do sol de dia ou da lua de noite? Quando a colheita já amadureceu, quem precisa de nuvens de chuva?","it":"Il tuo volto spazza via l’oscurità dell’ignoranza. Che bisogno c’è allora del sole di giorno o della luna di notte? Quando il raccolto è maturo, chi ha bisogno di nuvole di pioggia?","gu":"તમારું મુખ અજ્ઞાનના અંધકારને દૂર કરે છે. તો પછી દિવસે સૂર્યની કે રાત્રે ચંદ્રની શી જરૂર? પાક પાકી ગયા પછી વરસાદનાં વાદળોની કોને જરૂર?"},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो विज्जाहराणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo vijjāharāṇaṃ"}],"mantra":[{"dev":"ॐ ह्रां ह्रीं ह्रूं ह्रः य क्ष ह्रीं वषट् नमः स्वाहा।","iast":"Oṃ hrāṃ hrīṃ hrūṃ hraḥ ya kṣa hrīṃ vaṣaṭ namaḥ svāhā"}],"method":{"en":"Every day in the early morning, bathe and put on pure clothes. With a focused mind, recall the nineteenth verse, the riddhi and the mantra 108 times.","es":"Cada día, de madrugada, báñate y ponte ropa limpia. Con la mente concentrada, recuerda 108 veces el decimonoveno verso, la riddhi y el mantra.","hi":"प्रतिदिन प्रातःकाल स्नान करके शुद्ध वस्त्र धारण करें तथा मन को एकाग्र करके उन्नीसवाँ काव्य, ऋद्धि तथा मंत्र का एक सौ आठ बार स्मरण करना चाहिए।","pt":"Todos os dias, de manhã cedo, tome banho e vista roupas puras. Com a mente concentrada, recorde o décimo nono verso, o riddhi e o mantra 108 vezes.","it":"Ogni giorno, di buon mattino, fai il bagno e indossa abiti puliti. Con la mente concentrata, ricorda il diciannovesimo verso, il riddhi e il mantra 108 volte.","gu":"દરરોજ વહેલી સવારે સ્નાન કરી શુદ્ધ વસ્ત્રો પહેરો. એકાગ્ર મનથી ઓગણીસમો શ્લોક, ઋદ્ધિ અને મંત્ર 108 વાર યાદ કરો."},"benefit":{"en":"Keeping the yantra with you, the mantras, spells, charms and black magic used against the devotee by others have no effect, and there is no fear of being driven away (uchchatan). If an unlucky person recalls this riddhi and mantra constantly, their livelihood begins to run smoothly. All comforts and conveniences become available.","es":"Con el yantra a tu lado, los mantras, hechizos, amuletos y magia negra que otros emplean contra el devoto no surten efecto, y no hay temor de ser desterrado (uchchatan). Si una persona desafortunada recuerda constantemente esta riddhi y este mantra, su sustento comienza a marchar bien. Todas las comodidades y facilidades se vuelven disponibles.","hi":"यंत्र को पास में रखने से आराधक पर प्रयोग किये हुए दूसरे के मंत्र, विद्या, टोटका, जादू मूठ आदि का प्रभाव नहीं पड़ता और न ही उच्चाटन का भय रहता है यदि कोई भाग्यहीन पुरुष इस ऋद्धि मंत्र का सतत स्मरण करें तो उसकी आजीविका सुचारु रूप से चलने लगती है। सभी सुख सुविधायें उपलब्ध होने लगती हैं।","pt":"Mantendo o yantra consigo, os mantras, feitiços, amuletos e magia negra usados contra o devoto por outros não têm efeito, e não há medo de ser expulso (uchchatan). Se uma pessoa azarada recorda constantemente este riddhi e mantra, seu sustento começa a fluir sem obstáculos. Todos os confortos e facilidades tornam-se acessíveis.","it":"Tenendo con te lo yantra, i mantra, gli incantesimi, i talismani e la magia nera usati contro il devoto da altri non hanno effetto, e non c’è timore di essere scacciati (uchchatan). Se una persona sfortunata ricorda di continuo questo riddhi e mantra, il suo sostentamento comincia a scorrere senza intoppi. Tutti gli agi e le comodità diventano accessibili.","gu":"યંત્ર પોતાની પાસે રાખવાથી બીજાઓ દ્વારા ભક્ત પર કરવામાં આવેલા મંત્ર, ટોણા-ટોટકા અને કાળા જાદુની કોઈ અસર થતી નથી, અને ઉચ્ચાટનનો (ઉચાળા ભરાવી દેવાનો) ભય રહેતો નથી. કમનસીબ વ્યક્તિ આ ઋદ્ધિ અને મંત્ર સતત યાદ કરે તો તેની આજીવિકા સરળતાથી ચાલવા લાગે છે. બધી સુખ-સગવડો પ્રાપ્ત થાય છે."}},{"n":20,"sa":["ज्ञानं यथा त्वयि विभाति कृतावकाशं,","नैवं तथा हरि-हरादिषु नायकेषु।","तेजःस्फुरन्मणिषु याति यथा महत्त्वं,","नैवं तु काच-शकले किरणा-कुलेऽपि।।२०।।"],"pron":["jñānaṃ yathā tvayi vibhāti kṛtāvakāśaṃ,","naivaṃ tathā hari-harādiṣu nāyakeṣu|","tejaḥsphuranmaṇiṣu yāti yathā mahattvaṃ,","naivaṃ tu kāca-śakale kiraṇā-kule’pi||20||"],"title":{"en":"Knowledge like a jewel","hi":"रत्न-सा ज्ञान","es":"Conocimiento como una joya","pt":"Conhecimento como uma joia","it":"Conoscenza come un gioiello","gu":"રત્ન જેવું જ્ઞાન"},"meaning":{"en":"Knowledge shines in you completely, as light shows its full glory in a priceless gem and not in a piece of glass.","hi":"ज्ञान आपमें पूर्ण रूप से चमकता है, जैसे प्रकाश अपना पूरा वैभव अमूल्य रत्न में दिखाता है, काँच के टुकड़े में नहीं।","es":"El conocimiento brilla en ti por completo, como la luz muestra toda su gloria en una gema sin precio y no en un pedazo de vidrio.","pt":"O conhecimento resplandece em ti por inteiro, como a luz mostra toda a sua glória em uma gema inestimável e não em um pedaço de vidro.","it":"La conoscenza risplende in te per intero, come la luce mostra tutta la sua gloria in una gemma inestimabile e non in un pezzo di vetro.","gu":"જ્ઞાન તમારામાં સંપૂર્ણ રીતે પ્રકાશે છે, જેમ પ્રકાશ અમૂલ્ય રત્નમાં પોતાનો પૂર્ણ મહિમા દર્શાવે છે, કાચના ટુકડામાં નહીં."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो चारणाणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo cāraṇāṇaṃ"}],"mantra":[{"dev":"ॐ श्रां श्रीं श्रूं श्रः शत्रु भय निवारणाय ठः ठः नमः स्वाहा।","iast":"Oṃ śrāṃ śrīṃ śrūṃ śraḥ śatru bhaya nivāraṇāya ṭhaḥ ṭhaḥ namaḥ svāhā"},{"dev":"ॐ नमो भगवते पुत्रार्थ सौख्यं कुरु कुरु ह्रीं नमः स्वाहा।","iast":"oṃ namo bhagavate putrārtha saukhyaṃ kuru kuru hrīṃ namaḥ svāhā"}],"method":{"en":"In the morning, become pure, wear clean clothes, set up the yantra and worship it. Then sit facing east, recite the Namokar mantra nine times, and afterwards recall the twentieth verse, the riddhi and the mantra 108 times.","es":"Por la mañana, purifícate, ponte ropa limpia, coloca el yantra y adóralo. Luego siéntate mirando al este, recita nueve veces el mantra Namokar y después recuerda 108 veces el vigésimo verso, la riddhi y el mantra.","hi":"प्रातः पवित्र होकर शुद्ध वस्त्र पहनकर यंत्र स्थापित कर पूजा करें पश्चात् पूर्व दिशा की ओर मुख करके बैठकर नौ बार णमोकार मंत्र पढ़ें तदुपरान्त बीसवाँ काव्य, ऋद्धि तथा मंत्र का १०८ बार स्मरण करें।","pt":"De manhã, purifique-se, vista roupas limpas, coloque o yantra e adore-o. Depois sente-se voltado para o leste, recite o mantra Namokar nove vezes e, em seguida, recorde o vigésimo verso, o riddhi e o mantra 108 vezes.","it":"Al mattino, purificati, indossa abiti puliti, disponi lo yantra e adoralo. Poi siediti rivolto a est, recita il mantra Namokar nove volte e, dopo, ricorda il ventesimo verso, il riddhi e il mantra 108 volte.","gu":"સવારે શુદ્ધ થઈ, સ્વચ્છ વસ્ત્રો પહેરી, યંત્રની સ્થાપના કરી તેની પૂજા કરો. પછી પૂર્વ તરફ મુખ રાખી બેસો, નવકાર મંત્ર નવ વાર બોલો, અને પછી વીસમો શ્લોક, ઋદ્ધિ અને મંત્ર 108 વાર યાદ કરો."},"benefit":{"en":"Keeping the yantra with you and recalling the riddhi and mantra 108 times brings a child. Wealth (Lakshmi) is gained, good fortune increases, victory is achieved and the intellect grows.","es":"Tener el yantra contigo y recordar 108 veces la riddhi y el mantra trae un hijo. Se alcanza la prosperidad (Lakshmi), aumenta la buena fortuna, se logra la victoria y crece la inteligencia.","hi":"यंत्र को पास में रखने से तथा ऋद्धि मंत्र का एक सौ आठ बार स्मरण करने से सन्तान की प्राप्ति होती है लक्ष्मी का लाभ, सौभाग्य की वृद्धि, विजय प्राप्ति तथा बुद्धि का विकास होता है।","pt":"Mantendo o yantra consigo e recordando o riddhi e o mantra 108 vezes, vem um filho. Ganha-se riqueza (Lakshmi), a boa sorte aumenta, alcança-se a vitória e a inteligência cresce.","it":"Tenendo con te lo yantra e ricordando il riddhi e il mantra 108 volte, arriva un figlio. Si ottiene ricchezza (Lakshmi), la buona sorte aumenta, si consegue la vittoria e l’intelletto cresce.","gu":"યંત્ર પોતાની પાસે રાખી ઋદ્ધિ અને મંત્ર 108 વાર યાદ કરવાથી સંતાનપ્રાપ્તિ થાય છે. લક્ષ્મી (ધન) મળે છે, સૌભાગ્ય વધે છે, વિજય પ્રાપ્ત થાય છે અને બુદ્ધિ વધે છે."}},{"n":21,"sa":["मन्ये वरं हरि-हरादय एव दृष्टा,","दृष्टेषु येषु हृदयं त्वयि तोषमेति।","किं वीक्षितेन भवता भुवि येन नान्यः,","कश्चिन्मनो हरति नाथ भवान्तरेऽपि।।२१।।"],"pron":["manye varaṃ hari-harādaya eva dṛṣṭā,","dṛṣṭeṣu yeṣu hṛdayaṃ tvayi toṣameti|","kiṃ vīkṣitena bhavatā bhuvi yena nānyaḥ,","kaścinmano harati nātha bhavāntare’pi||21||"],"title":{"en":"A heart at rest","hi":"विश्रांत हृदय","es":"Un corazón en reposo","pt":"Um coração em repouso","it":"Un cuore in pace","gu":"વિશ્રામ પામેલું હૃદય"},"meaning":{"en":"I believe it was for the best that I saw other deities first. Having seen you, my heart finds contentment in no one else, now or in lives to come.","hi":"मैं मानता हूँ कि पहले अन्य देवों को देखना अच्छा ही रहा। आपको देख लेने के बाद मेरा हृदय किसी और में संतोष नहीं पाता, न अभी, न आने वाले जन्मों में।","es":"Creo que fue para bien haber visto primero a otras deidades. Después de verte, mi corazón no encuentra contento en nadie más, ni ahora ni en vidas futuras.","pt":"Creio que foi para o melhor que vi primeiro outras divindades. Depois de te ver, meu coração não encontra contentamento em mais ninguém, nem agora nem em vidas futuras.","it":"Credo sia stato un bene aver visto prima altre divinità. Dopo aver visto te, il mio cuore non trova appagamento in nessun altro, né ora né nelle vite a venire.","gu":"મને લાગે છે કે મેં પહેલાં બીજા દેવોને જોયા તે સારું જ થયું. તમને જોયા પછી મારું હૃદય હવે કે આવનારા જન્મોમાં બીજા કોઈમાં સંતોષ પામતું નથી."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो पण्ण समणाणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo paṇṇa samaṇāṇaṃ"}],"mantra":[{"dev":"ॐ नमो भगवते शत्रुभय निवारणाय नमः स्वाहा।","iast":"Oṃ namo bhagavate śatrubhaya nivāraṇāya namaḥ svāhā"}],"method":{"en":"Become pure, wear red clothes and, with a red rosary, for forty-two days recall the twenty-first verse, the riddhi and the mantra 108 times each day.","es":"Purifícate, vístete de rojo y, con un rosario rojo, durante cuarenta y dos días recuerda cada día 108 veces el vigésimo primer verso, la riddhi y el mantra.","hi":"पवित्र होकर लाल वस्त्र धारण कर लाल माला द्वारा बयालीस दिन तक प्रतिदिन १०८ वार इक्कीसवाँ काव्य, ऋद्धि तथा मंत्र का स्मरण करना चाहिए।","pt":"Purifique-se, vista roupas vermelhas e, com um rosário vermelho, durante quarenta e dois dias recorde o vigésimo primeiro verso, o riddhi e o mantra 108 vezes por dia.","it":"Purificati, indossa abiti rossi e, con un rosario rosso, per quarantadue giorni ricorda il ventunesimo verso, il riddhi e il mantra 108 volte al giorno.","gu":"શુદ્ધ થઈ, લાલ વસ્ત્રો પહેરી, લાલ માળા વડે બેંતાલીસ દિવસ સુધી રોજ એકવીસમો શ્લોક, ઋદ્ધિ અને મંત્ર 108 વાર યાદ કરો."},"benefit":{"en":"Keeping the yantra with you, and constantly recalling the verse, riddhi and mantra, all people, family and relatives come under one's influence. All become favourable and are won over.","es":"Con el yantra a tu lado, y recordando constantemente el verso, la riddhi y el mantra, todas las personas, la familia y los parientes quedan bajo la propia influencia. Todos se vuelven favorables y se ganan.","hi":"यंत्र पास में रखने तथा काव्य ऋद्धि और मंत्र का स्मरण करते रहने से सर्वजन, स्वजन और परिजन अपने अधीन होते हैं। सभी अनुकूल एवं वशीभूत होते हैं।","pt":"Mantendo o yantra consigo e recordando constantemente o verso, o riddhi e o mantra, todas as pessoas, a família e os parentes ficam sob a sua influência. Todos se tornam favoráveis e são conquistados.","it":"Tenendo con te lo yantra e ricordando di continuo il verso, il riddhi e il mantra, tutte le persone, la famiglia e i parenti vengono sotto la propria influenza. Tutti diventano favorevoli e si lasciano conquistare.","gu":"યંત્ર પોતાની પાસે રાખી, શ્લોક, ઋદ્ધિ અને મંત્રનું સતત સ્મરણ કરવાથી બધા લોકો, કુટુંબ અને સગાંવહાલાં પોતાના પ્રભાવ હેઠળ આવે છે. બધા અનુકૂળ બને છે અને વશ થાય છે."}},{"n":22,"sa":["स्त्रीणां शतानि शतशो जनयन्ति पुत्रान्-","नान्या सुतं त्वदुपमं जननी प्रसूता।","सर्वा दिशो दधति भानि सहस्र-रश्मिं,","प्राच्येव दिग्जनयति स्फुर-दंशु-जालम् ।।२२।।"],"pron":["strīṇāṃ śatāni śataśo janayanti putrān-","nānyā sutaṃ tvadupamaṃ jananī prasūtā|","sarvā diśo dadhati bhāni sahasra-raśmiṃ,","prācyeva digjanayati sphura-daṃśu-jālam ||22||"],"title":{"en":"The eastern horizon","hi":"पूर्व दिशा","es":"El horizonte del este","pt":"O horizonte do oriente","it":"L’orizzonte d’oriente","gu":"પૂર્વની ક્ષિતિજ"},"meaning":{"en":"Hundreds of women give birth to sons, but no other mother has borne one like you. Stars fill every direction, yet only the east gives birth to the sun.","hi":"सैकड़ों स्त्रि याँ पुत्रों को जन्म देती हैं, पर आप जैसे पुत्र को किसी और माता ने जन्म नहीं दिया। तारे हर दिशा में हैं, पर सूर्य को केवल पूर्व दिशा ही जन्म देती है।","es":"Cientos de mujeres dan a luz hijos, pero ninguna otra madre ha dado a luz uno como tú. Hay estrellas en todas las direcciones, pero solo el este da a luz al sol.","pt":"Centenas de mulheres dão à luz filhos, mas nenhuma outra mãe gerou alguém como tu. As estrelas enchem todas as direções, mas só o oriente dá à luz o sol.","it":"Centinaia di donne mettono al mondo figli, ma nessun’altra madre ne ha generato uno come te. Le stelle riempiono ogni direzione, ma solo l’oriente dà alla luce il sole.","gu":"સેંકડો સ્ત્રીઓ પુત્રોને જન્મ આપે છે, પણ તમારા જેવા પુત્રને બીજી કોઈ માતાએ જન્મ આપ્યો નથી. તારાઓ બધી દિશાઓ ભરી દે છે, પણ સૂર્યને તો માત્ર પૂર્વ દિશા જ જન્મ આપે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो आगास गामीणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo āgāsa gāmīṇaṃ"}],"mantra":[{"dev":"ॐ नमो श्री वीरेहिं जृम्भय जृम्भय मोहय मोहय स्तम्भय स्तम्भय अवधारणं कुरु कुरु स्वाहा।","iast":"Oṃ namo śrī vīrehiṃ jṛmbhaya jṛmbhaya mohaya mohaya stambhaya stambhaya avadhāraṇaṃ kuru kuru svāhā"}],"method":{"en":"Become pure, wear clean clothes, set up the yantra and worship it. Place an auspicious pot (mangal kalash) and, with a lit lamp in front of you, facing east, recall the twenty-second verse, the riddhi and the mantra 108 times every day.","es":"Purifícate, ponte ropa limpia, coloca el yantra y adóralo. Coloca un cántaro auspicioso (mangal kalash) y, con una lámpara encendida delante, mirando al este, recuerda cada día 108 veces el vigésimo segundo verso, la riddhi y el mantra.","hi":"पवित्र होकर शुद्ध वस्त्र धारण कर यंत्र स्थापित कर उसकी पूजा करें। मंगल कलश रखें, प्रज्वलित दीपक सामने रख पूर्व दिशा की ओर मुख करके प्रतिदिन एक सौ आठ बार बाईसवें काव्य, ऋद्धि तथा मंत्र का स्मरण करना चाहिए।","pt":"Purifique-se, vista roupas limpas, coloque o yantra e adore-o. Disponha um pote auspicioso (mangal kalash) e, com uma lamparina acesa à sua frente, voltado para o leste, recorde o vigésimo segundo verso, o riddhi e o mantra 108 vezes todos os dias.","it":"Purificati, indossa abiti puliti, disponi lo yantra e adoralo. Colloca un vaso benaugurale (mangal kalash) e, con una lampada accesa davanti a te, rivolto a est, ricorda il ventiduesimo verso, il riddhi e il mantra 108 volte ogni giorno.","gu":"શુદ્ધ થઈ, સ્વચ્છ વસ્ત્રો પહેરી, યંત્રની સ્થાપના કરી તેની પૂજા કરો. મંગળ કળશ મૂકો અને સામે પ્રગટાવેલો દીવો રાખી, પૂર્વ તરફ મુખ રાખીને રોજ બાવીસમો શ્લોક, ઋદ્ધિ અને મંત્ર 108 વાર યાદ કરો."},"benefit":{"en":"By tying the yantra around the neck, and by chewing a lump of turmeric root charged 21 times with the riddhi and mantra, the troubles of dakini, shakini, ghosts, pishach, churail and the like are removed.","es":"Atando el yantra al cuello, y masticando un trozo de raíz de cúrcuma cargado 21 veces con la riddhi y el mantra, se alejan las perturbaciones de dakinis, shakinis, fantasmas, pishachas, churails y seres semejantes.","hi":"यंत्र को गले में बाँधने से तथा हल्दी की गाँठ को इक्कीस बार ऋद्धि मंत्र द्वारा मंत्रित कर चबाने से डाकिनी, शाकिनी, भूत, पिशाच, चुड़ैल आदि की बाधायें दूर होती हैं।","pt":"Amarrando o yantra no pescoço e mastigando um pedaço de raiz de cúrcuma carregado 21 vezes com o riddhi e o mantra, afastam-se os tormentos de dakini, shakini, fantasmas, pishach, churail e semelhantes.","it":"Legando lo yantra al collo e masticando un pezzetto di radice di curcuma caricato 21 volte con il riddhi e il mantra, si allontanano i tormenti di dakini, shakini, fantasmi, pishach, churail e simili.","gu":"યંત્રને ગળામાં બાંધવાથી અને ઋદ્ધિ તથા મંત્ર વડે 21 વાર અભિમંત્રિત કરેલો હળદરનો ગાંઠિયો ચાવવાથી ડાકણ, શાકિની, ભૂત, પિશાચ, ચુડેલ વગેરેની પીડા દૂર થાય છે."}},{"n":23,"sa":["त्वामा-मनन्ति मुनयः परमं पुमांस-","मादित्य-वर्ण-ममलं तमसः पुरस्तात","त्वामेव सम्य-गुपलभ्य जयन्ति मृत्युं,","नान्यः शिवः शिव-पदस्य मुनीन्द्र पन्थाः।।२३।।"],"pron":["tvāmā-mananti munayaḥ paramaṃ pumāṃsa-","māditya-varṇa-mamalaṃ tamasaḥ purastāt","tvāmeva samya-gupalabhya jayanti mṛtyuṃ,","nānyaḥ śivaḥ śiva-padasya munīndra panthāḥ||23||"],"title":{"en":"The path to freedom","hi":"मुक्ति का मार्ग","es":"El camino a la libertad","pt":"O caminho para a liberdade","it":"La via della libertà","gu":"મુક્તિનો માર્ગ"},"meaning":{"en":"The wise call you the supreme being, bright as the sun, free of stain and beyond the darkness of ignorance. Knowing you, one conquers death; there is no other auspicious path to liberation.","hi":"ज्ञानी आपको परम पुरुष कहते हैं, सूर्य-सम तेजस्वी, निर्मल और अज्ञान-अंधकार से परे। आपको जानकर मनुष्य मृत्यु को जीत लेता है; मोक्ष का इसके सिवा कोई दूसरा शुभ मार्ग नहीं।","es":"Los sabios te llaman el ser supremo, brillante como el sol, sin mancha y más allá de la oscuridad de la ignorancia. Conociéndote se vence a la muerte; no hay otro camino auspicioso a la liberación.","pt":"Os sábios te chamam de ser supremo, brilhante como o sol, livre de mancha e além da escuridão da ignorância. Conhecendo-te, vence-se a morte; não há outro caminho auspicioso para a libertação.","it":"I saggi ti chiamano l’essere supremo, luminoso come il sole, privo di macchia e oltre l’oscurità dell’ignoranza. Conoscendoti, si vince la morte; non esiste altra via propizia verso la liberazione.","gu":"જ્ઞાનીઓ તમને પરમ પુરુષ કહે છે, સૂર્ય જેવા તેજસ્વી, નિષ્કલંક અને અજ્ઞાનના અંધકારથી પર. તમને જાણીને મૃત્યુને જીતી શકાય છે; મોક્ષનો બીજો કોઈ શુભ માર્ગ નથી."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो आसी विसाणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo āsī visāṇaṃ"}],"mantra":[{"dev":"ॐ ह्रीं श्रीं क्लीं सर्व सिद्धाय श्रीं नमः।","iast":"Oṃ hrīṃ śrīṃ klīṃ sarva siddhāya śrīṃ namaḥ"},{"dev":"ॐ नमो भगवती जयावती मम समीहितार्थं मोक्ष सौख्यं कुरु कुरु स्वाहा।","iast":"Oṃ namo bhagavatī jayāvatī mama samīhitārthaṃ mokṣa saukhyaṃ kuru kuru svāhā"}],"method":{"en":"On an auspicious day, become pure, wear white clothes, set up the yantra facing north, place an auspicious pot (mangal kalash), light a lamp and worship the yantra. Then, with a white rosary, practise the riddhi and the mantra 4,000 times to perfect the mantra.","es":"En un día propicio, purifícate, vístete de blanco, coloca el yantra mirando al norte, pon un cántaro auspicioso (mangal kalash), enciende una lámpara y adora el yantra. Luego, con un rosario blanco, practica la riddhi y el mantra 4.000 veces para perfeccionar el mantra.","hi":"शुभयोग में पवित्र हो सफेद वस्त्र धारण कर उत्तराभिमुख यंत्र स्थापित कर मंगल कलश रखें, दीपक जलावें तथा यंत्र की पूजा करें पश्चात् सफेद माला द्वारा चार हजार बार ऋद्धि, मंत्र का आराधन करके मंत्र सिद्ध करना चाहिए।","pt":"Em um dia auspicioso, purifique-se, vista roupas brancas, coloque o yantra voltado para o norte, disponha um pote auspicioso (mangal kalash), acenda uma lamparina e adore o yantra. Depois, com um rosário branco, pratique o riddhi e o mantra 4.000 vezes para aperfeiçoar o mantra.","it":"In un giorno propizio, purificati, indossa abiti bianchi, disponi lo yantra rivolto a nord, colloca un vaso benaugurale (mangal kalash), accendi una lampada e adora lo yantra. Poi, con un rosario bianco, pratica il riddhi e il mantra 4.000 volte per rendere perfetto il mantra.","gu":"શુભ દિવસે શુદ્ધ થઈ, સફેદ વસ્ત્રો પહેરી, ઉત્તર તરફ મુખ રાખી યંત્રની સ્થાપના કરો, મંગળ કળશ મૂકો, દીવો પ્રગટાવો અને યંત્રની પૂજા કરો. પછી સફેદ માળા વડે ઋદ્ધિ અને મંત્રનો 4,000 વાર જાપ કરી મંત્ર સિદ્ધ કરો."},"benefit":{"en":"First, to protect your own body, recall the twenty-third verse, the riddhi and the mantra 108 times. Afterwards, tie the yantra on the person who is troubled by ghosts and spirits and treat them with the mantra: the spirit affliction goes away.","es":"Primero, para proteger tu propio cuerpo, recuerda 108 veces el vigésimo tercer verso, la riddhi y el mantra. Después, ata el yantra a la persona afligida por fantasmas y espíritus y trátala con el mantra: la aflicción del espíritu desaparece.","hi":"सर्वप्रथम स्वशरीर की रक्षा के लिये एक सौ आठ बार तेईसवाँ काव्य, ऋद्धि तथा मंत्र का स्मरण कर पश्चात् जिसे भूत प्रेत की बाधा हो उसे यंत्र बाँधे तथा मंत्र द्वारा झाड़े तो प्रेत बाधा दूर होती है।","pt":"Primeiro, para proteger o próprio corpo, recorde o vigésimo terceiro verso, o riddhi e o mantra 108 vezes. Depois, amarre o yantra na pessoa atormentada por fantasmas e espíritos e trate-a com o mantra: a aflição causada por espíritos desaparece.","it":"Per prima cosa, per proteggere il tuo corpo, ricorda il ventitreesimo verso, il riddhi e il mantra 108 volte. Poi lega lo yantra alla persona tormentata da fantasmi e spiriti e trattala con il mantra: l’afflizione degli spiriti scompare.","gu":"પ્રથમ, પોતાના શરીરની રક્ષા માટે તેવીસમો શ્લોક, ઋદ્ધિ અને મંત્ર 108 વાર યાદ કરો. પછી ભૂત-પ્રેતથી પીડિત વ્યક્તિને યંત્ર બાંધો અને મંત્ર વડે ઉપચાર કરો: પ્રેતબાધા દૂર થાય છે."}},{"n":24,"sa":["त्वा-मव्ययं विभु-मचिन्त्य-मसंख्य-माद्यं,","ब्रह्माण-मीश्वर-मनन्त-मनंग केतुम्।","योगीश्वरं विदित-योग-मनेक-मेकं,","ज्ञान-स्वरूप-ममलं प्रवदन्ति सन्तः।।२४।।"],"pron":["tvā-mavyayaṃ vibhu-macintya-masaṃkhya-mādyaṃ,","brahmāṇa-mīśvara-mananta-manaṃga ketum|","yogīśvaraṃ vidita-yoga-maneka-mekaṃ,","jñāna-svarūpa-mamalaṃ pravadanti santaḥ||24||"],"title":{"en":"Names of the awakened","hi":"जागृत के नाम","es":"Los nombres del despierto","pt":"Nomes do desperto","it":"Nomi del risvegliato","gu":"જાગૃત પુરુષનાં નામો"},"meaning":{"en":"The sages call you imperishable, all-pervading, beyond measure, infinite, the first of all, ever blissful, master of yoga, the very form of stainless knowledge.","hi":"संत आपको अव्यय, विभु, अचिंत्य, असंख्य, आद्य, योगीश्वर और निर्मल ज्ञान का स्वरूप कहते हैं।","es":"Los sabios te llaman imperecedero, omnipresente, incomprensible, infinito, el primero, maestro del yoga, la forma misma del conocimiento sin mancha.","pt":"Os sábios te chamam de imperecível, onipresente, incomensurável, infinito, o primeiro de todos, sempre bem-aventurado, mestre do yoga, a própria forma do conhecimento sem mácula.","it":"I saggi ti chiamano imperituro, onnipresente, incommensurabile, infinito, il primo di tutti, sempre beato, signore dello yoga, la forma stessa della conoscenza senza macchia.","gu":"ઋષિઓ તમને અવિનાશી, સર્વવ્યાપી, અપાર, અનંત, સર્વના આદિ, સદા આનંદસ્વરૂપ, યોગીશ્વર અને નિર્મળ જ્ઞાનના સાક્ષાત્ સ્વરૂપ કહે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो दिट्टि विसाणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo diṭṭi visāṇaṃ"}],"mantra":[{"dev":"ॐ ह्रां ह्रीं ह्रूं ह्रौं ह्रः असिआउसा नमः स्वाहा।","iast":"Oṃ hrāṃ hrīṃ hrūṃ hrauṃ hraḥ asiāusā namaḥ svāhā"},{"dev":"ॐ नमो भगवते वद्धमाण सामिस्स सर्व समीहितं कुरु कुरु स्वाहा।","iast":"oṃ namo bhagavate vaddhamāṇa sāmissa sarva samīhitaṃ kuru kuru svāhā"}],"method":{"en":"Become pure, wear saffron (ochre) clothes, set up the yantra and worship it, light a lamp and perform the aarti. Then practise the riddhi and the mantra 108 times each day, or 1,000 times each day for seven days.","es":"Purifícate, vístete con ropa azafrán (ocre), coloca el yantra y adóralo, enciende una lámpara y haz el aarti. Luego practica la riddhi y el mantra 108 veces al día, o 1.000 veces al día durante siete días.","hi":"पवित्र होकर गेरुआ रंग के वस्त्र पहने यंत्र स्थापित कर पूजा करें, दीपक जलावें, आरती उतारें पश्चात् प्रतिदिन एक सौ आठ बार अथवा सात दिन तक प्रतिदिन एक हजार बार ऋद्धि मंत्र का आराधन करना चाहिए।","pt":"Purifique-se, vista roupas açafrão (ocre), coloque o yantra e adore-o, acenda uma lamparina e realize o aarti. Depois pratique o riddhi e o mantra 108 vezes por dia, ou 1.000 vezes por dia durante sete dias.","it":"Purificati, indossa abiti color zafferano (ocra), disponi lo yantra e adoralo, accendi una lampada ed esegui l’aarti. Poi pratica il riddhi e il mantra 108 volte al giorno, oppure 1.000 volte al giorno per sette giorni.","gu":"શુદ્ધ થઈ, ભગવાં (કેસરી) વસ્ત્રો પહેરી, યંત્રની સ્થાપના કરી તેની પૂજા કરો, દીવો પ્રગટાવો અને આરતી કરો. પછી રોજ 108 વાર, અથવા સાત દિવસ સુધી રોજ 1,000 વાર, ઋદ્ધિ અને મંત્રની સાધના કરો."},"benefit":{"en":"Charging ash 21 times and applying it to an aching head, and keeping the yantra with you, relieves migraine (adhashishi), sun-headache (suryavat), pressure in the head and every kind of head pain.","es":"Cargar ceniza 21 veces y aplicarla sobre una cabeza que duele, y tener el yantra contigo, alivia la migraña (adhashishi), el dolor de cabeza por el sol (suryavat), la presión en la cabeza y toda clase de dolor de cabeza.","hi":"इक्कीस बार राख मंत्रित कर दुखते हुए सिर पर लगाने से और यंत्र को पास में रखने से आधाशीशी सूर्यवात, मस्तक का वेग आदि शिर सम्बन्धी सब तरह की पीड़ायें दूर होती है।","pt":"Carregar cinzas 21 vezes e aplicá-las em uma cabeça que dói, e manter o yantra consigo, alivia a enxaqueca (adhashishi), a dor de cabeça causada pelo sol (suryavat), a pressão na cabeça e todo tipo de dor de cabeça.","it":"Caricare la cenere 21 volte e applicarla su una testa dolorante, e tenere con sé lo yantra, allevia l’emicrania (adhashishi), il mal di testa da sole (suryavat), la pressione alla testa e ogni tipo di mal di testa.","gu":"રાખને 21 વાર અભિમંત્રિત કરી દુખતા માથા પર લગાવવાથી અને યંત્ર પોતાની પાસે રાખવાથી આધાશીશી (અધાશીશી), સૂર્યાવર્ત, માથાનું દબાણ અને દરેક પ્રકારનો માથાનો દુખાવો મટે છે."}},{"n":25,"sa":["बुद्धस्त्वमेव विबुधार्चित-बुद्धि-बोधात्-","त्वं शंकरोऽसि भुवन-त्रय-शंकरत्वात्।","धातासि धीर शिव-मार्ग-विधे-र्विधानात्,","व्यक्तं त्वमेव भगवन् पुरुषोत्तमोऽसि।।२५।।"],"pron":["buddhastvameva vibudhārcita-buddhi-bodhāt-","tvaṃ śaṃkaro’si bhuvana-traya-śaṃkaratvāt|","dhātāsi dhīra śiva-mārga-vidhe-rvidhānāt,","vyaktaṃ tvameva bhagavan puruṣottamo’si||25||"],"title":{"en":"Many names, one praise","hi":"अनेक नाम, एक स्तुति","es":"Muchos nombres, una alabanza","pt":"Muitos nomes, um só louvor","it":"Molti nomi, un’unica lode","gu":"અનેક નામ, એક સ્તુતિ"},"meaning":{"en":"The wise honour you as Buddha, for your knowledge is awake; as Shankara, for you bring peace to the three worlds; as Brahma, for you lay out the path to liberation; and as the highest among beings.","hi":"ज्ञानी आपको बुद्ध मानते हैं, क्योंकि आपका ज्ञान जागृत है; शंकर, क्योंकि आप तीनों लोकों को सुख देते हैं; विधाता, क्योंकि आप मोक्ष-मार्ग का विधान करते हैं; और पुरुषोत्तम, प्राणियों में सर्वोत्तम।","es":"Los sabios te honran como Buda, porque tu conocimiento está despierto; como Shankara, porque das paz a los tres mundos; como Brahma, porque trazas el camino a la liberación; y como el más elevado entre los seres.","pt":"Os sábios te honram como Buda, porque teu conhecimento está desperto; como Shankara, porque trazes paz aos três mundos; como Brahma, porque traças o caminho da libertação; e como o mais elevado entre os seres.","it":"I saggi ti onorano come Buddha, perché la tua conoscenza è desta; come Shankara, perché porti pace ai tre mondi; come Brahma, perché tracci la via della liberazione; e come il più elevato tra gli esseri.","gu":"જ્ઞાનીઓ તમને બુદ્ધ તરીકે પૂજે છે, કારણ કે તમારું જ્ઞાન જાગૃત છે; શંકર તરીકે, કારણ કે તમે ત્રણે લોકને શાંતિ આપો છો; બ્રહ્મા તરીકે, કારણ કે તમે મુક્તિનો માર્ગ રચો છો; અને જીવોમાં સર્વોત્તમ તરીકે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो उग्ग तवाणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo ugga tavāṇaṃ"}],"mantra":[{"dev":"ॐ ह्रां ह्रीं ह्रौं ह्रः अ सि आ उ सा नमः स्वाहा।","iast":"Oṃ hrāṃ hrīṃ hrauṃ hraḥ a si ā u sā namaḥ svāhā"},{"dev":"ॐ नमो भगवते जय विजया पराजिते सर्व सौभाग्यं सर्वसौख्यं कुरु कुरु स्वाहा।","iast":"oṃ namo bhagavate jaya vijayā parājite sarva saubhāgyaṃ sarvasaukhyaṃ kuru kuru svāhā"}],"method":{"en":"Become pure, wear red clothes, set up the yantra, worship it and perform the aarti. At night, in a lonely place, fearless, recall the riddhi and the mantra 4,000 times to perfect the mantra.","es":"Purifícate, vístete de rojo, coloca el yantra, adóralo y haz el aarti. De noche, en un lugar solitario, sin miedo, recuerda 4.000 veces la riddhi y el mantra para perfeccionar el mantra.","hi":"पवित्र होकर लाल रंग के वस्त्र पहनकर यंत्र स्थापित कर उसकी पूजा करें आरती उतारें, रात्रि के समय किसी एकान्त स्थान में निर्भय होकर चार हजार बार ऋद्धि मंत्र का स्मरण कर मंत्र सिद्ध करना चाहिए।","pt":"Purifique-se, vista roupas vermelhas, coloque o yantra, adore-o e realize o aarti. À noite, em um lugar solitário, sem medo, recorde o riddhi e o mantra 4.000 vezes para aperfeiçoar o mantra.","it":"Purificati, indossa abiti rossi, disponi lo yantra, adoralo ed esegui l’aarti. Di notte, in un luogo solitario, senza paura, ricorda il riddhi e il mantra 4.000 volte per rendere perfetto il mantra.","gu":"શુદ્ધ થઈ, લાલ વસ્ત્રો પહેરી, યંત્રની સ્થાપના કરો, તેની પૂજા કરો અને આરતી કરો. રાત્રે એકાંત સ્થળે, નિર્ભય થઈને, મંત્ર સિદ્ધ કરવા માટે ઋદ્ધિ અને મંત્ર 4,000 વાર યાદ કરો."},"benefit":{"en":"Recalling the twenty-fifth verse, the riddhi and the mantra, and keeping the yantra with you, removes the evil eye. One is protected from the harm of a bad gaze, the effect of fire does not touch one, and the weapon falls from the hand of an enemy who is ready to strike, so that he cannot attack.","es":"Recordar el vigésimo quinto verso, la riddhi y el mantra, y tener el yantra contigo, aleja el mal de ojo. Uno se libra del daño de una mala mirada, el efecto del fuego no lo toca, y al enemigo que se dispone a golpear se le cae el arma de la mano y no puede atacar.","hi":"पच्चीसवाँ काव्य, ऋद्धि तथा मंत्र के स्मरण एवं यंत्र को पास में रखने से नजर उतरती है। दृष्टि दोष से बचता है, अग्नि का प्रभाव नहीं पड़ता तथा मारने के लिये उद्यत शत्रु के हाथ से शस्त्र गिर पड़ता है वह वार नहीं कर पाता।","pt":"Recordando o vigésimo quinto verso, o riddhi e o mantra, e mantendo o yantra consigo, afasta-se o mau-olhado. Fica-se protegido do dano de um olhar mau, o efeito do fogo não toca a pessoa, e a arma cai da mão do inimigo que se prepara para golpear, de modo que ele não pode atacar.","it":"Ricordando il venticinquesimo verso, il riddhi e il mantra, e tenendo con te lo yantra, si allontana il malocchio. Si è protetti dal danno di uno sguardo maligno, l’effetto del fuoco non ci tocca, e l’arma cade dalla mano del nemico pronto a colpire, così che non può attaccare.","gu":"પચીસમો શ્લોક, ઋદ્ધિ અને મંત્ર યાદ કરવાથી અને યંત્ર પોતાની પાસે રાખવાથી નજર લાગવી દૂર થાય છે. ખરાબ નજરના નુકસાનથી રક્ષણ મળે છે, અગ્નિનો પ્રભાવ સ્પર્શતો નથી, અને પ્રહાર કરવા તૈયાર શત્રુના હાથમાંથી શસ્ત્ર પડી જાય છે, જેથી તે હુમલો કરી શકતો નથી."}},{"n":26,"sa":["तुभ्यं नम-स्त्रिभुवनार्ति-हराय नाथ,","तुभ्यं नमः क्षिति-तलामल-भूषणाय।","तुभ्यं नमस्त्रिजगतः परमेश्वराय,","तुभ्यं नमो जिन भवोदधि-शोषणाय।।२६।।"],"pron":["tubhyaṃ nama-stribhuvanārti-harāya nātha,","tubhyaṃ namaḥ kṣiti-talāmala-bhūṣaṇāya|","tubhyaṃ namastrijagataḥ parameśvarāya,","tubhyaṃ namo jina bhavodadhi-śoṣaṇāya||26||"],"title":{"en":"Four salutations","hi":"चार नमन","es":"Cuatro saludos","pt":"Quatro saudações","it":"Quattro saluti","gu":"ચાર નમસ્કાર"},"meaning":{"en":"Homage to you, who end the suffering of the three worlds. Homage to you, ornament of the earth. Homage to you, lord of the three worlds. Homage to you, who dry up the ocean of worldly existence.","hi":"तीनों लोकों की पीड़ा हरने वाले आपको नमन। पृथ्वी के आभूषण आपको नमन। तीनों लोकों के स्वामी आपको नमन। संसार-सागर को सुखा देने वाले आपको नमन।","es":"Homenaje a ti, que pones fin al sufrimiento de los tres mundos. Homenaje a ti, adorno de la tierra. Homenaje a ti, señor de los tres mundos. Homenaje a ti, que secas el océano de la existencia mundana.","pt":"Homenagem a ti, que pões fim ao sofrimento dos três mundos. Homenagem a ti, ornamento da terra. Homenagem a ti, senhor dos três mundos. Homenagem a ti, que secas o oceano da existência mundana.","it":"Omaggio a te, che poni fine alla sofferenza dei tre mondi. Omaggio a te, ornamento della terra. Omaggio a te, signore dei tre mondi. Omaggio a te, che prosciughi l’oceano dell’esistenza mondana.","gu":"ત્રણે લોકનું દુઃખ હરનાર તમને નમસ્કાર. પૃથ્વીના આભૂષણ સમાન તમને નમસ્કાર. ત્રણે લોકના સ્વામી તમને નમસ્કાર. સંસારસાગરને સૂકવનાર તમને નમસ્કાર."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो दित्त तवाणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo ditta tavāṇaṃ"}],"mantra":[{"dev":"ॐ नमो ॐ ह्रीं श्रीं क्लीं हूं हूं परजन शान्ति व्यवहारे जयं कुरु कुरु स्वाहा।","iast":"Oṃ namo oṃ hrīṃ śrīṃ klīṃ hūṃ hūṃ parajana śānti vyavahāre jayaṃ kuru kuru svāhā"}],"method":{"en":"Become pure, wear red clothes, face north and set up the yantra. Perform the aarti and worship the yantra. Then, from midnight until the afternoon, chant the riddhi and the mantra 12,000 times to perfect the mantra.","es":"Purifícate, vístete de rojo, mira al norte y coloca el yantra. Haz el aarti y adora el yantra. Luego, desde la medianoche hasta la tarde, canta 12.000 veces la riddhi y el mantra para perfeccionar el mantra.","hi":"शुद्ध होकर लाल रंग के वस्त्र धारण कर उत्तर दिशा की ओर मुख करके यंत्र स्थापित करें। आरती उतारें यंत्र का पूजन करें, पश्चात् अर्धरात्रि से अपराह्न काल तक बारह हजार बार ऋद्धि मंत्र का जाप जपकर मंत्र सिद्ध करें।","pt":"Purifique-se, vista roupas vermelhas, volte-se para o norte e coloque o yantra. Realize o aarti e adore o yantra. Depois, da meia-noite até a tarde, entoe o riddhi e o mantra 12.000 vezes para aperfeiçoar o mantra.","it":"Purificati, indossa abiti rossi, rivolgiti a nord e disponi lo yantra. Esegui l’aarti e adora lo yantra. Poi, da mezzanotte fino al pomeriggio, intona il riddhi e il mantra 12.000 volte per rendere perfetto il mantra.","gu":"શુદ્ધ થઈ, લાલ વસ્ત્રો પહેરી, ઉત્તર તરફ મુખ રાખી યંત્રની સ્થાપના કરો. આરતી કરો અને યંત્રની પૂજા કરો. પછી મધ્યરાત્રિથી બપોર સુધી મંત્ર સિદ્ધ કરવા માટે ઋદ્ધિ અને મંત્રનો 12,000 વાર જાપ કરો."},"benefit":{"en":"Keeping the yantra with you and applying oil charged 108 times with the riddhi and mantra to the head, half-head pain (ardhakapali, migraine) is destroyed. Massage with the charged oil and drinking the charged water relieve the pain of a woman after childbirth. By the power of this mantra even life-threatening diseases are calmed.","es":"Teniendo el yantra contigo y aplicando en la cabeza aceite cargado 108 veces con la riddhi y el mantra, se destruye el dolor de medio cráneo (ardhakapali, migraña). El masaje con el aceite cargado y beber el agua cargada alivian el dolor de la mujer tras el parto. Por el poder de este mantra se calman incluso las enfermedades mortales.","hi":"यंत्र को पास में रखने से तथा ऋद्धि मंत्र द्वारा १०८ बार तेल मन्त्रित कर शिर पर लगाने से अर्धकपाली (आधे सिर की पीड़ा) नष्ट होती है, मंत्रित तेल की मालिश तथा मंत्रित जल को पिलाने से प्रसूता की पीड़ा दूर होती है इस मंत्र के प्रभाव से प्राणान्तक रोग भी शान्त हो जाते है।","pt":"Mantendo o yantra consigo e aplicando na cabeça óleo carregado 108 vezes com o riddhi e o mantra, destrói-se a dor de meia cabeça (ardhakapali, enxaqueca). A massagem com o óleo carregado e a água carregada para beber aliviam a dor da mulher após o parto. Pelo poder deste mantra, até doenças que ameaçam a vida se acalmam.","it":"Tenendo con te lo yantra e applicando sul capo olio caricato 108 volte con il riddhi e il mantra, si dissolve il dolore a metà testa (ardhakapali, emicrania). Il massaggio con l’olio caricato e l’acqua caricata da bere alleviano il dolore della donna dopo il parto. Per la potenza di questo mantra si placano anche malattie che mettono in pericolo la vita.","gu":"યંત્ર પોતાની પાસે રાખી, ઋદ્ધિ અને મંત્ર વડે 108 વાર અભિમંત્રિત કરેલું તેલ માથા પર લગાવવાથી અડધા માથાનો દુખાવો (અર્ધકપાળી, આધાશીશી) નાશ પામે છે. અભિમંત્રિત તેલની માલિશ અને અભિમંત્રિત પાણી પીવાથી પ્રસૂતિ પછી સ્ત્રીની પીડા શાંત થાય છે. આ મંત્રના પ્રભાવથી જીવલેણ રોગો પણ શાંત થાય છે."}},{"n":27,"sa":["को विस्मयोऽत्र यदि नाम गुणैरशेषै-","स्त्वं संश्रितो निरवकाश-तया मुनीश।","दोषै-रुपात्त-विविधाश्रय-जात-गर्वैः,","स्वप्नान्तरेऽपि न कदाचिद-पीक्षितोऽसि।।२७।।"],"pron":["ko vismayo’tra yadi nāma guṇairaśeṣai-","stvaṃ saṃśrito niravakāśa-tayā munīśa|","doṣai-rupātta-vividhāśraya-jāta-garvaiḥ,","svapnāntare’pi na kadācida-pīkṣito’si||27||"],"title":{"en":"No room for faults","hi":"दोषों के लिए स्थान नहीं","es":"Sin lugar para las faltas","pt":"Sem lugar para as falhas","it":"Nessun posto per i difetti","gu":"દોષો માટે જગ્યા નથી"},"meaning":{"en":"It is no wonder that every virtue has taken shelter in you. Faults found no space left, and puffed up with pride, they never came near you, even in dreams.","hi":"आश्चर्य नहीं कि सभी गुणों ने आपकी शरण ली है। दोषों को कोई स्थान न मिला, और अहंकार में फूले वे स्वप्न में भी आपके पास न आए।","es":"No es de extrañar que todas las virtudes se hayan refugiado en ti. Las faltas no encontraron espacio y, hinchadas de orgullo, ni en sueños se acercaron a ti.","pt":"Não é de admirar que toda virtude tenha se abrigado em ti. As falhas não encontraram espaço e, inchadas de orgulho, nunca se aproximaram de ti, nem mesmo em sonhos.","it":"Non c’è da stupirsi che ogni virtù abbia trovato rifugio in te. I difetti non trovarono più spazio e, gonfi di orgoglio, non si avvicinarono mai a te, nemmeno in sogno.","gu":"દરેક ગુણે તમારામાં આશ્રય લીધો તેમાં કોઈ આશ્ચર્ય નથી. દોષોને જગ્યા ન મળી, અને અભિમાનથી ફૂલેલા તેઓ સ્વપ્નમાં પણ તમારી પાસે આવ્યા નહીં."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो तत्त तवाणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo tatta tavāṇaṃ"}],"mantra":[{"dev":"ॐ नमो चक्रेश्वरी देवी चक्रधारिणी चक्रेण अनुकूलं साधय साधय शत्रून् उन्मूलय उन्मूलय स्वाहा।","iast":"Oṃ namo cakreśvarī devī cakradhāriṇī cakreṇa anukūlaṃ sādhaya sādhaya śatrūn unmūlaya unmūlaya svāhā"},{"dev":"ॐ नमो भगवते सर्वार्थ सिद्धाय सुखाय ह्रीं श्रीं नमः।","iast":"oṃ namo bhagavate sarvārtha siddhāya sukhāya hrīṃ śrīṃ namaḥ"}],"method":{"en":"Become pure, wear black clothes, write the yantra with red sandalwood paste and set it up, then worship it. Afterwards, for 21 days, with a black rosary, recite the 27th verse, the riddhi and the mantra 108 times each day, offering 108 flowers. Eat one meal a day without salt.","es":"Purifícate, vístete de negro, escribe el yantra con pasta de sándalo rojo y colócalo, y luego adóralo. Después, durante 21 días, con un rosario negro, recita cada día 108 veces el verso 27, la riddhi y el mantra, ofreciendo 108 flores. Come una vez al día sin sal.","hi":"पवित्र होकर काले वस्त्र पहनें रक्त चन्दन से यंत्र लिखकर स्थापित करें यंत्र की पूजा करें। पश्चात् २१ दिन तक प्रतिदिन काले रंग की माला से एक सौ आठ बार सत्ताईसवें काव्य, ऋद्धि तथा मंत्र का जाप करते हुए एक सौ आठ पुष्प चढ़ाना चाहिए बिना नमक का एक बार भोजन करना चाहिए।","pt":"Purifique-se, vista roupas pretas, escreva o yantra com pasta de sândalo vermelho, coloque-o e adore-o. Depois, durante 21 dias, com um rosário preto, recite o 27º verso, o riddhi e o mantra 108 vezes por dia, oferecendo 108 flores. Faça uma refeição por dia, sem sal.","it":"Purificati, indossa abiti neri, scrivi lo yantra con pasta di sandalo rosso, disponilo e adoralo. Poi, per 21 giorni, con un rosario nero, recita il 27º verso, il riddhi e il mantra 108 volte al giorno, offrendo 108 fiori. Fai un solo pasto al giorno, senza sale.","gu":"શુદ્ધ થઈ, કાળાં વસ્ત્રો પહેરી, રક્તચંદનની પેસ્ટથી યંત્ર લખો, તેની સ્થાપના કરો અને પૂજા કરો. પછી 21 દિવસ સુધી કાળી માળા વડે રોજ 27મો શ્લોક, ઋદ્ધિ અને મંત્ર 108 વાર બોલો અને 108 ફૂલ અર્પણ કરો. દિવસમાં એક વાર મીઠા વગરનું ભોજન કરો."},"benefit":{"en":"Keeping the yantra with you and repeatedly recalling the riddhi and mantra, an enemy cannot cause any obstruction to the mantra practice; he is defeated.","es":"Tener el yantra contigo y recordar repetidamente la riddhi y el mantra impide que el enemigo ponga obstáculo alguno a la práctica del mantra; queda derrotado.","hi":"यंत्र को पास में रखने तथा ऋद्धि मंत्र का बार बार स्मरण करते रहने से शत्रु मंत्र आराधना में कोई बाधा नहीं पहुँचा सकता वह पराजित हो जाता है।","pt":"Mantendo o yantra consigo e recordando repetidamente o riddhi e o mantra, o inimigo não consegue causar nenhum obstáculo à prática do mantra; ele é derrotado.","it":"Tenendo con te lo yantra e ricordando di continuo il riddhi e il mantra, il nemico non può creare alcun ostacolo alla pratica del mantra; viene sconfitto.","gu":"યંત્ર પોતાની પાસે રાખી ઋદ્ધિ અને મંત્રનું વારંવાર સ્મરણ કરવાથી શત્રુ મંત્રસાધનામાં કોઈ વિઘ્ન નાખી શકતો નથી; તે પરાજિત થાય છે."}},{"n":28,"sa":["उच्चैर-शोक-तरु-संश्रित-मुन्मयूख-","माभाति रूप-ममलं भवतो नितान्तम्।","स्पष्टोल्लसत्-किरणमस्त-तमो-वितानं,","बिम्बं रवेरिव पयोधर-पार्श्ववर्ति।।२८।।"],"pron":["uccaira-śoka-taru-saṃśrita-munmayūkha-","mābhāti rūpa-mamalaṃ bhavato nitāntam|","spaṣṭollasat-kiraṇamasta-tamo-vitānaṃ,","bimbaṃ raveriva payodhara-pārśvavarti||28||"],"title":{"en":"Beneath the ashoka","hi":"अशोक वृक्ष के नीचे","es":"Bajo el ashoka","pt":"Sob o ashoka","it":"Sotto l’ashoka","gu":"અશોકવૃક્ષ નીચે"},"meaning":{"en":"Beneath the tall ashoka tree your flawless form shines, like the sun’s disk breaking through the dark clouds around it.","hi":"ऊँचे अशोक वृक्ष के नीचे आपका निर्मल स्वरूप ऐसे दमकता है जैसे अंधकारमय बादलों को चीरकर निकला सूर्य-मंडल।","es":"Bajo el alto árbol ashoka tu forma impecable resplandece, como el disco del sol que atraviesa las nubes oscuras que lo rodean.","pt":"Sob a alta árvore ashoka brilha tua forma impecável, como o disco do sol rompendo as nuvens escuras ao seu redor.","it":"Sotto l’alto albero di ashoka risplende la tua forma senza difetto, come il disco del sole che squarcia le nubi scure intorno a sé.","gu":"ઊંચા અશોકવૃક્ષ નીચે તમારું નિષ્કલંક સ્વરૂપ ચમકે છે, જેમ આસપાસનાં કાળાં વાદળોને ચીરીને સૂર્યનું મંડળ પ્રકાશે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो महातवाणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo mahātavāṇaṃ"}],"mantra":[{"dev":"ॐ नमो भगवते जये विजये जृम्भय जृम्भय मोहय मोहय, सर्वसिद्धि सम्पत्ति सौख्यं कुरु कुरु स्वाहा।","iast":"Oṃ namo bhagavate jaye vijaye jṛmbhaya jṛmbhaya mohaya mohaya, sarvasiddhi sampatti saukhyaṃ kuru kuru svāhā"}],"method":{"en":"Become pure, wear yellow clothes, face north or east and set up the yantra and worship it. Then sit on a yellow seat and, with a yellow rosary, practise the riddhi and the mantra 1,000 times each day until 12,000 repetitions are complete. Offer yellow flowers.","es":"Purifícate, vístete de amarillo, mira al norte o al este, coloca el yantra y adóralo. Luego siéntate en un asiento amarillo y, con un rosario amarillo, practica la riddhi y el mantra 1.000 veces al día hasta completar 12.000 repeticiones. Ofrece flores amarillas.","hi":"पवित्र होकर पीले वस्त्र धारण करें उत्तर या पूर्व दिशा की ओर मुख करके यंत्र स्थापित कर उसकी पूजा करें पश्चात् पीले आसन पर बैठकर पीली माला द्वारा प्रतिदिन एक हजार बार ऋद्धि मंत्र का आराधन कर बारह हजार जप पूरा करें। पीले फूल चढ़ावें।","pt":"Purifique-se, vista roupas amarelas, volte-se para o norte ou para o leste, coloque o yantra e adore-o. Depois sente-se em um assento amarelo e, com um rosário amarelo, pratique o riddhi e o mantra 1.000 vezes por dia até completar 12.000 repetições. Ofereça flores amarelas.","it":"Purificati, indossa abiti gialli, rivolgiti a nord o a est, disponi lo yantra e adoralo. Poi siediti su un sedile giallo e, con un rosario giallo, pratica il riddhi e il mantra 1.000 volte al giorno fino a completare 12.000 ripetizioni. Offri fiori gialli.","gu":"શુદ્ધ થઈ, પીળાં વસ્ત્રો પહેરી, ઉત્તર અથવા પૂર્વ તરફ મુખ રાખી યંત્રની સ્થાપના કરી તેની પૂજા કરો. પછી પીળા આસન પર બેસી, પીળી માળા વડે 12,000 જાપ પૂરા થાય ત્યાં સુધી રોજ 1,000 વાર ઋદ્ધિ અને મંત્રની સાધના કરો. પીળાં ફૂલ અર્પણ કરો."},"benefit":{"en":"Keeping the yantra with you and practising the 28th verse, the riddhi and the mantra every day increases profit in business, happiness and prosperity, success and victory, honour, and standing in the royal court.","es":"Tener el yantra contigo y practicar cada día el verso 28, la riddhi y el mantra aumenta la ganancia en los negocios, la felicidad y la prosperidad, el éxito y la victoria, el honor y el prestigio en la corte real.","hi":"यंत्र पास में रखने तथा प्रतिदिन अट्ठाइसवें काव्य, ऋद्धि तथा मंत्र का आराधन करने से व्यापार में लाभ, सुख समृद्धि, यश विजय, सम्मान तथा राजदरबार में प्रतिष्ठा बढ़ती है।","pt":"Mantendo o yantra consigo e praticando todos os dias o 28º verso, o riddhi e o mantra, aumentam o lucro nos negócios, a felicidade e a prosperidade, o sucesso e a vitória, a honra e o prestígio na corte real.","it":"Tenendo con te lo yantra e praticando ogni giorno il 28º verso, il riddhi e il mantra, aumentano il guadagno negli affari, la felicità e la prosperità, il successo e la vittoria, l’onore e il prestigio alla corte reale.","gu":"યંત્ર પોતાની પાસે રાખી, રોજ 28મો શ્લોક, ઋદ્ધિ અને મંત્રની સાધના કરવાથી વેપારમાં નફો, સુખ-સમૃદ્ધિ, સફળતા અને વિજય, માન-સન્માન અને રાજદરબારમાં પ્રતિષ્ઠા વધે છે."}},{"n":29,"sa":["सिंहासने मणि-मयूख-शिखा-विचित्रे,","विभ्राजते तव वपुः कनका-वदातम् ।","बिम्बं वियद्-विलस-दंशु-लता-वितानं,","तुंगोदयाद्रि-शिरसीव सहस्र-रश्मेः।।२९।।"],"pron":["siṃhāsane maṇi-mayūkha-śikhā-vicitre,","vibhrājate tava vapuḥ kanakā-vadātam |","bimbaṃ viyad-vilasa-daṃśu-latā-vitānaṃ,","tuṃgodayādri-śirasīva sahasra-raśmeḥ||29||"],"title":{"en":"The jeweled throne","hi":"रत्नजटित सिंहासन","es":"El trono de joyas","pt":"O trono de joias","it":"Il trono di gemme","gu":"રત્નજડિત સિંહાસન"},"meaning":{"en":"Seated on a jeweled throne, your golden body gleams like the rising sun spreading its rays over Mount Udaya.","hi":"रत्नजटित सिंहासन पर विराजमान आपका स्वर्णिम शरीर उदयाचल पर किरणें बिखेरते उदित सूर्य-सा दमकता है।","es":"Sentado en un trono de joyas, tu cuerpo dorado resplandece como el sol naciente que extiende sus rayos sobre el monte Udaya.","pt":"Sentado em um trono de joias, teu corpo dourado reluz como o sol nascente espalhando seus raios sobre o monte Udaya.","it":"Seduto su un trono di gemme, il tuo corpo dorato risplende come il sole nascente che diffonde i suoi raggi sul monte Udaya.","gu":"રત્નજડિત સિંહાસન પર બિરાજેલું તમારું સુવર્ણ શરીર ઉદયાચળ પર્વત પર કિરણો ફેલાવતા ઊગતા સૂર્ય જેમ ઝળહળે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो घोर तवाणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo ghora tavāṇaṃ"}],"mantra":[{"dev":"ॐ णमो णमिऊण पासं विसहर फुलिंग मंतो विसहर नाम रकार मंतो सर्वसिद्धि मीहे इह समरंताणं मण्णे जागई कप्पदुमच्चं सर्वसिद्धि ॐ नमः स्वाहा।","iast":"Oṃ ṇamo ṇamiūṇa pāsaṃ visahara phuliṃga maṃto visahara nāma rakāra maṃto sarvasiddhi mīhe iha samaraṃtāṇaṃ maṇṇe jāgaī kappadumaccaṃ sarvasiddhi oṃ namaḥ svāhā"}],"method":{"en":"After bathing, wear sky-blue clothes, face north and set up the yantra. Perform the aarti and the worship. Until the mantra is perfected, practise the riddhi and the mantra 1,000 times every day.","es":"Después de bañarte, vístete de azul cielo, mira al norte y coloca el yantra. Haz el aarti y la adoración. Hasta perfeccionar el mantra, practica la riddhi y el mantra 1.000 veces cada día.","hi":"स्नान करके आसमानी रंग के वस्त्र धारण कर उत्तर दिशा की ओर मुख करके यंत्र स्थापित करें, आरती उतारें, पूजा करें मंत्र सिद्धि पर्यन्त प्रतिदिन एक हजार बार ऋद्धि मंत्र की आराधना करना चाहिए।","pt":"Depois do banho, vista roupas azul-celeste, volte-se para o norte e coloque o yantra. Realize o aarti e a adoração. Até que o mantra seja aperfeiçoado, pratique o riddhi e o mantra 1.000 vezes por dia.","it":"Dopo il bagno, indossa abiti azzurro cielo, rivolgiti a nord e disponi lo yantra. Esegui l’aarti e l’adorazione. Finché il mantra non è reso perfetto, pratica il riddhi e il mantra 1.000 volte ogni giorno.","gu":"સ્નાન કરી આસમાની વસ્ત્રો પહેરો, ઉત્તર તરફ મુખ રાખી યંત્રની સ્થાપના કરો. આરતી અને પૂજા કરો. મંત્ર સિદ્ધ ન થાય ત્યાં સુધી રોજ 1,000 વાર ઋદ્ધિ અને મંત્રની સાધના કરો."},"benefit":{"en":"Keeping the yantra with you and charging water 108 times with the 29th verse, the riddhi and the mantra, and giving it to drink, removes the effect of intoxicants such as bhang, charas and datura, relieves the pain of a sore eye, and the venom of a scorpion also goes away.","es":"Teniendo el yantra contigo y cargando agua 108 veces con el verso 29, la riddhi y el mantra, y dándola a beber, desaparece el efecto de las sustancias embriagantes como el bhang, el charas y el datura, se alivia el dolor de un ojo irritado, y también se va el veneno del escorpión.","hi":"यंत्र पास में रखने तथा उन्तीसवाँ काव्य, ऋद्धि और मंत्र द्वारा एक सौ आठ बार मंत्रित कर जल पिलाने से नशीले पदार्थ जैसे भाँग, चरस, धतूरा आदि नशे का प्रभाव दूर होता है तथा दुःखती आँख की पीड़ा दूर होती है विच्छू का विष भी उतर जाता है।","pt":"Mantendo o yantra consigo, carregando água 108 vezes com o 29º verso, o riddhi e o mantra e dando-a para beber, remove-se o efeito de intoxicantes como bhang, charas e datura, alivia-se a dor de um olho inflamado, e o veneno de escorpião também desaparece.","it":"Tenendo con te lo yantra, caricando l’acqua 108 volte con il 29º verso, il riddhi e il mantra e dandola da bere, si rimuove l’effetto di intossicanti come bhang, charas e datura, si allevia il dolore di un occhio infiammato, e scompare anche il veleno dello scorpione.","gu":"યંત્ર પોતાની પાસે રાખી, 29મા શ્લોક, ઋદ્ધિ અને મંત્ર વડે પાણીને 108 વાર અભિમંત્રિત કરીને પીવડાવવાથી ભાંગ, ચરસ, ધતૂરા જેવા નશાની અસર ઊતરે છે, દુખતી આંખની પીડા શાંત થાય છે, અને વીંછીનું ઝેર પણ ઊતરે છે."}},{"n":30,"sa":["कुन्दावदात-चल-चामर-चारु-शोभं,","विभ्राजते तव वपुः कलधौत-कान्तम्।","उद्यच्छशांक-शुचि-निर्झर-वारि-धार-","मुच्चैस्तटं सुर-गिरेरिव शात-कौम्भम् ।।३०।।"],"pron":["kundāvadāta-cala-cāmara-cāru-śobhaṃ,","vibhrājate tava vapuḥ kaladhauta-kāntam|","udyacchaśāṃka-śuci-nirjhara-vāri-dhāra-","muccaistaṭaṃ sura-gireriva śāta-kaumbham ||30||"],"title":{"en":"The white ceremonial fans","hi":"श्वेत चँवर","es":"Los abanicos blancos","pt":"Os leques cerimoniais brancos","it":"I ventagli cerimoniali bianchi","gu":"સફેદ ચામર"},"meaning":{"en":"Flanked by white chauris, pale as jasmine blossoms, your golden body gleams like the summit of golden Mount Meru with moon-white waterfalls streaming down.","hi":"चमेली-सी श्वेत चँवरों से घिरा आपका स्वर्णिम शरीर ऐसे दमकता है जैसे सुमेरु का स्वर्ण-शिखर, जिस पर चंद्र-सी उज्ज्वल जलधाराएँ गिर रही हों।","es":"Flanqueado por abanicos blancos como flores de jazmín, tu cuerpo dorado resplandece como la cumbre dorada del monte Meru, con cascadas blancas como la luna.","pt":"Ladeado por chauris brancos, pálidos como flores de jasmim, teu corpo dourado reluz como o cume do dourado monte Meru com cascatas brancas como a lua descendo por ele.","it":"Affiancato da chauri bianchi, pallidi come fiori di gelsomino, il tuo corpo dorato risplende come la vetta del dorato monte Meru da cui scendono cascate bianche come la luna.","gu":"ચમેલીનાં ફૂલ જેવા ફિક્કા સફેદ ચામરો વચ્ચે, તમારું સુવર્ણ શરીર ચંદ્ર જેવા શ્વેત ધોધ વહેતા સુવર્ણ મેરુ પર્વતના શિખર જેમ ઝળહળે છે."},"riddhi":[{"dev":"ॐ श्रीं अर्हं णमो घोर गुणाणं।","iast":"Oṃ śrīṃ arhaṃ ṇamo ghora guṇāṇaṃ"}],"mantra":[{"dev":"ॐ णमो अट्टे मट्टे क्षुद्रान् स्तम्भय स्तम्भय रक्षां कुरु कुरु स्वाहा।","iast":"Oṃ ṇamo aṭṭe maṭṭe kṣudrān stambhaya stambhaya rakṣāṃ kuru kuru svāhā"}],"method":{"en":"After bathing, wear white clothes, face east and set up the yantra and worship it. Offer white flowers and perform the aarti. Then sit on a white seat in the lotus posture (padmasana) and, with a crystal rosary, practise the riddhi and the mantra 1,000 times each day until it is perfected.","es":"Después de bañarte, vístete de blanco, mira al este, coloca el yantra y adóralo. Ofrece flores blancas y haz el aarti. Luego siéntate en un asiento blanco en la postura del loto (padmasana) y, con un rosario de cristal, practica la riddhi y el mantra 1.000 veces al día hasta perfeccionarlo.","hi":"स्नान के बाद सफेद वस्त्र धारण कर पूर्व दिशा की ओर मुख करके यंत्र स्थापित करें, यंत्र की पूजा करें, सफेद फूल चढ़ावें, आरती उतारें, पश्चात् सफेद आसन पर पद्मासन में बैठकर स्फटिक मणि की माला द्वारा प्रतिदिन एक हजार बार ऋद्धि मंत्र का आराधन कर उसे सिद्ध करना चाहिए।","pt":"Depois do banho, vista roupas brancas, volte-se para o leste, coloque o yantra e adore-o. Ofereça flores brancas e realize o aarti. Depois sente-se em um assento branco na postura de lótus (padmasana) e, com um rosário de cristal, pratique o riddhi e o mantra 1.000 vezes por dia até que seja aperfeiçoado.","it":"Dopo il bagno, indossa abiti bianchi, rivolgiti a est, disponi lo yantra e adoralo. Offri fiori bianchi ed esegui l’aarti. Poi siediti su un sedile bianco nella posizione del loto (padmasana) e, con un rosario di cristallo, pratica il riddhi e il mantra 1.000 volte al giorno fino a renderlo perfetto.","gu":"સ્નાન કરી સફેદ વસ્ત્રો પહેરો, પૂર્વ તરફ મુખ રાખી યંત્રની સ્થાપના કરી તેની પૂજા કરો. સફેદ ફૂલ અર્પણ કરો અને આરતી કરો. પછી સફેદ આસન પર પદ્માસનમાં બેસી, સ્ફટિકની માળા વડે મંત્ર સિદ્ધ ન થાય ત્યાં સુધી રોજ 1,000 વાર ઋદ્ધિ અને મંત્રની સાધના કરો."},"benefit":{"en":"By repeatedly recalling the above riddhi and mantra and keeping the yantra with you, the enemy is halted. In a lonely forest there is no fear of thieves or of lions and other fierce animals; all kinds of fear run away.","es":"Recordando repetidamente la riddhi y el mantra anteriores y teniendo el yantra contigo, el enemigo queda detenido. En un bosque solitario no hay temor a ladrones ni a leones y otros animales feroces; toda clase de miedos huyen.","hi":"उपरोक्त ऋद्धि मंत्र के बार बार स्मरण करने तथा यंत्र को पास में रखने से शत्रु का स्तम्भन होता है बियावान वन में चोर सिंहादिक हिंसक पशुओं का भय नहीं रहता सब प्रकार के भय दूर भाग जाते हैं।","pt":"Recordando repetidamente o riddhi e o mantra acima e mantendo o yantra consigo, o inimigo é detido. Em uma floresta solitária não há medo de ladrões, de leões nem de outros animais ferozes; todo tipo de medo foge.","it":"Ricordando di continuo il riddhi e il mantra sopra indicati e tenendo con te lo yantra, il nemico viene fermato. In una foresta solitaria non c’è timore di ladri, di leoni né di altri animali feroci; ogni genere di paura fugge.","gu":"ઉપરોક્ત ઋદ્ધિ અને મંત્રનું વારંવાર સ્મરણ કરવાથી અને યંત્ર પોતાની પાસે રાખવાથી શત્રુ અટકી જાય છે. એકાંત જંગલમાં ચોર, સિંહ કે અન્ય હિંસક પ્રાણીઓનો ભય રહેતો નથી; દરેક પ્રકારનો ભય ભાગી જાય છે."}},{"n":31,"sa":["छत्र-त्रयं तव विभाति शशांक-कान्त-","मुच्चैः स्थितं स्थगित-भानु-कर-प्रतापम्।","मुक्ता-फल-प्रकर-जाल-विवृद्ध-शोभं,","प्रख्यापयत्-त्रिजगतः परमेश्वरत्वम्।।३१।।"],"pron":["chatra-trayaṃ tava vibhāti śaśāṃka-kānta-","muccaiḥ sthitaṃ sthagita-bhānu-kara-pratāpam|","muktā-phala-prakara-jāla-vivṛddha-śobhaṃ,","prakhyāpayat-trijagataḥ parameśvaratvam||31||"],"title":{"en":"The three parasols","hi":"तीन छत्र","es":"Los tres parasoles","pt":"Os três guarda-sóis","it":"I tre parasoli","gu":"ત્રણ છત્ર"},"meaning":{"en":"The three-tiered canopy above you, cool as the moon and fringed with pearls, hides the sun’s rays and proclaims your supremacy over the three worlds.","hi":"आपके ऊपर चंद्र-सम शीतल, मोतियों की झालर वाले तीन छत्र सूर्य की किरणों को रोकते हैं और तीनों लोकों पर आपकी परम प्रभुता की घोषणा करते हैं।","es":"El dosel de tres niveles sobre ti, fresco como la luna y orlado de perlas, detiene los rayos del sol y proclama tu supremacía sobre los tres mundos.","pt":"O dossel de três níveis acima de ti, fresco como a lua e franjado de pérolas, esconde os raios do sol e proclama a tua supremacia sobre os três mundos.","it":"Il baldacchino a tre livelli sopra di te, fresco come la luna e frangiato di perle, nasconde i raggi del sole e proclama la tua supremazia sui tre mondi.","gu":"તમારા ઉપર ચંદ્ર જેવું શીતળ અને મોતીઓની ઝાલરવાળું ત્રણ સ્તરનું છત્ર સૂર્યનાં કિરણોને ઢાંકી દે છે અને ત્રણે લોક પર તમારી સર્વોપરિતા જાહેર કરે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो घोर गुण परक्कमाणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo ghora guṇa parakkamāṇaṃ"}],"mantra":[{"dev":"ॐ उवसग्गहरं पासं पासं वंदामि कम्म-घण-मुक्कं विसहर विसं णिण्णासं मङ्गल कल्लाण-आवासं ॐ ह्रीं नमः स्वाहा।","iast":"Oṃ uvasaggaharaṃ pāsaṃ pāsaṃ vaṃdāmi kamma-ghaṇa-mukkaṃ visahara visaṃ ṇiṇṇāsaṃ maṅgala kallāṇa-āvāsaṃ oṃ hrīṃ namaḥ svāhā"}],"method":{"en":"Become pure, wear red clothes, set up the yantra and worship it. Place a pot full of water. Then, facing north, sit on a red seat in the lotus posture and, chanting the riddhi and mantra every day, complete 7,500 repetitions.","es":"Purifícate, vístete de rojo, coloca el yantra y adóralo. Pon una vasija llena de agua. Luego, mirando al norte, siéntate en un asiento rojo en la postura del loto y, cantando cada día la riddhi y el mantra, completa 7.500 repeticiones.","hi":"पवित्र होकर रक्त वर्ण के वस्त्र धारण कर यंत्र स्थापित करें, यंत्र की पूजा करें, जल से परिपूर्ण कलश रखें, पश्चात् उत्तर दिशा की ओर मुख करें लाल आसन पर पद्मासन लगाकर प्रतिदिन ऋद्धि मंत्र का जाप जपते हुए ७५०० जाप पूरा करें।","pt":"Purifique-se, vista roupas vermelhas, coloque o yantra e adore-o. Disponha um pote cheio de água. Depois, voltado para o norte, sente-se em um assento vermelho na postura de lótus e, entoando o riddhi e o mantra todos os dias, complete 7.500 repetições.","it":"Purificati, indossa abiti rossi, disponi lo yantra e adoralo. Colloca un vaso pieno d’acqua. Poi, rivolto a nord, siediti su un sedile rosso nella posizione del loto e, intonando ogni giorno il riddhi e il mantra, completa 7.500 ripetizioni.","gu":"શુદ્ધ થઈ, લાલ વસ્ત્રો પહેરી, યંત્રની સ્થાપના કરી તેની પૂજા કરો. પાણી ભરેલો કળશ મૂકો. પછી ઉત્તર તરફ મુખ રાખી, લાલ આસન પર પદ્માસનમાં બેસી, રોજ ઋદ્ધિ અને મંત્રનો જાપ કરીને 7,500 જાપ પૂરા કરો."},"benefit":{"en":"By reciting the 31st verse, the riddhi and the mantra 108 times every day and keeping the yantra with you, one is honoured in the royal court, the king is won over, and relief comes from all kinds of skin diseases.","es":"Recitando cada día 108 veces el verso 31, la riddhi y el mantra, y teniendo el yantra contigo, se recibe honor en la corte real, el rey queda ganado y se obtiene alivio de toda clase de enfermedades de la piel.","hi":"प्रतिदिन एक सौ आठ बार ३१वाँ काव्य, ऋद्धि तथा मंत्र स्मरण करने और यंत्र को पास में रखने से राजदरबार में सम्मान मिलता है राजा वश में होता है तथा सब तरह के चर्म रोगों से छुटकारा हो जाता है।","pt":"Recitando o 31º verso, o riddhi e o mantra 108 vezes por dia e mantendo o yantra consigo, a pessoa é honrada na corte real, o rei é conquistado e vem o alívio de todo tipo de doença de pele.","it":"Recitando il 31º verso, il riddhi e il mantra 108 volte al giorno e tenendo con te lo yantra, si è onorati alla corte reale, il re viene conquistato e arriva sollievo da ogni tipo di malattia della pelle.","gu":"રોજ 31મો શ્લોક, ઋદ્ધિ અને મંત્ર 108 વાર બોલવાથી અને યંત્ર પોતાની પાસે રાખવાથી રાજદરબારમાં સન્માન મળે છે, રાજા વશ થાય છે અને દરેક પ્રકારના ચામડીના રોગોમાં રાહત મળે છે."}},{"n":32,"sa":["गम्भीर-तार-रव-पूरित-दिग्विभाग-","स्त्रैलोक्य-लोक-शुभ-संगम-भूति-दक्षः।","सद्धर्म-राज-जय-घोषण-घोषकः सन्,","खे दुन्दुभिर्-ध्वनति ते यशसः प्रवादी।।३२।।"],"pron":["gambhīra-tāra-rava-pūrita-digvibhāga-","strailokya-loka-śubha-saṃgama-bhūti-dakṣaḥ|","saddharma-rāja-jaya-ghoṣaṇa-ghoṣakaḥ san,","khe dundubhir-dhvanati te yaśasaḥ pravādī||32||"],"title":{"en":"The celestial drum","hi":"देव-दुंदुभि","es":"El tambor celestial","pt":"O tambor celestial","it":"Il tamburo celeste","gu":"દેવદુંદુભિ"},"meaning":{"en":"The deep, resounding drum of the gods fills every direction, proclaiming your fame and inviting the beings of the three worlds to join the path of true dharma.","hi":"देवों की गहरी, गूँजती दुंदुभि सब दिशाओं को भर देती है, आपकी कीर्ति की घोषणा करती है और तीनों लोकों के प्राणियों को सद्धर्म के मार्ग से जुड़ने का आह्वान देती है।","es":"El profundo y resonante tambor de los dioses llena todas las direcciones, proclama tu fama e invita a los seres de los tres mundos a unirse al camino del verdadero dharma.","pt":"O tambor profundo e ressoante dos deuses enche todas as direções, proclamando a tua fama e convidando os seres dos três mundos a seguir o caminho do dharma verdadeiro.","it":"Il profondo tamburo risonante degli dèi riempie ogni direzione, proclamando la tua fama e invitando gli esseri dei tre mondi a unirsi alla via del vero dharma.","gu":"દેવોની ગહન, ગુંજતી દુંદુભિ બધી દિશાઓ ભરી દે છે, તમારી કીર્તિ જાહેર કરે છે અને ત્રણે લોકના જીવોને સાચા ધર્મના માર્ગે જોડાવા આમંત્રે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो घोर गुणबंभचारीणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo ghora guṇabaṃbhacārīṇaṃ"}],"mantra":[{"dev":"ॐ नमो ह्रां ह्रीं ह्रूं ह्रौं ह्रः सर्व दोष निवारणं कुरु कुरु स्वाहा। सर्व सिद्धिं वृद्धिं वांछां पूर्ण कुरु कुरु स्वाहा।","iast":"Oṃ namo hrāṃ hrīṃ hrūṃ hrauṃ hraḥ sarva doṣa nivāraṇaṃ kuru kuru svāhā sarva siddhiṃ vṛddhiṃ vāṃchāṃ pūrṇa kuru kuru svāhā"}],"method":{"en":"Become pure, wear yellow clothes and set up the yantra. Place an auspicious pot (mangal kalash) at its side and worship the yantra. Then, facing east in the lotus posture, with a yellow rosary chant the riddhi and the mantra 1,008 times to perfect the mantra.","es":"Purifícate, vístete de amarillo y coloca el yantra. Pon un cántaro auspicioso (mangal kalash) a su lado y adora el yantra. Luego, mirando al este en la postura del loto, con un rosario amarillo canta 1.008 veces la riddhi y el mantra para perfeccionar el mantra.","hi":"पवित्र होकर पीत वर्ण के वस्त्र धारण कर यंत्र स्थापित करें। पार्श्व भाग में मंगल कलश रखें, यंत्र की पूजा करें, पश्चात् पूर्व दिशा की ओर मुख करके पद्मासन लगाकर, एक हजार आठ वार पीली माला से ऋद्धि मंत्र जपकर मंत्र सिद्ध करना चाहिए।","pt":"Purifique-se, vista roupas amarelas e coloque o yantra. Disponha ao seu lado um pote auspicioso (mangal kalash) e adore o yantra. Depois, voltado para o leste na postura de lótus, com um rosário amarelo, entoe o riddhi e o mantra 1.008 vezes para aperfeiçoar o mantra.","it":"Purificati, indossa abiti gialli e disponi lo yantra. Colloca al suo fianco un vaso benaugurale (mangal kalash) e adora lo yantra. Poi, rivolto a est nella posizione del loto, con un rosario giallo intona il riddhi e il mantra 1.008 volte per rendere perfetto il mantra.","gu":"શુદ્ધ થઈ, પીળાં વસ્ત્રો પહેરી, યંત્રની સ્થાપના કરો. તેની બાજુમાં મંગળ કળશ મૂકી યંત્રની પૂજા કરો. પછી પૂર્વ તરફ મુખ રાખી પદ્માસનમાં બેસી, પીળી માળા વડે મંત્ર સિદ્ધ કરવા માટે ઋદ્ધિ અને મંત્રનો 1,008 વાર જાપ કરો."},"benefit":{"en":"Raw thread spun by an unmarried girl is charged 21 or 108 times with the 32nd verse, the riddhi and the mantra. Tying that thread around the neck and keeping the yantra with you relieves sangrahani and all kinds of abdominal pain.","es":"Se carga 21 o 108 veces con el verso 32, la riddhi y el mantra un hilo crudo hilado por una joven soltera. Atar ese hilo al cuello y tener el yantra contigo alivia la sangrahani y toda clase de dolores abdominales.","hi":"अविवाहित कन्या द्वारा काते हुए कच्चे धागे को बत्तीसवाँ काव्य, ऋद्धि तथा मंत्र द्वारा इक्कीस वार या १०८ वार मंत्रित कर उस धागे को गले में बाँधने से और यंत्र को पास में रखने से संग्रहणी आदि उदर की सब तरह की पीड़ायें दूर होती हैं।","pt":"Um fio cru, fiado por uma jovem solteira, é carregado 21 ou 108 vezes com o 32º verso, o riddhi e o mantra. Amarrar esse fio no pescoço e manter o yantra consigo alivia a sangrahani e todo tipo de dor abdominal.","it":"Un filo grezzo, filato da una ragazza nubile, viene caricato 21 o 108 volte con il 32º verso, il riddhi e il mantra. Legare quel filo al collo e tenere con sé lo yantra allevia la sangrahani e ogni tipo di dolore addominale.","gu":"કુંવારી કન્યાએ કાંતેલા કાચા દોરાને 32મા શ્લોક, ઋદ્ધિ અને મંત્ર વડે 21 અથવા 108 વાર અભિમંત્રિત કરો. તે દોરો ગળામાં બાંધવાથી અને યંત્ર પોતાની પાસે રાખવાથી સંગ્રહણી અને દરેક પ્રકારનો પેટનો દુખાવો મટે છે."}},{"n":33,"sa":["मन्दार-सुन्दर-नमेरु-सुपारिजात ,","सन्तानकादि-कुसुमोत्कर-वृष्टिरुद्धा।","गन्धोद-बिन्दु-शुभ-मन्द मरुत्प्रपाता,","दिव्या दिवः पतति ते वचसां ततिर्वा ।।३३।।"],"pron":["mandāra-sundara-nameru-supārijāta ,","santānakādi-kusumotkara-vṛṣṭiruddhā|","gandhoda-bindu-śubha-manda marutprapātā,","divyā divaḥ patati te vacasāṃ tatirvā ||33||"],"title":{"en":"A shower of flowers","hi":"पुष्पवृष्टि","es":"Lluvia de flores","pt":"Uma chuva de flores","it":"Una pioggia di fiori","gu":"પુષ્પોનો વરસાદ"},"meaning":{"en":"When the gods shower the flowers of Mandara, Sundara, Namera and Parijata, mixed with fragrant dewdrops on a gentle breeze, it seems as if your auspicious words are raining down.","hi":"जब देव मंदार, सुंदर, नमेरु और पारिजात के पुष्पों की वर्षा सुगंधित जल-बिंदुओं के साथ मंद पवन में करते हैं, तो ऐसा लगता है मानो आपके मंगलमय वचन बरस रहे हों।","es":"Cuando los dioses derraman flores de Mandara, Sundara, Namera y Parijata, mezcladas con gotas de rocío perfumado en una brisa suave, parece que llovieran tus palabras auspiciosas.","pt":"Quando os deuses fazem chover as flores de Mandara, Sundara, Namera e Parijata, misturadas a gotas de orvalho perfumadas numa brisa suave, parece que as tuas palavras auspiciosas caem como chuva.","it":"Quando gli dèi fanno piovere i fiori di Mandara, Sundara, Namera e Parijata, mescolati a profumate gocce di rugiada su una brezza lieve, sembra che le tue parole propizie cadano come pioggia.","gu":"જ્યારે દેવો મંદાર, સુંદર, નમેરુ અને પારિજાતનાં ફૂલો સુગંધી ઝાકળનાં ટીપાં સાથે મંદ પવનમાં વરસાવે છે, ત્યારે એવું લાગે છે કે તમારી મંગલ વાણી વરસી રહી છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो सव्वोसहि पत्ताणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo savvosahi pattāṇaṃ"}],"mantra":[{"dev":"ॐ ह्रीं श्रीं क्लीं ब्लूं ध्यान सिद्धि परम योगीश्वराय नमो नमः स्वाहा।","iast":"Oṃ hrīṃ śrīṃ klīṃ blūṃ dhyāna siddhi parama yogīśvarāya namo namaḥ svāhā"}],"method":{"en":"Become pure, wear white clothes, face east, set up the yantra and perform the worship. Then sit on a white seat facing north and, with a white rosary, offering guggul incense mixed with ghee, chant the riddhi and the mantra 1,008 times to attain perfection.","es":"Purifícate, vístete de blanco, mira al este, coloca el yantra y realiza la adoración. Luego siéntate en un asiento blanco mirando al norte y, con un rosario blanco, ofreciendo incienso de guggul mezclado con ghee, canta 1.008 veces la riddhi y el mantra para alcanzar la perfección.","hi":"पवित्र होकर धवल वस्त्र धारण कर पूर्व दिशा की ओर मुख करके यंत्र स्थापित करें, यंत्र की पूजा अर्चना करें पश्चात् सफेद आसन पर उत्तर दिशा की ओर मुख करके बैठकर सफेद माला द्वारा घृत मिश्रित गुग्गुल की धूप क्षेपण करते हुये एक हजार आठ बार ऋद्धि मंत्र का जाप कर सिद्धि प्राप्त करना चाहिये।","pt":"Purifique-se, vista roupas brancas, volte-se para o leste, coloque o yantra e faça a adoração. Depois sente-se em um assento branco voltado para o norte e, com um rosário branco, oferecendo incenso de guggul misturado com ghee, entoe o riddhi e o mantra 1.008 vezes para alcançar a perfeição.","it":"Purificati, indossa abiti bianchi, rivolgiti a est, disponi lo yantra ed esegui l’adorazione. Poi siediti su un sedile bianco rivolto a nord e, con un rosario bianco, offrendo incenso di guggul mescolato a ghi, intona il riddhi e il mantra 1.008 volte per raggiungere la perfezione.","gu":"શુદ્ધ થઈ, સફેદ વસ્ત્રો પહેરી, પૂર્વ તરફ મુખ રાખી યંત્રની સ્થાપના કરી પૂજા કરો. પછી ઉત્તર તરફ મુખ રાખી સફેદ આસન પર બેસો અને સફેદ માળા વડે, ઘી મિશ્રિત ગુગળનો ધૂપ અર્પણ કરતાં, સિદ્ધિ મેળવવા માટે ઋદ્ધિ અને મંત્રનો 1,008 વાર જાપ કરો."},"benefit":{"en":"A cord is made from raw thread spun by an unmarried girl and charged 21 times with the 33rd verse, the riddhi and the mantra; tied on, used for a blessing-rite (jhada), and with the yantra kept nearby, it removes alternate-day fever (ekatara), third-day fever (tijari) and similar illnesses.","es":"Con hilo crudo hilado por una joven soltera se hace un cordón y se carga 21 veces con el verso 33, la riddhi y el mantra; atado, usado en un rito de bendición (jhada) y con el yantra cerca, elimina la fiebre alterna (ekatara), la fiebre de tercer día (tijari) y males semejantes.","hi":"कुमारी कन्या द्वारा काते हुए कच्चे धागे का कंडा बनाकर और उसे तेंतीसवें काव्य, ऋद्धि तथा मंत्र द्वारा इक्कीस बार मंत्रित कर बाँधने झाड़ा देने तथा यंत्र पास में रखने से एकातरा ताप ज्वर, तिजारी आदि रोग दूर होते हैं।","pt":"Faz-se um cordão com fio cru fiado por uma jovem solteira, carregado 21 vezes com o 33º verso, o riddhi e o mantra; amarrado, usado em um rito de bênção (jhada) e com o yantra mantido por perto, ele remove a febre em dias alternados (ekatara), a febre terçã (tijari) e doenças semelhantes.","it":"Si prepara un cordoncino con filo grezzo filato da una ragazza nubile, caricato 21 volte con il 33º verso, il riddhi e il mantra; legato, usato in un rito di benedizione (jhada) e con lo yantra tenuto vicino, rimuove la febbre a giorni alterni (ekatara), la febbre terzana (tijari) e malattie simili.","gu":"કુંવારી કન્યાએ કાંતેલા કાચા દોરાનો દોરો બનાવી, 33મા શ્લોક, ઋદ્ધિ અને મંત્ર વડે 21 વાર અભિમંત્રિત કરો; તે બાંધવાથી, ઝાડફૂંક કરવાથી અને યંત્ર પાસે રાખવાથી એકાંતરિયો તાવ (એકતરા), તરિયો તાવ (તિજારી) અને તેવા રોગો દૂર થાય છે."}},{"n":34,"sa":["शुम्भत्प्रभा-वलय-भूरि-विभा विभोस्ते,","लोकत्रये द्युतिमतां द्युतिमा-क्षिपन्ती।","प्रोद्यद्-दिवाकर-निरन्तर-भूरि-संख्या,","दीप्त्या जयत्यपि निशामपि सोम-सौम्याम्।।३४।।"],"pron":["śumbhatprabhā-valaya-bhūri-vibhā vibhoste,","lokatraye dyutimatāṃ dyutimā-kṣipantī|","prodyad-divākara-nirantara-bhūri-saṃkhyā,","dīptyā jayatyapi niśāmapi soma-saumyām||34||"],"title":{"en":"The gentle halo","hi":"कोमल प्रभामंडल","es":"El halo suave","pt":"O halo suave","it":"Il dolce alone","gu":"કોમળ પ્રભામંડળ"},"meaning":{"en":"Your luminous halo outshines the light of all the luminaries of the three worlds, brighter than many rising suns, yet calm and soothing as moonlight that dispels the night.","hi":"आपका तेजस्वी प्रभामंडल तीनों लोकों के सभी ज्योतिपुंजों की कांति को मात देता है, अनेक उदित सूर्यों से भी उज्ज्वल, फिर भी रात्रि का अंधकार हरने वाली चाँदनी-सा शांत और शीतल।","es":"Tu halo luminoso supera el brillo de todos los astros de los tres mundos, más radiante que muchos soles naciendo, y a la vez sereno y suave como la luz de luna que disipa la noche.","pt":"Teu halo luminoso ofusca a luz de todos os astros dos três mundos, mais brilhante que muitos sóis nascentes, e ainda assim sereno e suave como o luar que dissipa a noite.","it":"Il tuo alone luminoso offusca la luce di tutti gli astri dei tre mondi, più brillante di molti soli nascenti, eppure calmo e lenitivo come il chiaro di luna che dissolve la notte.","gu":"તમારું તેજસ્વી પ્રભામંડળ ત્રણે લોકના સર્વ તેજસ્વી પદાર્થોના પ્રકાશને ઝાંખો કરી દે છે, અનેક ઊગતા સૂર્યોથી વધુ તેજસ્વી, છતાં રાત્રિને હરનાર ચાંદની જેવું શાંત અને શીતળ."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो खिल्लोसहिपत्ताणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo khillosahipattāṇaṃ"}],"mantra":[{"dev":"ॐ नमो ह्रीं श्रीं ऐं ह्रौं पद्मावत्यै देव्यै नमो नमः स्वाहा।","iast":"Oṃ namo hrīṃ śrīṃ aiṃ hrauṃ padmāvatyai devyai namo namaḥ svāhā"}],"method":{"en":"Become pure, wear white silk clothes and face north. Set up the auspicious pot and the yantra and worship the yantra. Then sit on a white seat facing east in the lotus posture and, with a crystal rosary, chant the riddhi and the mantra 12,000 times to attain perfection.","es":"Purifícate, vístete con ropa de seda blanca y mira al norte. Coloca el cántaro auspicioso y el yantra y adora el yantra. Luego siéntate en un asiento blanco mirando al este en la postura del loto y, con un rosario de cristal, canta 12.000 veces la riddhi y el mantra para alcanzar la perfección.","hi":"पवित्र होकर सफेद रेशमी वस्त्र धारण कर उत्तर दिशा की ओर मुख करके मंगल कलश तथा यंत्र की स्थापना कर यंत्र की पूजा करें पश्चात् सफेद आसन पर पूर्व दिशा की ओर मुख करके पद्मासन लगाकर स्फटिक मणि की माला द्वारा बारह हजार बार ऋद्धि, मंत्र जपकर सिद्धि प्राप्त करना चाहिए।","pt":"Purifique-se, vista roupas brancas de seda e volte-se para o norte. Coloque o pote auspicioso e o yantra e adore o yantra. Depois sente-se em um assento branco voltado para o leste na postura de lótus e, com um rosário de cristal, entoe o riddhi e o mantra 12.000 vezes para alcançar a perfeição.","it":"Purificati, indossa abiti di seta bianca e rivolgiti a nord. Disponi il vaso benaugurale e lo yantra e adora lo yantra. Poi siediti su un sedile bianco rivolto a est nella posizione del loto e, con un rosario di cristallo, intona il riddhi e il mantra 12.000 volte per raggiungere la perfezione.","gu":"શુદ્ધ થઈ, સફેદ રેશમી વસ્ત્રો પહેરી ઉત્તર તરફ મુખ રાખો. મંગળ કળશ અને યંત્રની સ્થાપના કરી યંત્રની પૂજા કરો. પછી પૂર્વ તરફ મુખ રાખી સફેદ આસન પર પદ્માસનમાં બેસી, સ્ફટિકની માળા વડે સિદ્ધિ મેળવવા માટે ઋદ્ધિ અને મંત્રનો 12,000 વાર જાપ કરો."},"benefit":{"en":"A thread dyed saffron is charged 108 times with the 34th verse, the riddhi and the mantra, fumigated with guggul smoke and tied around the neck or the waist. With the yantra kept nearby, the womb is held firm and an untimely miscarriage does not occur.","es":"Un hilo teñido de azafrán se carga 108 veces con el verso 34, la riddhi y el mantra, se sahúma con humo de guggul y se ata al cuello o a la cintura. Con el yantra cerca, el embarazo se mantiene firme y no ocurre una pérdida prematura.","hi":"केशरिया रंग से रंगे हुए धागे को एक सौ आठ बार चौतीसवें काव्य ऋद्धि तथा मंत्र से मंत्रित कर गूगल की धूनी देकर गले में या कटिप्रदेश में बाँधने और यंत्र को पास में रखने से गर्भ का स्तम्भन होता है, असमय में गर्भ का पतन नहीं होता।","pt":"Um fio tingido de açafrão é carregado 108 vezes com o 34º verso, o riddhi e o mantra, defumado com fumaça de guggul e amarrado no pescoço ou na cintura. Com o yantra mantido por perto, o ventre se mantém firme e não ocorre um aborto espontâneo fora de hora.","it":"Un filo tinto di zafferano viene caricato 108 volte con il 34º verso, il riddhi e il mantra, affumicato con fumo di guggul e legato al collo o alla vita. Con lo yantra tenuto vicino, il grembo si mantiene saldo e non si verifica un aborto spontaneo prematuro.","gu":"કેસરી રંગે રંગેલા દોરાને 34મા શ્લોક, ઋદ્ધિ અને મંત્ર વડે 108 વાર અભિમંત્રિત કરી, ગુગળના ધુમાડાથી ધૂપિત કરીને ગળામાં અથવા કમરે બાંધો. યંત્ર પાસે રાખવાથી ગર્ભ સ્થિર રહે છે અને અકાળે ગર્ભપાત થતો નથી."}},{"n":35,"sa":["स्वर्गा-पवर्ग-गममार्ग-विमार्गणेष्टः,","सद्धर्म तत्त्व-कथनैक-पटुस्-त्रिलोक्याः।","दिव्य-ध्वनिर्-भवति ते विशदार्थ-सर्व-","भाषा-स्वभाव-परिणाम-गुणैः प्रयोज्यः।।३५।।"],"pron":["svargā-pavarga-gamamārga-vimārgaṇeṣṭaḥ,","saddharma tattva-kathanaika-paṭus-trilokyāḥ|","divya-dhvanir-bhavati te viśadārtha-sarva-","bhāṣā-svabhāva-pariṇāma-guṇaiḥ prayojyaḥ||35||"],"title":{"en":"Teaching for every listener","hi":"हर श्रोता के लिए उपदेश","es":"Enseñanza para cada oyente","pt":"Um ensinamento para cada ouvinte","it":"Un insegnamento per ogni ascoltatore","gu":"દરેક શ્રોતા માટે ઉપદેશ"},"meaning":{"en":"Your soothing divine voice shows the path to heaven and to liberation, explains the true nature of the highest dharma, and turns into every language, so that all can understand.","hi":"आपकी शांतिदायिनी दिव्य ध्वनि स्वर्ग और मोक्ष का मार्ग दिखाती है, परम धर्म का सच्चा स्वरूप बताती है, और हर भाषा के रूप में परिणत हो जाती है, ताकि सब समझ सकें।","es":"Tu voz divina y serena muestra el camino al cielo y a la liberación, explica la verdadera naturaleza del dharma supremo y se transforma en cada idioma, para que todos comprendan.","pt":"Tua voz divina e suave mostra o caminho do céu e da libertação, explica a verdadeira natureza do dharma supremo e se transforma em cada idioma, para que todos possam entender.","it":"La tua voce divina e lenitiva mostra la via del cielo e della liberazione, spiega la vera natura del dharma supremo e si trasforma in ogni lingua, così che tutti possano comprendere.","gu":"તમારી શાંત દિવ્ય વાણી સ્વર્ગ અને મોક્ષનો માર્ગ બતાવે છે, પરમ ધર્મનું સાચું સ્વરૂપ સમજાવે છે અને દરેક ભાષામાં પરિણમે છે, જેથી સૌ સમજી શકે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो जल्लोसहिपत्ताणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo jallosahipattāṇaṃ"}],"mantra":[{"dev":"ॐ नमो जय विजय अपराजिते महालक्ष्मी अमृतवर्षिणी अमृतस्राविणी अमृतं भव भव वषट् सुधायै स्वाहा।","iast":"Oṃ namo jaya vijaya aparājite mahālakṣmī amṛtavarṣiṇī amṛtasrāviṇī amṛtaṃ bhava bhava vaṣaṭ sudhāyai svāhā"},{"dev":"ॐ नमो गजगमने सर्व कल्याण मूर्ते रक्ष रक्ष नमः स्वाहा।","iast":"oṃ namo gajagamane sarva kalyāṇa mūrte rakṣa rakṣa namaḥ svāhā"}],"method":{"en":"Become pure, wear yellow clothes, face north and set up the yantra and worship it. Offer yellow flowers and light a lamp. Then, with a yellow rosary, practise the riddhi and the mantra 4,000 times to attain perfection. After this too, chant 108 times every day.","es":"Purifícate, vístete de amarillo, mira al norte, coloca el yantra y adóralo. Ofrece flores amarillas y enciende una lámpara. Luego, con un rosario amarillo, practica la riddhi y el mantra 4.000 veces para alcanzar la perfección. Después de esto, canta además 108 veces cada día.","hi":"पवित्र होकर पीले रंग के वस्त्र धारण कर उत्तर दिशा की ओर मुख करके यंत्र स्थापित करें, यंत्र की पूजा करें पीले फूल चढ़ावें, दीप प्रज्वलित करें पश्चात् पीले रंग की माला द्वारा चार हजार बार ऋद्धि मंत्र की साधना कर सिद्धि प्राप्त करना चाहिए। इसके बाद भी प्रतिदिन एक सौ आठ बार जाप जपे।","pt":"Purifique-se, vista roupas amarelas, volte-se para o norte, coloque o yantra e adore-o. Ofereça flores amarelas e acenda uma lamparina. Depois, com um rosário amarelo, pratique o riddhi e o mantra 4.000 vezes para alcançar a perfeição. Depois disso também, entoe 108 vezes todos os dias.","it":"Purificati, indossa abiti gialli, rivolgiti a nord, disponi lo yantra e adoralo. Offri fiori gialli e accendi una lampada. Poi, con un rosario giallo, pratica il riddhi e il mantra 4.000 volte per raggiungere la perfezione. Anche dopo, intona 108 volte ogni giorno.","gu":"શુદ્ધ થઈ, પીળાં વસ્ત્રો પહેરી, ઉત્તર તરફ મુખ રાખી યંત્રની સ્થાપના કરી તેની પૂજા કરો. પીળાં ફૂલ અર્પણ કરો અને દીવો પ્રગટાવો. પછી પીળી માળા વડે સિદ્ધિ મેળવવા માટે ઋદ્ધિ અને મંત્રની 4,000 વાર સાધના કરો. તે પછી પણ રોજ 108 વાર જાપ કરો."},"benefit":{"en":"Keeping the yantra with you and practising the 35th verse, the riddhi and the mantra removes epidemic (mari), epilepsy, theft, famine and fear from the state, and brings profit in business, standing in the state, and one's word is regarded as trustworthy.","es":"Teniendo el yantra contigo y practicando el verso 35, la riddhi y el mantra, se alejan la epidemia (mari), la epilepsia, el robo, la hambruna y el temor al poder del Estado; trae ganancia en los negocios, reconocimiento en el Estado, y la palabra de uno se tiene por digna de crédito.","hi":"यंत्र पास में रखने और पैंतीसवें काव्य, ऋद्धि तथा मंत्र की आराधना से मरी, मिरगी, चोरी दुर्भिक्ष राज्य भय आदि दूर होते हैं तथा व्यापार में लाभ होता है राज्य में मान्यता होती है वचन प्रामाणिक माने जाते हैं।","pt":"Mantendo o yantra consigo e praticando o 35º verso, o riddhi e o mantra, afastam-se a epidemia (mari), a epilepsia, o roubo, a fome e o medo vindo do governo, e vêm lucro nos negócios, prestígio junto ao governo, e a palavra da pessoa passa a ser considerada digna de confiança.","it":"Tenendo con te lo yantra e praticando il 35º verso, il riddhi e il mantra, si allontanano epidemia (mari), epilessia, furto, carestia e timore del governo, e arrivano guadagno negli affari, prestigio presso il governo, e la parola della persona viene ritenuta degna di fiducia.","gu":"યંત્ર પોતાની પાસે રાખી, 35મા શ્લોક, ઋદ્ધિ અને મંત્રની સાધના કરવાથી મરકી, વાઈ, ચોરી, દુકાળ અને રાજ્ય તરફથી ભય દૂર થાય છે, વેપારમાં નફો થાય છે, રાજ્યમાં પ્રતિષ્ઠા મળે છે અને વ્યક્તિની વાત વિશ્વસનીય ગણાય છે."}},{"n":36,"sa":["उन्निद्र-हेम-नवपंकजपुंज-कान्ति-,","पर्युल्लसन्नख-मयूख-शिखा-भिरामौ।।","पादौ पदानि तव यत्र जिनेन्द्र धत्तः,","पद्मानि तत्र विबुधाः परि-कल्पयन्ति।।३६।।"],"pron":["unnidra-hema-navapaṃkajapuṃja-kānti-,","paryullasannakha-mayūkha-śikhā-bhirāmau||","pādau padāni tava yatra jinendra dhattaḥ,","padmāni tatra vibudhāḥ pari-kalpayanti||36||"],"title":{"en":"Lotuses beneath each step","hi":"हर कदम पर कमल","es":"Lotos bajo cada paso","pt":"Lótus sob cada passo","it":"Loti sotto ogni passo","gu":"દરેક પગલે કમળ"},"meaning":{"en":"Wherever your feet come to rest, the gods place nine golden lotuses beneath them, fresh and glowing, their petals bright as polished nails.","hi":"जहाँ आपके चरण पड़ते हैं, वहाँ देव आपके चरणों के नीचे नौ स्वर्ण-कमल बिछा देते हैं, ताज़े और दीप्तिमान।","es":"Dondequiera que se posan tus pies, los dioses colocan debajo nueve lotos dorados, frescos y radiantes.","pt":"Onde quer que teus pés repousem, os deuses colocam nove lótus dourados sob eles, frescos e luminosos, com pétalas brilhantes como unhas polidas.","it":"Ovunque i tuoi piedi si posino, gli dèi pongono sotto di essi nove loti dorati, freschi e luminosi, con petali brillanti come unghie lucidate.","gu":"તમારા ચરણ જ્યાં પણ ટકે ત્યાં દેવો તેમની નીચે નવ સુવર્ણ કમળ મૂકે છે, તાજાં અને તેજસ્વી, જેની પાંખડીઓ ઘસીને ચમકાવેલાં નખ જેવી ઉજ્જવળ છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो विप्पोसहि पत्ताणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo vipposahi pattāṇaṃ"}],"mantra":[{"dev":"ॐ ह्रीं श्रीं कलिकुण्ड दण्ड स्वामिन् आगच्छ आगच्छ, आत्ममंत्रान् आकर्षय आकर्षय। आत्ममंत्रान् रक्ष रक्ष, परमंत्रान् छिन्द छिन्द मम समीहितं कुरु कुरु स्वाहा।","iast":"Oṃ hrīṃ śrīṃ kalikuṇḍa daṇḍa svāmin āgaccha āgaccha, ātmamaṃtrān ākarṣaya ākarṣaya ātmamaṃtrān rakṣa rakṣa, paramaṃtrān chinda chinda mama samīhitaṃ kuru kuru svāhā"}],"method":{"en":"After bathing, wear yellow clothes, face north and set up the yantra. Worship the yantra with yellow flowers and light a lamp. Then sit on a yellow seat in the lotus posture and, with a yellow rosary, complete 12,000 repetitions to perfect the mantra.","es":"Después de bañarte, vístete de amarillo, mira al norte y coloca el yantra. Adora el yantra con flores amarillas y enciende una lámpara. Luego siéntate en un asiento amarillo en la postura del loto y, con un rosario amarillo, completa 12.000 repeticiones para perfeccionar el mantra.","hi":"स्नान करके पीले वस्त्र धारण कर उत्तर दिशा की ओर मुख करके यंत्र स्थापित कर यंत्र की पूजा पीले फूलों से करें, दीपक जलावें पश्चात् पीले आसन पर पद्मासन लगाकर पीली माला द्वारा बारह हजार जप पूर्ण कर मंत्र सिद्ध करना चाहिए।","pt":"Depois do banho, vista roupas amarelas, volte-se para o norte e coloque o yantra. Adore o yantra com flores amarelas e acenda uma lamparina. Depois sente-se em um assento amarelo na postura de lótus e, com um rosário amarelo, complete 12.000 repetições para aperfeiçoar o mantra.","it":"Dopo il bagno, indossa abiti gialli, rivolgiti a nord e disponi lo yantra. Adora lo yantra con fiori gialli e accendi una lampada. Poi siediti su un sedile giallo nella posizione del loto e, con un rosario giallo, completa 12.000 ripetizioni per rendere perfetto il mantra.","gu":"સ્નાન કરી પીળાં વસ્ત્રો પહેરો, ઉત્તર તરફ મુખ રાખી યંત્રની સ્થાપના કરો. પીળાં ફૂલોથી યંત્રની પૂજા કરો અને દીવો પ્રગટાવો. પછી પીળા આસન પર પદ્માસનમાં બેસી, પીળી માળા વડે મંત્ર સિદ્ધ કરવા માટે 12,000 જાપ પૂરા કરો."},"benefit":{"en":"Keeping the yantra with you and practising the 36th verse, the riddhi and the mantra 108 times every day, wealth (Lakshmi) is gained in the trade of gold and other metals. Standing in the state is gained. One's word is held to be trustworthy among the village elders (panch).","es":"Teniendo el yantra contigo y practicando cada día 108 veces el verso 36, la riddhi y el mantra, se gana prosperidad (Lakshmi) en el comercio del oro y otros metales. Se obtiene reconocimiento en el Estado. La palabra de uno se tiene por digna de crédito entre los ancianos del pueblo (panch).","hi":"यंत्र पास में रखने तथा प्रतिदिन एक सौ आठ बार छत्तीसवें काव्य ऋद्धि मंत्र के आराधन से सुवर्णादिक धातुओं के व्यापार में लक्ष्मी का लाभ होता है। राज्य में मान्यता प्राप्त होती है। पाँच पंचों में बात प्रामाणिक मानी जाती है।","pt":"Mantendo o yantra consigo e praticando o 36º verso, o riddhi e o mantra 108 vezes por dia, ganha-se riqueza (Lakshmi) no comércio de ouro e de outros metais. Conquista-se prestígio junto ao governo. A palavra da pessoa é tida como digna de confiança entre os anciãos da aldeia (panch).","it":"Tenendo con te lo yantra e praticando il 36º verso, il riddhi e il mantra 108 volte al giorno, si ottiene ricchezza (Lakshmi) nel commercio di oro e di altri metalli. Si ottiene prestigio presso il governo. La parola della persona è ritenuta degna di fiducia tra gli anziani del villaggio (panch).","gu":"યંત્ર પોતાની પાસે રાખી, રોજ 36મો શ્લોક, ઋદ્ધિ અને મંત્ર 108 વાર સાધવાથી સોના અને અન્ય ધાતુઓના વેપારમાં લક્ષ્મી (ધન) મળે છે. રાજ્યમાં પ્રતિષ્ઠા મળે છે. ગામના પંચમાં વ્યક્તિની વાત વિશ્વસનીય ગણાય છે."}},{"n":37,"sa":["इत्थं यथा तव विभूति-रभूज्जिनेन्द्र,","धर्मोप-देशन विधौ न तथा परस्य।","यादृक् प्रभा दिनकृतः प्रहतान्ध-कारा,","तादृक्कुतो ग्रह-गणस्य विकासिनोऽपि।।३७।।"],"pron":["itthaṃ yathā tava vibhūti-rabhūjjinendra,","dharmopa-deśana vidhau na tathā parasya|","yādṛk prabhā dinakṛtaḥ prahatāndha-kārā,","tādṛkkuto graha-gaṇasya vikāsino’pi||37||"],"title":{"en":"The light of teaching","hi":"उपदेश का प्रकाश","es":"La luz de la enseñanza","pt":"A luz do ensinamento","it":"La luce dell’insegnamento","gu":"ઉપદેશનો પ્રકાશ"},"meaning":{"en":"The glory you show when you teach dharma is found in no other teacher, just as a gathering of stars cannot match the blaze of the sun that drives away darkness.","hi":"धर्मोपदेश के समय आपकी जो विभूति प्रकट होती है, वह किसी और में नहीं; जैसे नक्षत्रों का समूह अंधकार हरने वाले सूर्य के तेज की बराबरी नहीं कर सकता।","es":"La gloria que muestras al enseñar el dharma no se halla en ningún otro maestro, así como un grupo de estrellas no iguala el resplandor del sol que ahuyenta la oscuridad.","pt":"A glória que mostras ao ensinar o dharma não se encontra em nenhum outro mestre, assim como um conjunto de estrelas não se iguala ao clarão do sol que expulsa a escuridão.","it":"La gloria che mostri quando insegni il dharma non si trova in nessun altro maestro, così come un insieme di stelle non può eguagliare il fulgore del sole che scaccia l’oscurità.","gu":"ધર્મનો ઉપદેશ આપતી વખતે તમે જે મહિમા દર્શાવો છો તે બીજા કોઈ ઉપદેશકમાં જોવા મળતો નથી, જેમ તારાઓનો સમૂહ અંધકારને હરનાર સૂર્યના તેજની બરાબરી કરી શકતો નથી."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो सव्वोसहि पत्ताणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo savvosahi pattāṇaṃ"}],"mantra":[{"dev":"ॐ नमो भगवते अप्रतिचक्रे ऐं क्लीं ब्लूं ॐ ह्रीं मनोवांछित सिद्धयै नमो नमः अप्रतिचक्रे ह्रीं ठः ठः स्वाहा।","iast":"Oṃ namo bhagavate apraticakre aiṃ klīṃ blūṃ oṃ hrīṃ manovāṃchita siddhayai namo namaḥ apraticakre hrīṃ ṭhaḥ ṭhaḥ svāhā"}],"method":{"en":"After bathing, wear white clothes, face north, set up the yantra and worship it. Then sit on a white seat and prepare 1,008 pellets of guggul, camphor, saffron and musk mixed together. While chanting the riddhi and the mantra, drop the pellets one by one into the fire. In this way, practise the mantra to attain perfection.","es":"Después de bañarte, vístete de blanco, mira al norte, coloca el yantra y adóralo. Luego siéntate en un asiento blanco y prepara 1.008 bolitas de guggul, alcanfor, azafrán y almizcle mezclados. Mientras cantas la riddhi y el mantra, echa las bolitas una a una al fuego. De este modo practica el mantra hasta alcanzar la perfección.","hi":"स्नान करके सफेद वस्त्र धारण कर उत्तर दिशा की ओर मुख करके यंत्र स्थापित कर उसकी पूजा अर्चना करें पश्चात् धवलासन पर बैठकर गुग्गुल कपूर केशर कस्तूरी मिश्रित एक हजार आठ गोली बनावें और ऋद्धि मंत्र का जाप करते हुये एक-एक गोली अग्नि में छोड़ता जावे। इस प्रकार मंत्राराधन कर सिद्धि प्राप्त करना चाहिए।","pt":"Depois do banho, vista roupas brancas, volte-se para o norte, coloque o yantra e adore-o. Depois sente-se em um assento branco e prepare 1.008 bolinhas de guggul, cânfora, açafrão e almíscar misturados. Enquanto entoa o riddhi e o mantra, solte as bolinhas, uma a uma, no fogo. Dessa forma, pratique o mantra para alcançar a perfeição.","it":"Dopo il bagno, indossa abiti bianchi, rivolgiti a nord, disponi lo yantra e adoralo. Poi siediti su un sedile bianco e prepara 1.008 pallini di guggul, canfora, zafferano e muschio mescolati. Mentre intoni il riddhi e il mantra, lascia cadere i pallini uno a uno nel fuoco. In questo modo pratica il mantra per raggiungere la perfezione.","gu":"સ્નાન કરી સફેદ વસ્ત્રો પહેરો, ઉત્તર તરફ મુખ રાખી યંત્રની સ્થાપના કરી તેની પૂજા કરો. પછી સફેદ આસન પર બેસી ગુગળ, કપૂર, કેસર અને કસ્તૂરી ભેળવીને 1,008 ગોળીઓ બનાવો. ઋદ્ધિ અને મંત્રનો જાપ કરતાં કરતાં ગોળીઓ એક-એક કરીને અગ્નિમાં હોમો. આ રીતે સિદ્ધિ મેળવવા માટે મંત્રની સાધના કરો."},"benefit":{"en":"Keeping the yantra with you, and sprinkling on the face water charged 21 times with the 37th verse, the riddhi and the mantra, halts the harsh words of wicked people; fame and renown increase.","es":"Teniendo el yantra contigo y rociando en el rostro agua cargada 21 veces con el verso 37, la riddhi y el mantra, se detienen las palabras duras de las personas malvadas; aumentan la fama y el renombre.","hi":"यंत्र पास में रखने तथा सैंतीसवें काव्य ऋद्धि तथा मंत्र से इक्कीस बार जल मंत्रित कर मुख पर छिड़कने से दुष्ट पुरुषों के दुर्वचनों का स्तम्भन होता है कीर्ति तथा यश की वृद्धि होती है।","pt":"Mantendo o yantra consigo e borrifando no rosto água carregada 21 vezes com o 37º verso, o riddhi e o mantra, detêm-se as palavras ásperas de pessoas más; a fama e a reputação aumentam.","it":"Tenendo con te lo yantra e spruzzando sul viso acqua caricata 21 volte con il 37º verso, il riddhi e il mantra, si fermano le parole aspre dei malvagi; fama e reputazione aumentano.","gu":"યંત્ર પોતાની પાસે રાખી, 37મા શ્લોક, ઋદ્ધિ અને મંત્ર વડે 21 વાર અભિમંત્રિત કરેલું પાણી ચહેરા પર છાંટવાથી દુષ્ટ લોકોના કઠોર શબ્દો અટકે છે; કીર્તિ અને નામના વધે છે."}},{"n":38,"sa":["श्च्योतन्-मदा-विल-विलोल-कपोल-मूल-","मत्त-भ्रमद्-भ्रमर-नाद-विवृद्ध-कोपम्।","ऐरावताभ-मिभ-मुद्धत-मापतन्तं,","दृष्ट्वा भयं भवति नो भवदा-श्रितानाम्।।३८।।"],"pron":["ścyotan-madā-vila-vilola-kapola-mūla-","matta-bhramad-bhramara-nāda-vivṛddha-kopam|","airāvatābha-mibha-muddhata-māpatantaṃ,","dṛṣṭvā bhayaṃ bhavati no bhavadā-śritānām||38||"],"title":{"en":"Facing the elephant","hi":"हाथी का सामना","es":"Frente al elefante","pt":"Diante do elefante","it":"Davanti all’elefante","gu":"હાથી સામે"},"meaning":{"en":"Those who take refuge in you stay unafraid even before a huge, maddened elephant, like Airavata, with bees whirling round its streaming cheeks.","hi":"जो आपकी शरण लेते हैं, वे ऐरावत जैसे विशाल, मदमस्त हाथी के सामने भी निडर रहते हैं, जिसके मद-स्रावी गालों पर भौंरे मँडरा रहे हों।","es":"Quienes se refugian en ti permanecen sin miedo incluso ante un elefante enorme y enfurecido, como Airavata, con abejas girando en torno a sus mejillas.","pt":"Quem se refugia em ti permanece sem medo mesmo diante de um enorme elefante enfurecido, como Airavata, com abelhas rodopiando em torno de suas têmporas escorrendo.","it":"Chi prende rifugio in te resta senza paura anche davanti a un enorme elefante infuriato, come Airavata, con api che ronzano attorno alle sue tempie stillanti.","gu":"જે તમારું શરણ લે છે તે ઐરાવત જેવા વિશાળ, મદોન્મત્ત હાથી સામે પણ નિર્ભય રહે છે, જેના વહેતા ગંડસ્થળ પર ભમરાઓ ગુંજી રહ્યા હોય."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो मणबलीणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo maṇabalīṇaṃ"}],"mantra":[{"dev":"ॐ नमो भगवते महानाग कुलोच्चाटिनी काल दंष्ट्र मृतकोत्थापिनी पर मंत्र प्रणाशिनी देवि शासन देवते ह्रीं नमो नमः स्वाहा।","iast":"Oṃ namo bhagavate mahānāga kuloccāṭinī kāla daṃṣṭra mṛtakotthāpinī para maṃtra praṇāśinī devi śāsana devate hrīṃ namo namaḥ svāhā"},{"dev":"ॐ ह्रीं शत्रु विजयरणाग्रे ग्रां ग्रीं ग्रूं ग्रः नमो नमः स्वाहा।","iast":"oṃ hrīṃ śatru vijayaraṇāgre grāṃ grīṃ grūṃ graḥ namo namaḥ svāhā"}],"method":{"en":"Become pure, wear yellow clothes, face north, set up the yantra and perform its worship. Then sit on a yellow seat and, with a yellow rosary, recall the riddhi and the mantra 1,008 times to attain perfection of the mantra.","es":"Purifícate, vístete de amarillo, mira al norte, coloca el yantra y realiza su adoración. Luego siéntate en un asiento amarillo y, con un rosario amarillo, recuerda 1.008 veces la riddhi y el mantra para alcanzar la perfección del mantra.","hi":"पवित्र होकर पीले वस्त्र पहनकर उत्तर दिशा की ओर मुख करके यंत्र स्थापित कर यंत्र की पूजार्चा करने के पश्चात् पीले आसन पर बैठकर पीली माला द्वारा एक हजार आठ बार ऋद्धि मंत्र का स्मरण करते हुए मंत्र सिद्ध करना चाहिए।","pt":"Purifique-se, vista roupas amarelas, volte-se para o norte, coloque o yantra e faça a sua adoração. Depois sente-se em um assento amarelo e, com um rosário amarelo, recorde o riddhi e o mantra 1.008 vezes para alcançar a perfeição do mantra.","it":"Purificati, indossa abiti gialli, rivolgiti a nord, disponi lo yantra ed esegui la sua adorazione. Poi siediti su un sedile giallo e, con un rosario giallo, ricorda il riddhi e il mantra 1.008 volte per raggiungere la perfezione del mantra.","gu":"શુદ્ધ થઈ, પીળાં વસ્ત્રો પહેરી, ઉત્તર તરફ મુખ રાખી યંત્રની સ્થાપના કરી તેની પૂજા કરો. પછી પીળા આસન પર બેસી, પીળી માળા વડે મંત્રની સિદ્ધિ મેળવવા માટે ઋદ્ધિ અને મંત્ર 1,008 વાર યાદ કરો."},"benefit":{"en":"By repeatedly practising the 38th verse, the riddhi and the mantra, and keeping the yantra with you, a rutting elephant is brought under control and wealth is gained.","es":"Practicando repetidamente el verso 38, la riddhi y el mantra, y teniendo el yantra contigo, se domina a un elefante enloquecido y se obtiene riqueza.","hi":"अड़तीसवाँ काव्य ऋद्धि तथा मंत्र की बारम्बार आराधना करने और यंत्र को पास में रखने से मदोन्मत्त हाथी वश में होता है और अर्थ की प्राप्ति होती है।","pt":"Praticando repetidamente o 38º verso, o riddhi e o mantra, e mantendo o yantra consigo, um elefante no cio é dominado e ganha-se riqueza.","it":"Praticando di continuo il 38º verso, il riddhi e il mantra, e tenendo con te lo yantra, un elefante in calore viene domato e si ottiene ricchezza.","gu":"38મો શ્લોક, ઋદ્ધિ અને મંત્રની વારંવાર સાધના કરવાથી અને યંત્ર પોતાની પાસે રાખવાથી મદોન્મત્ત હાથી વશમાં આવે છે અને ધન પ્રાપ્ત થાય છે."}},{"n":39,"sa":["भिन्नेभ-कुम्भ-गल-दुज्ज्वल-शोणिताक्त-","मुक्ताफल-प्रकर-भूषित-भूमिभागः।","बद्ध-क्रमः क्रम-गतं हरिणा-धिपोऽपि,","नाक्रामति क्रम-युगाचल-संश्रितं ते।।३९।।"],"pron":["bhinnebha-kumbha-gala-dujjvala-śoṇitākta-","muktāphala-prakara-bhūṣita-bhūmibhāgaḥ|","baddha-kramaḥ krama-gataṃ hariṇā-dhipo’pi,","nākrāmati krama-yugācala-saṃśritaṃ te||39||"],"title":{"en":"Facing the lion","hi":"सिंह का सामना","es":"Frente al león","pt":"Diante do leão","it":"Davanti al leone","gu":"સિંહ સામે"},"meaning":{"en":"Even a fierce lion that has torn open an elephant’s forehead, scattering bloody pearls on the ground, does not attack one who has taken shelter at your feet.","hi":"हाथी का मस्तक चीरकर रक्त-रंजित मोती बिखेरने वाला भयंकर सिंह भी उस पर आक्रमण नहीं करता जो आपके चरणों की शरण में है।","es":"Ni siquiera un feroz león que ha desgarrado la frente de un elefante y esparcido perlas ensangrentadas ataca a quien se ha refugiado a tus pies.","pt":"Nem mesmo um leão feroz, que rasgou a testa de um elefante e espalhou pelo chão pérolas ensanguentadas, ataca quem se abrigou aos teus pés.","it":"Nemmeno un leone feroce, che ha squarciato la fronte di un elefante spargendo al suolo perle insanguinate, attacca chi ha preso rifugio ai tuoi piedi.","gu":"હાથીનું કપાળ ચીરી નાખી જમીન પર લોહીથી ખરડાયેલાં મોતી વેરી નાખનાર ભયંકર સિંહ પણ તમારા ચરણનું શરણ લેનાર પર હુમલો કરતો નથી."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो वयणबलीणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo vayaṇabalīṇaṃ"}],"mantra":[{"dev":"ॐ नमो एषु वृत्तेषु वर्द्धमान तव भयहरं वृत्ति वर्णायेषु मंत्राः पुनः स्मर्तव्या अतो ना-परमंत्र निवेदनाय नमः स्वाहा।","iast":"Oṃ namo eṣu vṛtteṣu varddhamāna tava bhayaharaṃ vṛtti varṇāyeṣu maṃtrāḥ punaḥ smartavyā ato nā-paramaṃtra nivedanāya namaḥ svāhā"}],"method":{"en":"Become pure, wear yellow clothes, face east, set up the yantra and worship it. Then sit on a yellow seat facing north and, with a yellow rosary, practise the riddhi and the mantra 1,008 times with a pure mind. After each mantra, keep offering incense of guggul, saffron, camphor and musk mixed with ghee.","es":"Purifícate, vístete de amarillo, mira al este, coloca el yantra y adóralo. Luego siéntate en un asiento amarillo mirando al norte y, con un rosario amarillo, practica la riddhi y el mantra 1.008 veces con mente pura. Después de cada mantra, sigue ofreciendo incienso de guggul, azafrán, alcanfor y almizcle mezclados con ghee.","hi":"पवित्र होकर पीले वस्त्र पहनकर पूर्व दिशा की ओर मुख करके यंत्र स्थापित कर उसकी पूजा करें। पश्चात् पीले आसन पर उत्तर दिशा की ओर मुख करके बैठकर पीत वर्ण की माला द्वारा एक हजार आठ बार ऋद्धि मंत्र का शुद्ध मन से आराधन करें तथा प्रत्येक मंत्र के बाद गुग्गुल, केशर, कर्पूर, कस्तूरी घृत मिश्रित धूप को खेते रहना चाहिए।","pt":"Purifique-se, vista roupas amarelas, volte-se para o leste, coloque o yantra e adore-o. Depois sente-se em um assento amarelo voltado para o norte e, com um rosário amarelo, pratique o riddhi e o mantra 1.008 vezes com a mente pura. Depois de cada mantra, continue oferecendo incenso de guggul, açafrão, cânfora e almíscar misturados com ghee.","it":"Purificati, indossa abiti gialli, rivolgiti a est, disponi lo yantra e adoralo. Poi siediti su un sedile giallo rivolto a nord e, con un rosario giallo, pratica il riddhi e il mantra 1.008 volte con mente pura. Dopo ogni mantra, continua a offrire incenso di guggul, zafferano, canfora e muschio mescolati a ghi.","gu":"શુદ્ધ થઈ, પીળાં વસ્ત્રો પહેરી, પૂર્વ તરફ મુખ રાખી યંત્રની સ્થાપના કરી તેની પૂજા કરો. પછી ઉત્તર તરફ મુખ રાખી પીળા આસન પર બેસો અને પીળી માળા વડે શુદ્ધ મનથી ઋદ્ધિ અને મંત્રની 1,008 વાર સાધના કરો. દરેક મંત્ર પછી ઘી સાથે ભેળવેલા ગુગળ, કેસર, કપૂર અને કસ્તૂરીનો ધૂપ અર્પણ કરતા રહો."},"benefit":{"en":"By keeping the yantra with you and recalling the 39th verse, the riddhi and the mantra, there is no fear on the road of snakes, lions, tigers and other fierce wild animals, a forgotten way is found, and the devotee reaches the destination without any hardship.","es":"Teniendo el yantra contigo y recordando el verso 39, la riddhi y el mantra, no hay temor en el camino a serpientes, leones, tigres y otros animales salvajes feroces, se encuentra un camino olvidado, y el devoto llega a su destino sin ninguna dificultad.","hi":"यंत्र को पास में रखने तथा उनतालीसवें काव्य ऋद्धि और मंत्र के स्मरण करने से मार्ग में सर्प, सिंह, बाघ आदि जंगली क्रूर हिंसक पशुओं का भय नहीं रहता तथा विस्मृत रास्ता मिल जाता है और आराधक गन्तव्य स्थान को बिना किसी कष्ट के प्राप्त कर लेता है।","pt":"Mantendo o yantra consigo e recordando o 39º verso, o riddhi e o mantra, não há medo no caminho de cobras, leões, tigres e outros animais selvagens ferozes; um caminho esquecido é encontrado, e o devoto chega ao destino sem nenhuma dificuldade.","it":"Tenendo con te lo yantra e ricordando il 39º verso, il riddhi e il mantra, non c’è timore lungo la strada di serpenti, leoni, tigri e altre fiere selvatiche, si ritrova una via dimenticata e il devoto raggiunge la meta senza alcuna difficoltà.","gu":"યંત્ર પોતાની પાસે રાખી, 39મો શ્લોક, ઋદ્ધિ અને મંત્ર યાદ કરવાથી માર્ગમાં સાપ, સિંહ, વાઘ અને અન્ય હિંસક જંગલી પ્રાણીઓનો ભય રહેતો નથી, ભૂલાયેલો રસ્તો મળી જાય છે અને ભક્ત કોઈ મુશ્કેલી વિના મંજિલે પહોંચે છે."}},{"n":40,"sa":["कल्पान्त-काल-पवनोद्धत-वह्नि-कल्पं,","दावानलं ज्वलित-मुज्ज्वल-मुत्स्फुलिंगम्।","विश्वं जिघत्सुमिव सम्मुख-मापतन्तं,","त्वन्नाम-कीर्तन-जलं शमयत्य-शेषम्।।४०।।"],"pron":["kalpānta-kāla-pavanoddhata-vahni-kalpaṃ,","dāvānalaṃ jvalita-mujjvala-mutsphuliṃgam|","viśvaṃ jighatsumiva sammukha-māpatantaṃ,","tvannāma-kīrtana-jalaṃ śamayatya-śeṣam||40||"],"title":{"en":"Water for the fire","hi":"अग्नि पर जल","es":"Agua para el fuego","pt":"Água para o fogo","it":"Acqua per il fuoco","gu":"અગ્નિ માટે જળ"},"meaning":{"en":"The fire at the world’s end, flinging sparks across the sky and rushing to swallow everything, is cooled in an instant by reciting your name, like water.","hi":"प्रलयकाल की अग्नि, जो चिंगारियाँ आकाश तक उछालती हुई सारे विश्व को निगलने दौड़ती है, आपके नाम-कीर्तन से क्षण भर में जल की भाँति शांत हो जाती है।","es":"El fuego del fin del mundo, que lanza chispas al cielo y corre a devorarlo todo, se apaga en un instante al recitar tu nombre, como con agua.","pt":"O fogo do fim do mundo, lançando faíscas pelo céu e avançando para devorar tudo, é resfriado num instante, como por água, ao recitar o teu nome.","it":"Il fuoco della fine del mondo, che scaglia scintille nel cielo e si getta a divorare ogni cosa, è raffreddato in un istante, come dall’acqua, recitando il tuo nome.","gu":"આકાશમાં તણખા ઉડાડતો અને સર્વસ્વ ગળી જવા દોડતો પ્રલયાગ્નિ, તમારું નામ લેવાથી જળની જેમ ક્ષણમાં શાંત થઈ જાય છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो कायबलीणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo kāyabalīṇaṃ"}],"mantra":[{"dev":"ॐ ह्रीं श्रीं क्लीं ह्रां ह्रीं अग्निमुपशमनं शान्तिं कुरु कुरु स्वाहा।","iast":"Oṃ hrīṃ śrīṃ klīṃ hrāṃ hrīṃ agnimupaśamanaṃ śāntiṃ kuru kuru svāhā"}],"method":{"en":"Become pure, wear red clothes, set up the auspicious pot facing east and the yantra facing north, and worship the yantra. Then sit on a red seat facing east and, with a red rosary, chant the riddhi and the mantra 12,000 times to perfect the mantra.","es":"Purifícate, vístete de rojo, coloca el cántaro auspicioso mirando al este y el yantra mirando al norte, y adora el yantra. Luego siéntate en un asiento rojo mirando al este y, con un rosario rojo, canta 12.000 veces la riddhi y el mantra para perfeccionar el mantra.","hi":"पवित्र होकर लाल रंग के वस्त्र पहनकर पूर्वाभिमुख मंगल कलश तथा उत्तराभिमुख यंत्र स्थापित कर यंत्र की पूजा करें। पश्चात् लाल आसन पर पूर्वाभिमुख बैठकर लाल रंग की माला से ऋद्धि मंत्र का बारह हजार बार जप करके मंत्र सिद्ध करना चाहिए।","pt":"Purifique-se, vista roupas vermelhas, coloque o pote auspicioso voltado para o leste e o yantra voltado para o norte, e adore o yantra. Depois sente-se em um assento vermelho voltado para o leste e, com um rosário vermelho, entoe o riddhi e o mantra 12.000 vezes para aperfeiçoar o mantra.","it":"Purificati, indossa abiti rossi, disponi il vaso benaugurale rivolto a est e lo yantra rivolto a nord, e adora lo yantra. Poi siediti su un sedile rosso rivolto a est e, con un rosario rosso, intona il riddhi e il mantra 12.000 volte per rendere perfetto il mantra.","gu":"શુદ્ધ થઈ, લાલ વસ્ત્રો પહેરી, પૂર્વ તરફ મંગળ કળશ અને ઉત્તર તરફ યંત્રની સ્થાપના કરી યંત્રની પૂજા કરો. પછી પૂર્વ તરફ મુખ રાખી લાલ આસન પર બેસી, લાલ માળા વડે મંત્ર સિદ્ધ કરવા માટે ઋદ્ધિ અને મંત્રનો 12,000 વાર જાપ કરો."},"benefit":{"en":"By keeping the yantra with you, and sprinkling water charged 21 times with the 40th verse, the riddhi and the mantra in all directions, the fear of fire goes away.","es":"Teniendo el yantra contigo y rociando en todas las direcciones agua cargada 21 veces con el verso 40, la riddhi y el mantra, desaparece el temor al fuego.","hi":"यंत्र को पास में रखने से तथा चालीसवें काव्य, ऋद्धि एवं मंत्र से इक्कीस बार जल मंत्र कर चारों ओर छिड़कने से अग्नि का भय दूर होता है।","pt":"Mantendo o yantra consigo e borrifando em todas as direções água carregada 21 vezes com o 40º verso, o riddhi e o mantra, o medo do fogo desaparece.","it":"Tenendo con te lo yantra e spruzzando in tutte le direzioni acqua caricata 21 volte con il 40º verso, il riddhi e il mantra, il timore del fuoco scompare.","gu":"યંત્ર પોતાની પાસે રાખી, 40મા શ્લોક, ઋદ્ધિ અને મંત્ર વડે 21 વાર અભિમંત્રિત કરેલું પાણી ચારે દિશામાં છાંટવાથી અગ્નિનો ભય દૂર થાય છે."}},{"n":41,"sa":["रक्तेक्षणं समद-कोकिल-कण्ठ-नीलं,","क्रोधोद्धतं फणिन-मुत्फण-मापतन्तम्।","आक्रामति क्रमयुगेण निरस्त-शंकस्-","त्वन्नाम-नाग-दमनी हृदि यस्य पुंसः।।४१।।"],"pron":["raktekṣaṇaṃ samada-kokila-kaṇṭha-nīlaṃ,","krodhoddhataṃ phaṇina-mutphaṇa-māpatantam|","ākrāmati kramayugeṇa nirasta-śaṃkas-","tvannāma-nāga-damanī hṛdi yasya puṃsaḥ||41||"],"title":{"en":"The serpent and courage","hi":"सर्प और साहस","es":"La serpiente y el valor","pt":"A serpente e a coragem","it":"Il serpente e il coraggio","gu":"સર્પ અને હિંમત"},"meaning":{"en":"A devotee who keeps the antidote of your name in the heart steps without fear past a red-eyed, rage-filled cobra, black as a cuckoo’s throat, rearing its hood.","hi":"जिसके हृदय में आपके नाम रूपी विष-नाशक औषधि है, वह लाल आँखों वाले, क्रोध से भरे, फन उठाए कोयल-कंठ-से काले नाग के सामने से भी निडर होकर निकल जाता है।","es":"Quien lleva en el corazón el antídoto de tu nombre pasa sin miedo ante una cobra de ojos rojos, llena de ira, negra como la garganta del cuco, con el capuchón alzado.","pt":"O devoto que guarda no coração o antídoto do teu nome passa sem medo por uma naja furiosa, de olhos vermelhos, negra como a garganta do cuco, com o capelo erguido.","it":"Il devoto che serba nel cuore l’antidoto del tuo nome passa senza paura accanto a un cobra furioso, dagli occhi rossi, nero come la gola del cuculo, con il cappuccio sollevato.","gu":"જે ભક્ત તમારા નામરૂપી વિષનાશક ઔષધને હૃદયમાં રાખે છે તે લાલ આંખોવાળા, ક્રોધથી ભરેલા, કોયલના કંઠ જેવા કાળા, ફેણ ઊંચી કરેલા નાગ પાસેથી પણ નિર્ભયપણે પસાર થાય છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो खीरसवीणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo khīrasavīṇaṃ"}],"mantra":[{"dev":"ॐ नमो श्रां श्रीं श्रूं श्रौं श्रः जलदेविकमले पद्महृद निवासिनी पद्मोपरि संस्थिते सिद्धिं देहि मनोवांछितं कुरु कुरु स्वाहा।","iast":"Oṃ namo śrāṃ śrīṃ śrūṃ śrauṃ śraḥ jaladevikamale padmahṛda nivāsinī padmopari saṃsthite siddhiṃ dehi manovāṃchitaṃ kuru kuru svāhā"},{"dev":"ॐ ह्रीं आदिदेवाय ह्रीं नमः।","iast":"Oṃ hrīṃ ādidevāya hrīṃ namaḥ"}],"method":{"en":"After bathing, wear white clothes, set up the yantra facing east and worship it. Light a lamp and perform the aarti. Then sit on a white seat facing north and, with a crystal rosary, practise the riddhi and the mantra 12,000 times to perfect the mantra.","es":"Después de bañarte, vístete de blanco, coloca el yantra mirando al este y adóralo. Enciende una lámpara y haz el aarti. Luego siéntate en un asiento blanco mirando al norte y, con un rosario de cristal, practica la riddhi y el mantra 12.000 veces para perfeccionar el mantra.","hi":"स्नान करके सफेद वस्त्र धारण कर पूर्वाभिमुख यंत्र स्थापित कर उसकी पूजा करें। दीपक जलावें आरती उतारें। पश्चात् सफेद आसन पर उत्तराभिमुख बैठकर स्फटिक मणि की माला द्वारा ऋद्धि, मंत्र का बारह हजार वार आराधन कर मंत्र सिद्ध करना चाहिए।","pt":"Depois do banho, vista roupas brancas, coloque o yantra voltado para o leste e adore-o. Acenda uma lamparina e realize o aarti. Depois sente-se em um assento branco voltado para o norte e, com um rosário de cristal, pratique o riddhi e o mantra 12.000 vezes para aperfeiçoar o mantra.","it":"Dopo il bagno, indossa abiti bianchi, disponi lo yantra rivolto a est e adoralo. Accendi una lampada ed esegui l’aarti. Poi siediti su un sedile bianco rivolto a nord e, con un rosario di cristallo, pratica il riddhi e il mantra 12.000 volte per rendere perfetto il mantra.","gu":"સ્નાન કરી સફેદ વસ્ત્રો પહેરો, પૂર્વ તરફ મુખ રાખી યંત્રની સ્થાપના કરી તેની પૂજા કરો. દીવો પ્રગટાવો અને આરતી કરો. પછી ઉત્તર તરફ મુખ રાખી સફેદ આસન પર બેસો અને સ્ફટિકની માળા વડે મંત્ર સિદ્ધ કરવા માટે ઋદ્ધિ અને મંત્રની 12,000 વાર સાધના કરો."},"benefit":{"en":"By keeping the yantra with you and repeatedly recalling the 41st verse, the riddhi and the mantra, honour is received in the royal court and standing increases; and by reciting this mantra over a snake-bite, the poison of a venomous snake is removed. Fill a bell-metal vessel with water, charge it 108 times with the mantra and give the charged water to drink: the effect of poison goes away.","es":"Teniendo el yantra contigo y recordando repetidamente el verso 41, la riddhi y el mantra, se recibe honor en la corte real y aumenta el prestigio; y recitando este mantra sobre una mordedura, se elimina el veneno de la serpiente venenosa. Llena una vasija de bronce con agua, cárgala 108 veces con el mantra y da a beber el agua cargada: el efecto del veneno desaparece.","hi":"यंत्र को पास में रखने से तथा इकतालीसवाँ काव्य, ऋद्धि तथा मंत्र का बार-बार स्मरण करने से राजदरबार में सम्मान मिलता है, प्रतिष्ठा बढ़ती है तथा इसी मंत्र के झाड़ने से विषधर का विष उतरता है। कांस्य पात्र में जल भरकर एक सौ आठ बार मंत्रित कर मंत्रित जल पिलाने से विष का प्रभाव दूर होता है।","pt":"Mantendo o yantra consigo e recordando repetidamente o 41º verso, o riddhi e o mantra, recebe-se honra na corte real e o prestígio aumenta; e, recitando este mantra sobre uma picada de cobra, remove-se o veneno de uma serpente venenosa. Encha uma vasilha de bronze com água, carregue-a 108 vezes com o mantra e dê a água carregada para beber: o efeito do veneno desaparece.","it":"Tenendo con te lo yantra e ricordando di continuo il 41º verso, il riddhi e il mantra, si riceve onore alla corte reale e il prestigio aumenta; e, recitando questo mantra su un morso di serpente, si rimuove il veleno di un serpente velenoso. Riempi un recipiente di bronzo con acqua, caricala 108 volte con il mantra e dai da bere l’acqua caricata: l’effetto del veleno scompare.","gu":"યંત્ર પોતાની પાસે રાખી, 41મો શ્લોક, ઋદ્ધિ અને મંત્રનું વારંવાર સ્મરણ કરવાથી રાજદરબારમાં માન મળે છે અને પ્રતિષ્ઠા વધે છે; અને સાપ કરડ્યા પર આ મંત્ર ભણવાથી ઝેરી સાપનું ઝેર ઊતરે છે. કાંસાના પાત્રમાં પાણી ભરી, મંત્ર વડે 108 વાર અભિમંત્રિત કરી તે પાણી પીવડાવો: ઝેરની અસર દૂર થાય છે."}},{"n":42,"sa":["वल्गत्तुरंग-गज-गर्जित-भीम-नाद-","माजौ बलं बलवतामपि भू-पतीनाम्।","उद्यद्-दिवाकर-मयूख-शिखा-पविद्धं,","त्वत्कीर्त्तनात्-तम इवाशु भिदा-मुपैति।।४२।।"],"pron":["valgatturaṃga-gaja-garjita-bhīma-nāda-","mājau balaṃ balavatāmapi bhū-patīnām|","udyad-divākara-mayūkha-śikhā-paviddhaṃ,","tvatkīrttanāt-tama ivāśu bhidā-mupaiti||42||"],"title":{"en":"Darkness before dawn","hi":"भोर से पहले का अंधकार","es":"Oscuridad antes del alba","pt":"Escuridão antes da aurora","it":"Il buio prima dell’alba","gu":"પ્રભાત પહેલાંનો અંધકાર"},"meaning":{"en":"Armies of mighty kings, with galloping horses and trumpeting elephants, fall back when your name is chanted, as darkness falls back before the rising sun.","hi":"आपके नाम-कीर्तन से घोड़ों की हिनहिनाहट और हाथियों की चिंघाड़ से गूँजती राजाओं की सेनाएँ पीछे हट जाती हैं, जैसे सूर्योदय पर अंधकार हट जाता है।","es":"Los ejércitos de reyes poderosos, con caballos al galope y elefantes que trompetean, retroceden cuando se canta tu nombre, como la oscuridad ante el sol naciente.","pt":"Os exércitos de reis poderosos, com cavalos a galope e elefantes trombeteando, recuam quando o teu nome é entoado, como a escuridão recua diante do sol nascente.","it":"Gli eserciti di re potenti, con cavalli al galoppo ed elefanti che barriscono, arretrano quando il tuo nome è intonato, come il buio arretra davanti al sole che sorge.","gu":"દોડતા ઘોડા અને ચિંઘાડતા હાથીઓવાળી બળવાન રાજાઓની સેનાઓ તમારું નામ લેવાથી પાછી હટી જાય છે, જેમ ઊગતા સૂર્ય આગળ અંધકાર હટી જાય છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो सप्पिसवीणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo sappisavīṇaṃ"}],"mantra":[{"dev":"ॐ नमो णमिऊण विषधर विष प्रणाशन रोग शोक दोष ग्रह कप्पदुमच्च जायई सुहनामग्रहण सकल सुहृदे ॐ नमः स्वाहा।","iast":"Oṃ namo ṇamiūṇa viṣadhara viṣa praṇāśana roga śoka doṣa graha kappadumacca jāyaī suhanāmagrahaṇa sakala suhṛde oṃ namaḥ svāhā"}],"method":{"en":"Become pure, wear white clothes, and set up the yantra, written with red sandalwood paste, facing east. Worship the yantra, light a lamp and perform the aarti. Then sit on a red seat facing north and, with a red rosary, chant the riddhi and the mantra 12,500 times and perfect the mantra.","es":"Purifícate, vístete de blanco y coloca el yantra, escrito con pasta de sándalo rojo, mirando al este. Adora el yantra, enciende una lámpara y haz el aarti. Luego siéntate en un asiento rojo mirando al norte y, con un rosario rojo, canta 12.500 veces la riddhi y el mantra y perfecciona el mantra.","hi":"पवित्र होकर धवल वस्त्र पहनकर रक्तचंदन से लिखे यंत्र को पूर्व दिशा की ओर स्थापित करें, यंत्र की पूजा करें, दीपक जलावें, आरती उतारें, पश्चात् रक्त आसन पर उत्तराभिमुख बैठकर लाल रंग की माला द्वारा बारह हजार पाँच सौ बार ऋद्धि मंत्र का जाप जपें तथा मंत्र सिद्ध करें।","pt":"Purifique-se, vista roupas brancas e coloque o yantra, escrito com pasta de sândalo vermelho, voltado para o leste. Adore o yantra, acenda uma lamparina e realize o aarti. Depois sente-se em um assento vermelho voltado para o norte e, com um rosário vermelho, entoe o riddhi e o mantra 12.500 vezes e aperfeiçoe o mantra.","it":"Purificati, indossa abiti bianchi e disponi lo yantra, scritto con pasta di sandalo rosso, rivolto a est. Adora lo yantra, accendi una lampada ed esegui l’aarti. Poi siediti su un sedile rosso rivolto a nord e, con un rosario rosso, intona il riddhi e il mantra 12.500 volte e rendi perfetto il mantra.","gu":"શુદ્ધ થઈ, સફેદ વસ્ત્રો પહેરી, રક્તચંદનની પેસ્ટથી લખેલા યંત્રની પૂર્વ તરફ સ્થાપના કરો. યંત્રની પૂજા કરો, દીવો પ્રગટાવો અને આરતી કરો. પછી ઉત્તર તરફ મુખ રાખી લાલ આસન પર બેસો અને લાલ માળા વડે ઋદ્ધિ અને મંત્રનો 12,500 વાર જાપ કરી મંત્ર સિદ્ધ કરો."},"benefit":{"en":"By tying the yantra on the upper arm and constantly recalling the riddhi and the mantra, fear does not arise even in a terrible battle. The king's anger is calmed and he turns his back and runs away. Fame spreads in all directions like the moonlight.","es":"Atando el yantra en el brazo y recordando constantemente la riddhi y el mantra, no surge el miedo ni siquiera en una batalla terrible. Se calma la ira del rey, que da la espalda y huye. La fama se extiende por todas partes como la luz de la luna.","hi":"यंत्र को भुजा में बाँधने तथा ऋद्धि मंत्र का स्मरण करते रहने से भयंकर युद्ध में भी भय उत्पन्न नहीं होता। राजा का क्रोध शान्त होता है और वह पीठ दिखाकर भाग जाता है। चन्द्रमा की चाँदनी सी कीर्ति चारों ओर फैलती है।","pt":"Amarrando o yantra no alto do braço e recordando constantemente o riddhi e o mantra, o medo não surge nem em uma batalha terrível. A ira do rei se acalma e ele dá as costas e foge. A fama se espalha em todas as direções como o luar.","it":"Legando lo yantra sulla parte alta del braccio e ricordando di continuo il riddhi e il mantra, la paura non sorge nemmeno in una battaglia terribile. L’ira del re si placa ed egli volta le spalle e fugge. La fama si diffonde in ogni direzione come il chiaro di luna.","gu":"યંત્રને બાવડા પર બાંધવાથી અને ઋદ્ધિ તથા મંત્રનું સતત સ્મરણ કરવાથી ભયંકર યુદ્ધમાં પણ ભય ઊપજતો નથી. રાજાનો ક્રોધ શાંત થાય છે અને તે પીઠ ફેરવીને ભાગી જાય છે. ચાંદનીની જેમ કીર્તિ ચારે દિશામાં ફેલાય છે."}},{"n":43,"sa":["कुन्ताग्र-भिन्न-गज-शोणित-वारिवाह-","वेगावतार-तरणातुर-योध-भीमे ।","युद्धे जयं विजित-दुर्जय-जेय-पक्षास्-","त्वत्-पाद-पंकज-वना-श्रयिणो लभन्ते।।४३।।"],"pron":["kuntāgra-bhinna-gaja-śoṇita-vārivāha-","vegāvatāra-taraṇātura-yodha-bhīme |","yuddhe jayaṃ vijita-durjaya-jeya-pakṣās-","tvat-pāda-paṃkaja-vanā-śrayiṇo labhante||43||"],"title":{"en":"Courage amid conflict","hi":"संघर्ष में साहस","es":"Valor en medio del conflicto","pt":"Coragem em meio ao conflito","it":"Coraggio in mezzo al conflitto","gu":"સંઘર્ષ વચ્ચે હિંમત"},"meaning":{"en":"In a fierce battle, where warriors eagerly wade through streams of blood from wounded elephants, the devotee who has taken shelter at your lotus feet wins a victory against even the unconquerable.","hi":"भीषण युद्ध में, जहाँ योद्धा घायल हाथियों के रक्त की धाराओं को पार करने को आतुर हैं, आपके चरण-कमलों की शरण लेने वाला अजेय शत्रुओं पर भी विजय पाता है।","es":"En una batalla feroz, donde los guerreros vadean ansiosos arroyos de sangre de elefantes heridos, quien se refugia en tus pies de loto alcanza la victoria incluso sobre lo invencible.","pt":"Em uma batalha feroz, onde os guerreiros avançam ansiosos por riachos de sangue de elefantes feridos, o devoto que se abrigou aos teus pés de lótus vence até o invencível.","it":"In una battaglia feroce, dove i guerrieri avanzano ansiosi tra torrenti di sangue di elefanti feriti, il devoto che ha preso rifugio ai tuoi piedi di loto riporta vittoria perfino sugli invincibili.","gu":"ઘાયલ હાથીઓના લોહીના પ્રવાહોમાં યોદ્ધાઓ ઉત્સાહથી ઊતરે તેવા ઘોર યુદ્ધમાં, તમારા ચરણકમળનું શરણ લેનાર ભક્ત અજેયને પણ જીતી લે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो महुरसवाणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo mahurasavāṇaṃ"}],"mantra":[{"dev":"ॐ नमो चक्रेश्वरी देवी चक्रधारिणी जिनशासन सेवाकारिणी क्षुद्रोपद्रव विनाशिनी धर्मशान्तिकारिणी नमः शान्तिं कुरु कुरु स्वाहा।","iast":"Oṃ namo cakreśvarī devī cakradhāriṇī jinaśāsana sevākāriṇī kṣudropadrava vināśinī dharmaśāntikāriṇī namaḥ śāntiṃ kuru kuru svāhā"}],"method":{"en":"After bathing, wear clean, pure white clothes, set up the yantra facing east and worship it. Then sit on a white seat facing north and, with a white rosary, practise the riddhi and the mantra 12,500 times and perfect the mantra.","es":"Después de bañarte, vístete con ropa blanca limpia y pura, coloca el yantra mirando al este y adóralo. Luego siéntate en un asiento blanco mirando al norte y, con un rosario blanco, practica la riddhi y el mantra 12.500 veces y perfecciona el mantra.","hi":"स्नान करके शुद्ध स्वच्छ सफेद वस्त्र धारण कर पूर्व दिशा की ओर यंत्र स्थापित कर यंत्र की पूजा करना चाहिए पश्चात् उत्तराभिमुख सफेद आसन पर बैठकर सफेद माला द्वारा बारह हजार पाँच सौ बार ऋद्धि मंत्र का आराधन कर मंत्र सिद्ध करें।","pt":"Depois do banho, vista roupas brancas, limpas e puras, coloque o yantra voltado para o leste e adore-o. Depois sente-se em um assento branco voltado para o norte e, com um rosário branco, pratique o riddhi e o mantra 12.500 vezes e aperfeiçoe o mantra.","it":"Dopo il bagno, indossa abiti bianchi, puliti e puri, disponi lo yantra rivolto a est e adoralo. Poi siediti su un sedile bianco rivolto a nord e, con un rosario bianco, pratica il riddhi e il mantra 12.500 volte e rendi perfetto il mantra.","gu":"સ્નાન કરી સ્વચ્છ, શુદ્ધ સફેદ વસ્ત્રો પહેરો, પૂર્વ તરફ મુખ રાખી યંત્રની સ્થાપના કરી તેની પૂજા કરો. પછી ઉત્તર તરફ મુખ રાખી સફેદ આસન પર બેસો અને સફેદ માળા વડે ઋદ્ધિ અને મંત્રની 12,500 વાર સાધના કરી મંત્ર સિદ્ધ કરો."},"benefit":{"en":"By recalling the 43rd verse, the riddhi and the mantra, worshipping the yantra and keeping it with you, all kinds of fear go away. In battle the blows of weapons do not strike, and wealth is gained through the king.","es":"Recordando el verso 43, la riddhi y el mantra, adorando el yantra y teniéndolo contigo, desaparecen todas las clases de miedo. En la batalla no alcanzan los golpes de las armas, y se obtiene riqueza por medio del rey.","hi":"तेंतालीसवाँ काव्य, ऋद्धि, मंत्र को स्मरण करने और यंत्र की पूजा करने एवं उसे पास में रखने से सब प्रकार के भय दूर होते हैं। संग्राम में अस्त्र शस्त्रों की चोटें नहीं लगतीं तथा राजा द्वारा धन लाभ होता है।","pt":"Recordando o 43º verso, o riddhi e o mantra, adorando o yantra e mantendo-o consigo, todo tipo de medo desaparece. Na batalha os golpes das armas não atingem, e ganha-se riqueza por meio do rei.","it":"Ricordando il 43º verso, il riddhi e il mantra, adorando lo yantra e tenendolo con sé, ogni genere di paura scompare. In battaglia i colpi delle armi non raggiungono, e si ottiene ricchezza tramite il re.","gu":"43મો શ્લોક, ઋદ્ધિ અને મંત્ર યાદ કરવાથી, યંત્રની પૂજા કરવાથી અને તેને પોતાની પાસે રાખવાથી દરેક પ્રકારનો ભય દૂર થાય છે. યુદ્ધમાં શસ્ત્રોના પ્રહાર વાગતા નથી, અને રાજા દ્વારા ધન પ્રાપ્ત થાય છે."}},{"n":44,"sa":["अम्भो-निधौ क्षुभित-भीषण-नक्र-चक्र-","पाठीन-पीठ-भय-दोल्वण-वाडवाग्नौ।","रंगत्तरंग-शिखर-स्थित-यान-पात्रास्-","त्रासं विहाय भवतः स्मरणाद्-व्रजन्ति।।४४।।"],"pron":["ambho-nidhau kṣubhita-bhīṣaṇa-nakra-cakra-","pāṭhīna-pīṭha-bhaya-dolvaṇa-vāḍavāgnau|","raṃgattaraṃga-śikhara-sthita-yāna-pātrās-","trāsaṃ vihāya bhavataḥ smaraṇād-vrajanti||44||"],"title":{"en":"Across the stormy sea","hi":"तूफ़ानी सागर के पार","es":"A través del mar tormentoso","pt":"Através do mar tempestuoso","it":"Attraverso il mare in tempesta","gu":"તોફાની સાગર પાર"},"meaning":{"en":"Those aboard a ship tossed by giant waves, crocodiles and sea monsters, and even by the fire beneath the sea, reach the shore safely by remembering you.","hi":"विशाल लहरों, मगरमच्छों और समुद्री जीवों, यहाँ तक कि बड़वाग्नि से घिरे जहाज़ पर सवार लोग आपका स्मरण करके सुरक्षित तट पर पहुँच जाते हैं।","es":"Quienes viajan en un barco sacudido por olas gigantes, cocodrilos y monstruos marinos, e incluso por el fuego bajo el mar, llegan sanos a la orilla al recordarte.","pt":"Quem está a bordo de um navio sacudido por ondas gigantes, crocodilos e monstros marinhos, e até pelo fogo sob o mar, chega são e salvo à praia ao se lembrar de ti.","it":"Chi è a bordo di una nave sballottata da onde gigantesche, coccodrilli e mostri marini, e persino dal fuoco sotto il mare, raggiunge sano e salvo la riva ricordandosi di te.","gu":"વિશાળ મોજાં, મગરો અને દરિયાઈ રાક્ષસો, અને સમુદ્ર નીચેના અગ્નિથી પણ હચમચી જતા જહાજમાં બેઠેલા લોકો તમારું સ્મરણ કરવાથી સલામત રીતે કિનારે પહોંચે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो अमियसवीणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo amiyasavīṇaṃ"}],"mantra":[{"dev":"ॐ नमो रावणाय विभीषणाय कुम्भकरणाय लंकाधिपतये महाबल पराक्रमाय मनश्चिन्तितं कुरु कुरु स्वाहा।","iast":"Oṃ namo rāvaṇāya vibhīṣaṇāya kumbhakaraṇāya laṃkādhipataye mahābala parākramāya manaścintitaṃ kuru kuru svāhā"}],"method":{"en":"After bathing, wear clean white clothes, face north and set up the yantra, and worship it. Place an auspicious pot, light a lamp and perform the aarti. Then sit on a white seat and, with a crystal rosary, practise the riddhi and the mantra 1,008 times to perfect the mantra.","es":"Después de bañarte, vístete con ropa blanca limpia, mira al norte, coloca el yantra y adóralo. Pon un cántaro auspicioso, enciende una lámpara y haz el aarti. Luego siéntate en un asiento blanco y, con un rosario de cristal, practica la riddhi y el mantra 1.008 veces para perfeccionar el mantra.","hi":"स्नान के बाद सफेद स्वच्छ वस्त्र धारण कर उत्तर दिशा की ओर मुख करके यंत्र स्थापित कर यंत्र की पूजा करें, मंगल कलश रखें, दीपक जलावें, आरती उतारें पश्चात् धवलासन पर बैठकर स्फटिक मणि की माला द्वारा एक हजार आठ बार ऋद्धि मंत्र का आराधन कर मंत्र सिद्ध करना चाहिए।","pt":"Depois do banho, vista roupas brancas e limpas, volte-se para o norte, coloque o yantra e adore-o. Disponha um pote auspicioso, acenda uma lamparina e realize o aarti. Depois sente-se em um assento branco e, com um rosário de cristal, pratique o riddhi e o mantra 1.008 vezes para aperfeiçoar o mantra.","it":"Dopo il bagno, indossa abiti bianchi e puliti, rivolgiti a nord, disponi lo yantra e adoralo. Colloca un vaso benaugurale, accendi una lampada ed esegui l’aarti. Poi siediti su un sedile bianco e, con un rosario di cristallo, pratica il riddhi e il mantra 1.008 volte per rendere perfetto il mantra.","gu":"સ્નાન કરી સ્વચ્છ સફેદ વસ્ત્રો પહેરો, ઉત્તર તરફ મુખ રાખી યંત્રની સ્થાપના કરી તેની પૂજા કરો. મંગળ કળશ મૂકો, દીવો પ્રગટાવો અને આરતી કરો. પછી સફેદ આસન પર બેસી, સ્ફટિકની માળા વડે મંત્ર સિદ્ધ કરવા માટે ઋદ્ધિ અને મંત્રની 1,008 વાર સાધના કરો."},"benefit":{"en":"By practising the 44th verse, the riddhi and the mantra, and keeping the yantra with you, calamities are removed. There is no fear of storms at sea. The sea is crossed with ease.","es":"Practicando el verso 44, la riddhi y el mantra, y teniendo el yantra contigo, se alejan las calamidades. No hay temor a las tormentas en el mar. El mar se cruza con facilidad.","hi":"चवालीसवाँ काव्य, ऋद्धि तथा मंत्र की आराधना से तथा यंत्र को अपने पास रखने से आपत्तियाँ दूर होती हैं। समुद्र में तूफान का भय नहीं होता। आसानी से समुद्र पार कर लिया जाता है।","pt":"Praticando o 44º verso, o riddhi e o mantra, e mantendo o yantra consigo, as calamidades são removidas. Não há medo de tempestades no mar. O mar é atravessado com facilidade.","it":"Praticando il 44º verso, il riddhi e il mantra, e tenendo con te lo yantra, le calamità vengono rimosse. Non c’è timore delle tempeste in mare. Il mare si attraversa con facilità.","gu":"44મો શ્લોક, ઋદ્ધિ અને મંત્રની સાધના કરવાથી અને યંત્ર પોતાની પાસે રાખવાથી આફતો દૂર થાય છે. સમુદ્રમાં તોફાનનો ભય રહેતો નથી. સમુદ્ર સહેલાઈથી પાર થાય છે."}},{"n":45,"sa":["उद्भूतभीषणजलोदरभारभुग्नाः","शोच्यां दशा-मुपगताश्च्युत-जीविताशाः।","त्वत्पाद-पंकज-रजोऽमृतदिग्ध-देहाः,","मर्त्या भवन्ति मकर-ध्वज-तुल्य-रूपाः।।४५।।"],"pron":["udbhūtabhīṣaṇajalodarabhārabhugnāḥ","śocyāṃ daśā-mupagatāścyuta-jīvitāśāḥ|","tvatpāda-paṃkaja-rajo’mṛtadigdha-dehāḥ,","martyā bhavanti makara-dhvaja-tulya-rūpāḥ||45||"],"title":{"en":"Hope in suffering","hi":"पीड़ा में आशा","es":"Esperanza en el sufrimiento","pt":"Esperança no sofrimento","it":"Speranza nella sofferenza","gu":"પીડામાં આશા"},"meaning":{"en":"People bowed down by terrible illness, almost without hope of recovery or even of life, become well and radiant again when they anoint themselves with the nectar-like dust of your lotus feet.","hi":"भीषण रोग से झुके, स्वस्थ होने या जीवित रहने की भी लगभग आशा खो चुके लोग आपके चरण-कमलों की अमृत-सम रज लगाकर पुनः स्वस्थ और कांतिमान हो जाते हैं।","es":"Las personas abatidas por una enfermedad terrible, casi sin esperanza de recuperarse o siquiera de vivir, vuelven a estar sanas y radiantes al ungirse con el polvo, como néctar, de tus pies de loto.","pt":"Pessoas curvadas por uma doença terrível, quase sem esperança de cura ou mesmo de vida, ficam bem e radiantes de novo quando se ungem com o pó de néctar dos teus pés de lótus.","it":"Le persone piegate da una malattia terribile, quasi senza speranza di guarigione o perfino di vita, tornano sane e radiose quando si ungono con la polvere simile a nettare dei tuoi piedi di loto.","gu":"ભયંકર રોગથી વળી ગયેલા, સાજા થવાની કે જીવવાની પણ લગભગ આશા ગુમાવી બેઠેલા લોકો તમારા ચરણકમળની અમૃત જેવી રજ શરીરે લગાવવાથી ફરી સ્વસ્થ અને તેજસ્વી બને છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो अक्खीणमहाणसाणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo akkhīṇamahāṇasāṇaṃ"}],"mantra":[{"dev":"ॐ नमो भगवती क्षुद्रोपद्रव शान्तिकारिणी रोगकष्ट ज्वरोपशमनं शान्तिं कुरु कुरु स्वाहा।","iast":"Oṃ namo bhagavatī kṣudropadrava śāntikāriṇī rogakaṣṭa jvaropaśamanaṃ śāntiṃ kuru kuru svāhā"},{"dev":"ॐ ह्रीं भगवते भयभीषणहराय नमः।","iast":"Oṃ hrīṃ bhagavate bhayabhīṣaṇaharāya namaḥ"}],"method":{"en":"Become pure, wear yellow clothes, face south and set up the yantra and worship it. Then sit on a yellow seat and, with a yellow rosary, recall the riddhi and the mantra 1,008 times to perfect the mantra.","es":"Purifícate, vístete de amarillo, mira al sur, coloca el yantra y adóralo. Luego siéntate en un asiento amarillo y, con un rosario amarillo, recuerda 1.008 veces la riddhi y el mantra para perfeccionar el mantra.","hi":"पवित्र होकर पीले रंग के वस्त्र पहनकर दक्षिण दिशा की ओर यंत्र स्थापित कर यंत्र की पूजा करें पश्चात् पीले आसन पर बैठकर पीले रंग की माला द्वारा एक हजार आठ बार ऋद्धि मंत्र का स्मरण कर मंत्र सिद्ध करना चाहिए।","pt":"Purifique-se, vista roupas amarelas, volte-se para o sul, coloque o yantra e adore-o. Depois sente-se em um assento amarelo e, com um rosário amarelo, recorde o riddhi e o mantra 1.008 vezes para aperfeiçoar o mantra.","it":"Purificati, indossa abiti gialli, rivolgiti a sud, disponi lo yantra e adoralo. Poi siediti su un sedile giallo e, con un rosario giallo, ricorda il riddhi e il mantra 1.008 volte per rendere perfetto il mantra.","gu":"શુદ્ધ થઈ, પીળાં વસ્ત્રો પહેરી, દક્ષિણ તરફ મુખ રાખી યંત્રની સ્થાપના કરી તેની પૂજા કરો. પછી પીળા આસન પર બેસી, પીળી માળા વડે મંત્ર સિદ્ધ કરવા માટે ઋદ્ધિ અને મંત્ર 1,008 વાર યાદ કરો."},"benefit":{"en":"By chanting the 45th verse, the riddhi and the mantra, keeping the yantra with you and worshipping it in the three daily periods, the pain of many kinds of illness is calmed; and great mortal fear, dropsy (jalodar), fistula (bhagandar), advanced leprosy and the like are calmed, and calamities (upsarg) go away.","es":"Recitando el verso 45, la riddhi y el mantra, teniendo el yantra contigo y adorándolo en los tres momentos del día, se calma el dolor de muchas clases de enfermedades; y se calman el gran temor a la muerte, la hidropesía (jalodar), la fístula (bhagandar), la lepra avanzada y males semejantes, y desaparecen las calamidades (upsarg).","hi":"पैंतालीसवाँ काव्य, ऋद्धि तथा मंत्र जपने और यंत्र को पास में रखने से तथा उसकी त्रिकाल पूजा करने से अनेक प्रकार की व्याधियों की पीड़ा शान्त होती है और महाभयानक मरण भय जलोदर भगन्दर गलित कोढ़ आदि शान्त होते हैं तथा उपसर्ग दूर होते हैं।","pt":"Entoando o 45º verso, o riddhi e o mantra, mantendo o yantra consigo e adorando-o nos três períodos do dia, a dor de muitos tipos de doença se acalma; e o grande medo da morte, a hidropisia (jalodar), a fístula (bhagandar), a lepra avançada e semelhantes se acalmam, e as calamidades (upsarg) desaparecem.","it":"Intonando il 45º verso, il riddhi e il mantra, tenendo con te lo yantra e adorandolo nei tre momenti del giorno, il dolore di molti tipi di malattia si calma; e il grande timore della morte, l’idropisia (jalodar), la fistola (bhagandar), la lebbra avanzata e simili si placano, e le calamità (upsarg) scompaiono.","gu":"45મો શ્લોક, ઋદ્ધિ અને મંત્રનો જાપ કરવાથી, યંત્ર પોતાની પાસે રાખી દિવસના ત્રણે સમયે તેની પૂજા કરવાથી ઘણા પ્રકારના રોગોની પીડા શાંત થાય છે; અને મૃત્યુનો મહાભય, જળોદર, ભગંદર, કોઢ (કુષ્ઠ) જેવા રોગો શાંત થાય છે, અને ઉપસર્ગ દૂર થાય છે."}},{"n":46,"sa":["आपाद-कण्ठ-मुरुश्रृंखल-वेष्टितांगा,","गाढं बृहन्निगड-कोटि-निघृष्ट-जंघाः।","त्वन्नाममन्त्रमनिशं मनुजाः स्मरन्तः","सद्यः स्वयं विगत-बन्ध-भया भवन्ति।।४६।।"],"pron":["āpāda-kaṇṭha-muruśrṛṃkhala-veṣṭitāṃgā,","gāḍhaṃ bṛhannigaḍa-koṭi-nighṛṣṭa-jaṃghāḥ|","tvannāmamantramaniśaṃ manujāḥ smarantaḥ","sadyaḥ svayaṃ vigata-bandha-bhayā bhavanti||46||"],"title":{"en":"Freedom from chains","hi":"बंधनों से मुक्ति","es":"Libres de cadenas","pt":"Livre das correntes","it":"Liberi dalle catene","gu":"બેડીઓમાંથી મુક્તિ"},"meaning":{"en":"Even those shackled from foot to neck in heavy chains, bruised and bound, are freed in an instant from bondage and fear by meditating on your name as a mantra.","hi":"पैर से कंठ तक भारी जंजीरों में जकड़े, घायल और बँधे लोग भी आपके नाम को मंत्र रूप में निरंतर स्मरण करने से क्षण भर में बंधन और भय से मुक्त हो जाते हैं।","es":"Incluso quienes están encadenados de los pies al cuello con pesadas cadenas, magullados y atados, se liberan al instante del cautiverio y del miedo al meditar tu nombre como un mantra.","pt":"Até aqueles acorrentados dos pés ao pescoço por pesadas correntes, feridos e atados, são libertados num instante da prisão e do medo ao meditar sobre o teu nome como um mantra.","it":"Anche chi è incatenato dai piedi al collo con pesanti catene, piagato e legato, viene liberato in un istante dalla schiavitù e dalla paura meditando sul tuo nome come mantra.","gu":"પગથી ગળા સુધી ભારે સાંકળોથી જકડાયેલા, ઘાયલ અને બંધાયેલા લોકો પણ તમારા નામનું મંત્રરૂપે ધ્યાન કરવાથી ક્ષણમાં બંધન અને ભયથી મુક્ત થાય છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो वड्ढमाणाणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo vaḍḍhamāṇāṇaṃ"}],"mantra":[{"dev":"ॐ नमो ह्रां ह्रीं श्रीं ह्रूं ह्रौं ह्रः ठः ठः जः जः क्षां क्षीं क्षूं क्षः क्षयः स्वाहा।","iast":"Oṃ namo hrāṃ hrīṃ śrīṃ hrūṃ hrauṃ hraḥ ṭhaḥ ṭhaḥ jaḥ jaḥ kṣāṃ kṣīṃ kṣūṃ kṣaḥ kṣayaḥ svāhā"}],"method":{"en":"After bathing, wear yellow clothes, face east, set up the yantra and worship it with yellow flowers. Set up the auspicious pot, light a lamp and perform the aarti. Then sit on a yellow seat and, with a yellow rosary, complete 12,000 repetitions of the riddhi and the mantra, and the mantra will be perfected.","es":"Después de bañarte, vístete de amarillo, mira al este, coloca el yantra y adóralo con flores amarillas. Pon el cántaro auspicioso, enciende una lámpara y haz el aarti. Luego siéntate en un asiento amarillo y, con un rosario amarillo, completa 12.000 repeticiones de la riddhi y el mantra, y el mantra quedará perfeccionado.","hi":"स्नान के बाद पीले रंग के वस्त्र पहनकर पूर्व दिशा की ओर मुख करके यंत्र स्थापित कर पीले फूलों से यंत्र की पूजा करना चाहिए। मंगलकलश की स्थापना कर दीपक जलाकर आरती करें पश्चात् पीले आसन पर बैठकर पीली माला द्वारा ऋद्धि मंत्र का बारह हजार बार जप पूरा करें तो मंत्र सिद्ध होगा।","pt":"Depois do banho, vista roupas amarelas, volte-se para o leste, coloque o yantra e adore-o com flores amarelas. Disponha o pote auspicioso, acenda uma lamparina e realize o aarti. Depois sente-se em um assento amarelo e, com um rosário amarelo, complete 12.000 repetições do riddhi e do mantra, e o mantra será aperfeiçoado.","it":"Dopo il bagno, indossa abiti gialli, rivolgiti a est, disponi lo yantra e adoralo con fiori gialli. Disponi il vaso benaugurale, accendi una lampada ed esegui l’aarti. Poi siediti su un sedile giallo e, con un rosario giallo, completa 12.000 ripetizioni del riddhi e del mantra, e il mantra sarà reso perfetto.","gu":"સ્નાન કરી પીળાં વસ્ત્રો પહેરો, પૂર્વ તરફ મુખ રાખી યંત્રની સ્થાપના કરી પીળાં ફૂલોથી તેની પૂજા કરો. મંગળ કળશની સ્થાપના કરો, દીવો પ્રગટાવો અને આરતી કરો. પછી પીળા આસન પર બેસી, પીળી માળા વડે ઋદ્ધિ અને મંત્રના 12,000 જાપ પૂરા કરો, અને મંત્ર સિદ્ધ થશે."},"benefit":{"en":"When trouble comes, by continually chanting the 46th verse, the riddhi and the mantra, keeping the yantra with you and worshipping it in the three daily periods, the body of one bound with iron chains in prison is set free and released from captivity. There is no fear of the king and the like.","es":"Cuando llega la dificultad, cantando continuamente el verso 46, la riddhi y el mantra, teniendo el yantra contigo y adorándolo en los tres momentos del día, el cuerpo de quien está atado con cadenas de hierro en la cárcel queda liberado y sale del cautiverio. No hay temor al rey ni a poderes semejantes.","hi":"संकट आने पर निरन्तर छियालीसवाँ काव्य ऋद्धि तथा मंत्र को जपने और यंत्र को पास में रखने तथा उसकी त्रिकाल पूजा करने से कारागार में लौह श्रृंखलाओं से बंधा हुआ शरीर बन्धन मुक्त हो जाता है और कैद से छुटकारा होता है। राजा आदि का भय नहीं रहता।","pt":"Quando a dificuldade chega, entoando continuamente o 46º verso, o riddhi e o mantra, mantendo o yantra consigo e adorando-o nos três períodos do dia, o corpo de quem está preso com correntes de ferro na prisão é libertado e solto do cativeiro. Não há medo do rei e de autoridades semelhantes.","it":"Quando arriva la difficoltà, intonando di continuo il 46º verso, il riddhi e il mantra, tenendo con te lo yantra e adorandolo nei tre momenti del giorno, il corpo di chi è legato con catene di ferro in prigione viene liberato e sciolto dalla prigionia. Non c’è timore del re e di autorità simili.","gu":"સંકટ આવે ત્યારે 46મો શ્લોક, ઋદ્ધિ અને મંત્રનો સતત જાપ કરવાથી, યંત્ર પોતાની પાસે રાખી દિવસના ત્રણે સમયે તેની પૂજા કરવાથી, જેલમાં લોખંડની સાંકળોથી બંધાયેલા વ્યક્તિનું શરીર મુક્ત થાય છે અને કેદમાંથી છૂટે છે. રાજા અને તેના જેવા સત્તાધીશોનો ભય રહેતો નથી."}},{"n":47,"sa":["मत्त-द्विपेन्द्र-मृगराज-दवानलाहि-","संग्राम-वारिधि-महोदर-बन्धनोत्थम्।","तस्याशु नाश-मुपयाति भयं भियेव,","यस्तावकं स्तव-मिमं मतिमान-धीते।।४७।।"],"pron":["matta-dvipendra-mṛgarāja-davānalāhi-","saṃgrāma-vāridhi-mahodara-bandhanottham|","tasyāśu nāśa-mupayāti bhayaṃ bhiyeva,","yastāvakaṃ stava-mimaṃ matimāna-dhīte||47||"],"title":{"en":"Gathering the fears","hi":"सब भयों का संग्रह","es":"Reunir los miedos","pt":"Reunindo os medos","it":"Raccogliere le paure","gu":"ભયોનો સમૂહ"},"meaning":{"en":"The wise person who recites this hymn with devotion finds the fears of raging elephants, lions, forest fires, serpents, war, stormy seas, disease and bondage grow small; fear itself is afraid of such a person.","hi":"जो विवेकी व्यक्ति भक्ति से इस स्तोत्र का पाठ करता है, उसके लिए मदमस्त हाथी, सिंह, दावानल, सर्प, युद्ध, तूफ़ानी समुद्र, रोग और बंधन के भय क्षीण हो जाते हैं; भय स्वयं ही उससे डरने लगता है।","es":"A quien recita este himno con devoción, los temores a elefantes enfurecidos, leones, incendios del bosque, serpientes, guerra, mares tormentosos, enfermedad y cautiverio se le hacen pequeños; hasta el miedo le tiene miedo.","pt":"A pessoa sábia que recita este hino com devoção vê diminuírem os medos de elefantes furiosos, leões, incêndios na floresta, serpentes, guerra, mares tempestuosos, doença e prisão; o próprio medo tem medo dessa pessoa.","it":"La persona saggia che recita questo inno con devozione vede rimpicciolirsi le paure di elefanti infuriati, leoni, incendi nella foresta, serpenti, guerra, mari in tempesta, malattia e prigionia; la paura stessa ha paura di quella persona.","gu":"જે જ્ઞાની પુરુષ ભક્તિપૂર્વક આ સ્તોત્ર પઢે છે, તેના માટે મદોન્મત્ત હાથી, સિંહ, દાવાનળ, સર્પ, યુદ્ધ, તોફાની સમુદ્ર, રોગ અને બંધનના ભય નાના થઈ જાય છે; ભય પોતે પણ તેનાથી ડરે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो सव्व सिद्धायदणाणं वड्ढमाणाणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo savva siddhāyadaṇāṇaṃ vaḍḍhamāṇāṇaṃ"}],"mantra":[{"dev":"ॐ नमो ह्रां ह्रीं ह्रूं ह्रः य क्ष श्रीं ह्रीं फट् स्वाहा।","iast":"Oṃ namo hrāṃ hrīṃ hrūṃ hraḥ ya kṣa śrīṃ hrīṃ phaṭ svāhā"}],"method":{"en":"After bathing, wear pure clothes, face north and set up the yantra, and worship it with offerings. Then sit on a white seat facing east and, with a white rosary, practise the riddhi and the mantra 9,000 times to perfect the mantra.","es":"Después de bañarte, ponte ropa pura, mira al norte, coloca el yantra y adóralo con ofrendas. Luego siéntate en un asiento blanco mirando al este y, con un rosario blanco, practica la riddhi y el mantra 9.000 veces para perfeccionar el mantra.","hi":"स्नान करके शुद्ध वस्त्र पहनकर उत्तरदिशा की ओर मुख करके यंत्र स्थापित कर उसकी पूजा अर्चना करना चाहिए। पश्चात् धवल आसन पर पूर्व दिशा की ओर मुख करके बैठकर सफेद माला द्वारा नौ हजार बार ऋद्धि मंत्र का आराधन कर मंत्र सिद्ध करना चाहिए।","pt":"Depois do banho, vista roupas puras, volte-se para o norte, coloque o yantra e adore-o com oferendas. Depois sente-se em um assento branco voltado para o leste e, com um rosário branco, pratique o riddhi e o mantra 9.000 vezes para aperfeiçoar o mantra.","it":"Dopo il bagno, indossa abiti puri, rivolgiti a nord, disponi lo yantra e adoralo con offerte. Poi siediti su un sedile bianco rivolto a est e, con un rosario bianco, pratica il riddhi e il mantra 9.000 volte per rendere perfetto il mantra.","gu":"સ્નાન કરી શુદ્ધ વસ્ત્રો પહેરો, ઉત્તર તરફ મુખ રાખી યંત્રની સ્થાપના કરી નૈવેદ્ય સાથે તેની પૂજા કરો. પછી પૂર્વ તરફ મુખ રાખી સફેદ આસન પર બેસો અને સફેદ માળા વડે મંત્ર સિદ્ધ કરવા માટે ઋદ્ધિ અને મંત્રની 9,000 વાર સાધના કરો."},"benefit":{"en":"By keeping the yantra with you, and after anointing the yantra (abhishek), recalling the 47th verse, the riddhi and the mantra 108 times with pure feelings: the one who marches against an opposing enemy receives the goddess of victory, the enemy is destroyed and all his weapons become blunt; wounds from bullets, spears and the like do not occur. Besides this, deliverance comes from a rutting elephant, a lion, a forest fire, a terrible snake, a storm at sea, a great illness and many kinds of bonds.","es":"Teniendo el yantra contigo y, tras ungir el yantra (abhishek), recordando 108 veces con sentimientos puros el verso 47, la riddhi y el mantra: quien marcha contra un enemigo adverso recibe a la diosa de la victoria, el enemigo es destruido y todas sus armas se embotan; no ocurren heridas de bala, de lanza y semejantes. Además, se logra la liberación de un elefante enloquecido, de un león, de un incendio forestal, de una serpiente terrible, de una tormenta en el mar, de una gran enfermedad y de muchas clases de ataduras.","hi":"यंत्र को पास में रखने व यंत्र का अभिषेक कर सैंतालीसवाँ काव्य ऋद्धि तथा मंत्र का एक सौ आठ बार पवित्र भावों के साथ स्मरण करने से विपक्षी शत्रु पर चढ़ाई करने वाले को विजयलक्ष्मी प्राप्त होती है शत्रु का नाश होता है और उसके सभी हथियार मोथरे हो जाते हैं बन्दूक की गोली वरछी आदि के घाव नहीं होते। इसके अतिरिक्त मदोन्मत्त हस्ती, सिंह, दावानल, भयंकर सर्प समुद्री तूफान महान रोग तथा अनेक तरह के बन्धनों से छुटकारा हो जाता है।","pt":"Mantendo o yantra consigo e, depois de ungir o yantra (abhishek), recordando o 47º verso, o riddhi e o mantra 108 vezes com sentimentos puros: quem marcha contra um inimigo adversário recebe a deusa da vitória, o inimigo é destruído e todas as suas armas se tornam cegas; não ocorrem ferimentos de balas, lanças e semelhantes. Além disso, vem a libertação de um elefante no cio, de um leão, de um incêndio florestal, de uma serpente terrível, de uma tempestade no mar, de uma grande doença e de muitos tipos de prisão.","it":"Tenendo con te lo yantra e, dopo aver unto lo yantra (abhishek), ricordando il 47º verso, il riddhi e il mantra 108 volte con sentimenti puri: chi marcia contro un nemico avversario riceve la dea della vittoria, il nemico viene distrutto e tutte le sue armi si spuntano; non si verificano ferite da pallottole, lance e simili. Inoltre arriva la liberazione da un elefante in calore, da un leone, da un incendio nella foresta, da un serpente terribile, da una tempesta in mare, da una grave malattia e da molti tipi di prigionia.","gu":"યંત્ર પોતાની પાસે રાખી, યંત્રનો અભિષેક કર્યા પછી શુદ્ધ ભાવથી 47મો શ્લોક, ઋદ્ધિ અને મંત્ર 108 વાર યાદ કરવાથી: સામે શત્રુ પર ચઢાઈ કરનારને વિજયલક્ષ્મી પ્રાપ્ત થાય છે, શત્રુનો નાશ થાય છે અને તેનાં બધાં શસ્ત્રો બુઠ્ઠાં થઈ જાય છે; ગોળી, ભાલા જેવા ઘા થતા નથી. વળી, મદોન્મત્ત હાથી, સિંહ, દાવાનળ, ભયંકર સર્પ, સમુદ્રનું તોફાન, મોટા રોગ અને અનેક પ્રકારનાં બંધનોમાંથી છુટકારો મળે છે."}},{"n":48,"sa":["स्तोत्र-स्रजं तव जिनेन्द्र गुणैर्-निबद्धां","भक्त्या मया विविध-वर्ण-विचित्र-पुष्पां।","धत्ते जनो य इह कण्ठ-गतामजस्रं-","तं मानतुंगमवशा समुपैति लक्ष्मीः।।४८।।"],"pron":["stotra-srajaṃ tava jinendra guṇair-nibaddhāṃ","bhaktyā mayā vividha-varṇa-vicitra-puṣpāṃ|","dhatte jano ya iha kaṇṭha-gatāmajasraṃ-","taṃ mānatuṃgamavaśā samupaiti lakṣmīḥ||48||"],"title":{"en":"A garland of devotion","hi":"भक्ति की माला","es":"Una guirnalda de devoción","pt":"Uma guirlanda de devoção","it":"Una ghirlanda di devozione","gu":"ભક્તિની માળા"},"meaning":{"en":"I, Manatunga, have woven this garland of praise from your virtues, with flowers of many colours and a heart of devotion. Whoever wears it close, reciting it without pause, wins the grace of liberation.","hi":"हे जिनेन्द्र! मैं मानतुंग ने आपके गुणों से, भक्ति और विविध रंगों के पुष्पों से यह स्तुति-माला गूँथी है। जो इसे निरंतर कंठ में धारण करता है, उसे मोक्ष-लक्ष्मी प्राप्त होती है।","es":"Yo, Manatunga, he tejido esta guirnalda de alabanza con tus virtudes, con flores de muchos colores y un corazón devoto. Quien la lleva cerca, recitándola sin pausa, alcanza la gracia de la liberación.","pt":"Eu, Manatunga, teci esta guirlanda de louvor com as tuas virtudes, com flores de muitas cores e um coração de devoção. Quem a usar junto ao peito, recitando-a sem pausa, conquista a graça da libertação.","it":"Io, Manatunga, ho intrecciato questa ghirlanda di lode con le tue virtù, con fiori di molti colori e un cuore di devozione. Chiunque la porti vicino al cuore, recitandola senza pausa, ottiene la grazia della liberazione.","gu":"હું માનતુંગ, તમારા ગુણોથી, અનેક રંગોનાં ફૂલોથી અને ભક્તિભર્યા હૃદયથી આ સ્તુતિની માળા ગૂંથું છું. જે તેને કંઠે ધારણ કરે છે અને અટક્યા વિના પઢે છે, તે મુક્તિની કૃપા પામે છે."},"riddhi":[{"dev":"ॐ ह्रीं अर्हं णमो सव्वसाहूणं ॐ णमो भयवं महति महावीर वड्ढमाण बुद्धिरिसीणं।","iast":"Oṃ hrīṃ arhaṃ ṇamo savvasāhūṇaṃ oṃ ṇamo bhayavaṃ mahati mahāvīra vaḍḍhamāṇa buddhirisīṇaṃ"}],"mantra":[{"dev":"ॐ ह्रां ह्रीं ह्रूं ह्रौं ह्रः अ सि आ उ सा झ्रौं झ्रौं नमः स्वाहा।","iast":"Oṃ hrāṃ hrīṃ hrūṃ hrauṃ hraḥ a si ā u sā jhrauṃ jhrauṃ namaḥ svāhā"}],"method":{"en":"After bathing, wear yellow clothes, face north and set up the yantra. Worship the yantra with yellow flowers, then sit on a yellow seat facing east and, with a yellow rosary, practise the riddhi and the mantra 4,500 times or 100,000 times, completing it within seven months, so that the mantra is perfected.","es":"Después de bañarte, vístete de amarillo, mira al norte y coloca el yantra. Adora el yantra con flores amarillas; luego siéntate en un asiento amarillo mirando al este y, con un rosario amarillo, practica la riddhi y el mantra 4.500 veces o 100.000 veces, completándolo en siete meses, para que el mantra quede perfeccionado.","hi":"स्नान करके पीले रंग के वस्त्र धारण कर उत्तरदिशा की ओर मुख करके यंत्र स्थापित कर पीले पुष्पों से यंत्र की पूजा करके पीले आसन पर पूर्व दिशा की ओर मुख करके बैठकर पीले रंग की माला द्वारा चार हजार पाँच सौ बार अथवा एक लाख बार ऋद्धि तथा मंत्र का आराधन सात महीने में पूर्ण कर मंत्र सिद्ध करना चाहिए।","pt":"Depois do banho, vista roupas amarelas, volte-se para o norte e coloque o yantra. Adore o yantra com flores amarelas, depois sente-se em um assento amarelo voltado para o leste e, com um rosário amarelo, pratique o riddhi e o mantra 4.500 vezes ou 100.000 vezes, concluindo em sete meses, para que o mantra seja aperfeiçoado.","it":"Dopo il bagno, indossa abiti gialli, rivolgiti a nord e disponi lo yantra. Adora lo yantra con fiori gialli, poi siediti su un sedile giallo rivolto a est e, con un rosario giallo, pratica il riddhi e il mantra 4.500 volte oppure 100.000 volte, completandolo entro sette mesi, affinché il mantra sia reso perfetto.","gu":"સ્નાન કરી પીળાં વસ્ત્રો પહેરો, ઉત્તર તરફ મુખ રાખી યંત્રની સ્થાપના કરો. પીળાં ફૂલોથી યંત્રની પૂજા કરો, પછી પૂર્વ તરફ મુખ રાખી પીળા આસન પર બેસો અને પીળી માળા વડે ઋદ્ધિ અને મંત્રની 4,500 વાર અથવા 1,00,000 વાર સાધના કરો, સાત મહિનામાં પૂર્ણ કરો, જેથી મંત્ર સિદ્ધ થાય."},"benefit":{"en":"By recalling the riddhi, the mantra and the 48th verse 108 times every day for twenty-one days, or for forty-nine days, and keeping the yantra with you, the desired work is accomplished. By contemplating the name of the person you wish to bring under your influence, that person comes under your control. Wealth (Lakshmi) is gained.","es":"Recordando cada día 108 veces la riddhi, el mantra y el verso 48 durante veintiún días, o durante cuarenta y nueve días, y teniendo el yantra contigo, se cumple la obra deseada. Contemplando el nombre de la persona a quien se desea poner bajo la propia influencia, esa persona queda bajo tu control. Se alcanza la prosperidad (Lakshmi).","hi":"प्रतिदिन एक सौ आठ बार इक्कीस दिन तक अथवा उनचास दिन तक ऋद्धि, मंत्र तथा अड़तालीसवाँ काव्य का स्मरण करने और यंत्र को पास में रखने से मनोवांछित कार्य की सिद्धि होती है। जिसको अपने अधीन करना हो उस व्यक्ति का नाम चिन्तन करने से वह व्यक्ति अपने वश में होता है। लक्ष्मी प्राप्त होती है।","pt":"Recordando o riddhi, o mantra e o 48º verso 108 vezes por dia durante vinte e um dias, ou durante quarenta e nove dias, e mantendo o yantra consigo, realiza-se a obra desejada. Contemplando o nome da pessoa que se deseja trazer sob a sua influência, essa pessoa passa ao seu controle. Ganha-se riqueza (Lakshmi).","it":"Ricordando il riddhi, il mantra e il 48º verso 108 volte al giorno per ventuno giorni, oppure per quarantanove giorni, e tenendo con te lo yantra, l’opera desiderata si compie. Contemplando il nome della persona che si desidera portare sotto la propria influenza, quella persona viene sotto il tuo controllo. Si ottiene ricchezza (Lakshmi).","gu":"એકવીસ દિવસ અથવા ઓગણપચાસ દિવસ સુધી રોજ 108 વાર ઋદ્ધિ, મંત્ર અને 48મો શ્લોક યાદ કરવાથી અને યંત્ર પોતાની પાસે રાખવાથી ઇચ્છિત કાર્ય સિદ્ધ થાય છે. જેને પોતાના વશમાં કરવા ઇચ્છતા હો તેનું નામ ચિંતવવાથી તે વ્યક્તિ વશમાં આવે છે. લક્ષ્મી (ધન) પ્રાપ્ત થાય છે."}}],"memory":{"name":"Sushila Meghraj Lunawat","dates":{"en":"12 July 1935 – 12 May 2026","hi":"12 जुलाई 1935 – 12 मई 2026","es":"12 de julio de 1935 – 12 de mayo de 2026","pt":"12 de julho de 1935 – 12 de maio de 2026","it":"12 luglio 1935 – 12 maggio 2026","gu":"12 જુલાઈ 1935 – 12 મે 2026"},"story":{"en":["Grandmother: A Life of Prayer","Sushila Meghraj Lunawat was born on 12 July 1935. In the third standard she learned Sanskrit, and the sacred sounds she met that year stayed with her for the rest of her life.","Every morning she chanted the Bhaktamar Stotra three times. Then she set out for a walk through our farms with my grandfather, the soil beneath her feet and the verses still warm on her lips. Snakes sometimes came near, and after she chanted the mantra, they would quietly go away.","She fasted for fourteen years and observed Varshi Tap, the long, patient austerity that asks everything of the body and gives back a quiet mind. In her last days she took Santhara, the Jain vow of calm and conscious letting go, and on 12 May 2026 she attained Maha Samadhi, at the age of ninety.","She was loved by everyone who knew her. This book is for them, and for those who never met her but will read the verses she carried close."],"hi":["नानीजी: प्रार्थना से भरा जीवन","सुशीला मेघराज लूनावत का जन्म 12 जुलाई 1935 को हुआ। तीसरी कक्षा में उन्होंने संस्कृत सीखी, और वे पवित्र स्वर जीवन भर उनके साथ रहे। हर सुबह वे भक्तामर स्तोत्र का तीन बार पाठ करती थीं। फिर नानाजी के साथ हमारे खेतों में सैर पर निकलती थीं, पैरों के नीचे मिट्टी और होंठों पर वही श्लोक। कभी साँप पास आ जाते, तो उनके मंत्र-पाठ के बाद वे चुपचाप लौट जाते थे।","उन्होंने चौदह वर्षों तक उपवास किए और वर्षीतप की साधना की। अंतिम समय में उन्होंने संथारा लिया और 12 मई 2026 को नब्बे वर्ष की आयु में महासमाधि को प्राप्त हुईं। वे सभी की प्रिय थीं।"],"es":["Abuela: una vida de oración","Sushila Meghraj Lunawat nació el 12 de julio de 1935. En tercer grado aprendió sánscrito, y esos sonidos sagrados la acompañaron toda la vida. Cada mañana recitaba el Bhaktamar Stotra tres veces. Luego salía a caminar por nuestros campos con mi abuelo, con la tierra bajo los pies y los versos todavía en los labios. A veces se acercaban serpientes y, después de su recitación del mantra, se alejaban en silencio. Ayunó durante catorce años y observó el Varshi Tap. En sus últimos días tomó el Santhara y el 12 de mayo de 2026 alcanzó el Maha Samadhi, a los noventa años. Todos los que la conocieron la querían."],"pt":["Avó: uma vida de oração","Sushila Meghraj Lunawat nasceu em 12 de julho de 1935. Na terceira série aprendeu sânscrito, e os sons sagrados que conheceu naquele ano a acompanharam pelo resto da vida.","Toda manhã ela recitava o Bhaktamar Stotra três vezes. Depois saía para caminhar pelas nossas terras com meu avô, com a terra sob os pés e os versos ainda quentes nos lábios. Às vezes as serpentes se aproximavam e, depois que ela recitava o mantra, se afastavam em silêncio.","Jejuou por catorze anos e observou o Varshi Tap, a longa e paciente austeridade que exige tudo do corpo e devolve uma mente tranquila. Nos seus últimos dias tomou o Santhara, o voto jainista de desapego sereno e consciente, e em 12 de maio de 2026 alcançou o Maha Samadhi, aos noventa anos.","Foi amada por todos que a conheceram. Este livro é para eles, e para aqueles que nunca a conheceram, mas lerão os versos que ela carregou tão perto do coração."],"it":["Nonna: una vita di preghiera","Sushila Meghraj Lunawat nacque il 12 luglio 1935. In terza elementare imparò il sanscrito, e i suoni sacri che incontrò quell’anno la accompagnarono per tutta la vita.","Ogni mattina recitava il Bhaktamar Stotra tre volte. Poi usciva a passeggiare per i nostri campi con mio nonno, con la terra sotto i piedi e i versi ancora caldi sulle labbra. A volte i serpenti si avvicinavano e, dopo che lei aveva recitato il mantra, si allontanavano in silenzio.","Digiunò per quattordici anni e seguì il Varshi Tap, la lunga e paziente austerità che chiede tutto al corpo e restituisce una mente quieta. Negli ultimi giorni prese il Santhara, il voto giainista di distacco sereno e consapevole, e il 12 maggio 2026 raggiunse il Maha Samadhi, a novant’anni.","Fu amata da tutti quelli che la conobbero. Questo libro è per loro, e per chi non l’ha mai incontrata ma leggerà i versi che portava così vicino al cuore."],"gu":["નાની: પ્રાર્થનાથી ભરેલું જીવન","સુશીલા મેઘરાજ લૂણાવતનો જન્મ 12 જુલાઈ 1935ના રોજ થયો હતો. ત્રીજા ધોરણમાં તેમણે સંસ્કૃત શીખ્યું, અને તે વર્ષે જે પવિત્ર સ્વરો તેમને મળ્યા તે જીવનભર તેમની સાથે રહ્યા.","દરરોજ સવારે તેઓ ભક્તામર સ્તોત્રનો ત્રણ વાર પાઠ કરતાં. પછી નાનાજી સાથે અમારાં ખેતરોમાં ફરવા નીકળતાં, પગ નીચે માટી અને હોઠ પર હજુ ગરમ શ્લોકો. ક્યારેક સાપ નજીક આવી જતા, અને તેમના મંત્રપાઠ પછી તેઓ ચુપચાપ ચાલ્યા જતા.","તેમણે ચૌદ વર્ષ સુધી ઉપવાસ કર્યા અને વર્ષીતપની સાધના કરી, એ લાંબી, ધીરજભરી તપસ્યા જે શરીર પાસે બધું માગે છે અને બદલામાં શાંત મન આપે છે. અંતિમ દિવસોમાં તેમણે સંથારો લીધો, શાંત અને સભાન રીતે છોડી દેવાનું જૈન વ્રત, અને 12 મે 2026ના રોજ નેવું વર્ષની ઉંમરે તેઓ મહાસમાધિને પ્રાપ્ત થયાં.","તેમને ઓળખનારા સૌને તેઓ પ્રિય હતાં. આ પુસ્તક તેમના માટે છે, અને એવા લોકો માટે પણ જેઓ તેમને ક્યારેય મળ્યા નથી પણ તેમણે હૃદયની નજીક રાખેલા શ્લોકો વાંચશે."]},"dedication":{"en":{"role":"Grandmother","line":"You prayed every day, and taught us, without a word, that devotion fits inside an ordinary morning.","line2":"This book is for you, and for everyone who will open it and find a quiet place to begin.","line3":"For the young generation of the Zabak family, and for everyone who seeks divine blessings.","draft":false},"hi":{"role":"नानीजी","line":"आप हर दिन प्रार्थना करती थीं, और बिना कुछ कहे हमें सिखा गईं कि भक्ति एक साधारण सुबह में भी समा सकती है।","line2":"यह पुस्तक आपके लिए है, और उन सबके लिए जो इसे खोलेंगे और आरंभ करने के लिए एक शांत स्थान पाएँगे।","line3":"Zabak परिवार की युवा पीढ़ी के लिए, और उन सभी के लिए जो दिव्य आशीर्वाद की खोज में हैं।","draft":false},"es":{"role":"Abuela","line":"Rezabas cada día, y nos enseñaste, sin una palabra, que la devoción cabe en una mañana cualquiera.","line2":"Este libro es para ti, y para todos los que lo abran y encuentren un lugar tranquilo para empezar.","line3":"Para la joven generación de la familia Zabak, y para todos los que buscan bendiciones divinas.","draft":false},"pt":{"role":"Avó","line":"Você rezava todos os dias e nos ensinou, sem uma palavra, que a devoção cabe numa manhã comum.","line2":"Este livro é para você, e para todos que o abrirem e encontrarem um lugar tranquilo para começar.","line3":"Para a jovem geração da família Zabak, e para todos que buscam bênçãos divinas.","draft":false},"it":{"role":"Nonna","line":"Pregavi ogni giorno, e ci hai insegnato, senza una parola, che la devozione sta dentro una mattina qualunque.","line2":"Questo libro è per te, e per tutti coloro che lo apriranno e troveranno un luogo tranquillo da cui iniziare.","line3":"Per la giovane generazione della famiglia Zabak, e per tutti coloro che cercano benedizioni divine.","draft":false},"gu":{"role":"નાની","line":"તમે દરરોજ પ્રાર્થના કરતાં, અને એક પણ શબ્દ બોલ્યા વિના અમને શીખવી ગયાં કે ભક્તિ એક સાધારણ સવારમાં પણ સમાઈ શકે છે.","line2":"આ પુસ્તક તમારા માટે છે, અને એ સૌ માટે જેઓ તેને ખોલશે અને શરૂઆત કરવા માટે એક શાંત સ્થળ મેળવશે.","line3":"Zabak પરિવારની યુવા પેઢી માટે, અને એ સૌ માટે જેઓ દિવ્ય આશીર્વાદની શોધમાં છે.","draft":false}}},"book":{"url":"https://shivtranslators.com/wp-content/uploads/2026/11/Bhaktamar_Book_FINAL_406pp_WEB_for_Shiv_Translators.pdf","site":"https://shivtranslators.com/books-and-apps/","edition":"November 2026","pages":406,"dir":"book/","toc":[[1,"Cover",1],[1,"Copyright and sharing",2],[1,"In loving memory",3],[1,"Preface",7],[1,"A note for the reader",9],[1,"Part One · Bhaktamar Stotra (48 verses)",11],[1,"Part Two · Uvasaggaharam Stotra",252],[1,"Part Three · Chaityavandana",258],[1,"Part Four · Hanuman Chalisa",292],[1,"Part Five · Pratikraman",336],[1,"Part Six · Vidhan Vidhi and Jin Sahasranama",382],[2,"Vidhan Vidhi (the forty-eight lamps)",383],[2,"Shri Jin Sahasranama Stotra (1008 names)",385],[1,"Part Seven · Days and Planets",398],[2,"Mantras for the seven days and the planets",399],[1,"Our memories of Grandmother",402],[1,"Gratitude",403],[1,"May kindness follow prayer",405],[1,"A few words from me",406]],"verses":[12,17,22,27,32,37,42,47,52,57,62,67,72,77,82,87,92,97,102,107,112,117,122,127,132,137,142,147,152,157,162,167,172,177,182,187,192,197,202,207,212,217,222,227,232,237,242,247]}};
